import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Дмитрію, ігумену Прилуцькому, Вологодському","e":"Akathist to our Venerable Father Demetrius, Abbot of Prilutsk near Vologda","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, преподо́бне о́тче наш Дими́тріє, дру́же і собесі́дниче дру́га Бо́жия преподо́бнаго Се́ргия і оте́чествія твоєго́ при́сний засту́пниче, прийми́ от нас с любо́вію приноси́моє тебі́ хвале́бноє пі́ніє і, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгел о́бразом, а́ще і челові́к по єстеству́, бил єси́ преподо́бне о́тче Дими́тріє: а́нгельськую бо чистоту́ стяжа́л єси́ на землі́, і а́нгельською красото́ю лице́ твоє́ цветяше, я́ко всім видевшим тя чуди́тися благолі́пію твоєму́. Тім же, я́ко ізбра́нника Бо́жия благолі́пнаго душе́ю і ті́лом, ублажа́єм тя пі́сньми си́ми:","Ра́дуйся, благочести́вих роди́телей пречестно́є порожде́ніє.","Ра́дуйся, гра́да Переяславля свято́є прозябе́ніє.","Ра́дуйся, Украї́нськия страни́ духо́вноє украше́ніє.","Ра́дуйся, єва́нгельськаго по Бо́зі житія́ ревни́телю.","Ра́дуйся, от ю́них літ жи́зні твоєя́ єди́наго Христа́ вседу́шно возлюби́вий.","Ра́дуйся, бога́тство тлі́нноє і ку́плю вре́менную презрі́вий.","Ра́дуйся, серафи́мською любо́вію ко Го́споду се́рдце твоє́ воспламенивий.","Ра́дуйся, да́ри Свята́го Ду́ха в ду́шу твою́ досто́йно восприя́вий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дівше роди́теліє твоя́, преподо́бне о́тче, я́ко не прилежало се́рдце твоє́ к бога́тству земно́му, но я́ко от млади́х ногте́й ти предпоче́л єси́ іска́ти єди́наго на потре́бу, є́же служи́ти і благоугожда́ти Христу́ чи́стим і непоро́чним житіє́м, премно́го удивля́хуся таково́му твоєму́ благонравію і ра́достно воспіва́ху Бо́гу, в ю́ності си́це тя укріпи́вшему, благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний стяжа́в, уразумі́л єси́ до́брі, о́тче Дими́тріє, указуємий Спаси́телем ми́ра путь к ви́сшеє соверше́нству духо́вному. Тім же по сме́рті роди́телей твої́х, а́біє ку́плю вре́менную оста́вил єси́ і все бога́тство твоє́ ни́щим расточи́л єси́, себе́ облегча́я к неприкоснове́нному тече́нію во слід Христа́. Сего́ ра́ди ублажа́єм тя такови́ми богохвальними словеси́:","Ра́дуйся, подви́жниче Бо́жий, ми́ра красота́ми не прельсти́вийся.","Ра́дуйся, нищету́ во́льную Христа́ ра́ди возлюби́вий.","Ра́дуйся, бога́тство мно́гоє меньшим бра́тіям Христо́вим раздававий.","Ра́дуйся, нищія і убо́гія от імі́нія твоєго́ удовли́вий.","Ра́дуйся, наги́я одевий і гла́дния напита́вий.","Ра́дуйся, вдови́цям і сирота́м оте́ць і благоді́тель би́вий.","Ра́дуйся, крест Христо́в носи́ти усе́рдно возжела́вий.","Ра́дуйся, смире́ніє Христо́во в ду́шу твою́ насади́вий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла духо́вная сви́ше от Го́спода тебі́ дарова́ся преподо́бне о́тче, єгда́ в постриже́нії і́ночестім а́нгельський о́браз восприя́л єси́ і вся́коє плотсько́є мудрова́ніє соверше́нно отложи́л єси́, я́ко би́ти тебі́ воістинупоследователем Христо́вим, на Христа́ бо єди́наго при́сно взира́л єси́ у́мнима очи́ма душі́ твоєя́ і Єго́ за́повіді святи́є ви́ну імі́л єси́ пред собо́ю, я́ко світи́льник путеводя́щий, зови Єму́ от любве́ те́плия: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я попече́ніє о спасе́нії душі́ твоєя́, безмо́лвія возжела́л єси́, преподо́бне о́тче, і на мі́сті блатнем і пусти́ннім близ гра́да Переяславля поселился єси́, єди́н єди́ному Христу́ рабо́тая в пості́ і моли́твах: оба́че не утаї́ся житіє́ твоє́ преподо́бноє от сограждан твої́х, і́же прихожда́ху к тебі́, о́вії моли́тв і благослове́нія от тебе́ прося́, о́вії наста́витися во спасе́ніє от теб'я́ жела́я, іні́ї же жи́тельствовати с тобо́ю хотя́ху под твої́м духо́вним руководительством: ти же гряду́щих к тебі́ не отгонял єси́, но спасе́нію душ челові́чеських служи́л єси́, є́же воспомина́я, хвале́бно вопіє́м ті:","Ра́дуйся, учи́телю благоче́стія, приме́ром житія́ твоєго́ всіх поучавий.","Ра́дуйся, наста́вниче богому́дрія, словеси́ твої́ми богодухнове́нними ученики́ твоя́ во спасе́ніє назида́вий.","Ра́дуйся, і́ночества богоуго́днаго пра́вило ізві́стноє.","Ра́дуйся, путі́ ті́снаго, во Ца́рствіє Небе́сноє ві́дущаго, указа́телю неле́стний.","Ра́дуйся, єва́нгельських за́повідей ві́рний ісполни́телю.","Ра́дуйся, непоколеби́мий сто́лпе Правосла́вія.","Ра́дуйся, сотвори́вий і научи́вий і ве́лій нарече́нний во Ца́рствії Небе́снім.","Ра́дуйся, со усе́рдієм послужи́вий ко спасе́нію мно́гих душ челові́чеських.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рноє треволне́ніє жите́йськаго мо́ря безбі́дно препли́л єси́, всеблаже́нне о́тче, і в ти́хоє приста́нище пусти́ні дости́гл єси́. В ней же оби́тель і́ноком возгради́л єси́ во і́м'я святи́теля і чудотво́рця Никола́я і сам освяще́нія ієре́йськаго сподо́бился єси́, ігу́мен богому́дрий оби́телі твоєя́ бив, кро́тко паси́й Бо́гом вруче́нния тебі́ слове́сния о́вці і немо́лчно воспіва́я ку́пно с ни́ми хвале́бную піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав о ди́вній красоті́ лиця́ твоєго́, о́тче Дими́тріє, єди́на от імени́тих боляринь гра́да Переяславля возжела́ла наслади́тися лицезрі́нія твоєго́ і сего́ ра́ди при́йде ко келії твоє́й, в ню же око́нцем прини́кнув, узрі́ тя на моли́тві стоя́ща і сві́том небе́сним облиставаєма, сама́ же а́біє всім ті́лом разслабі́ і па́дши я́ко ме́ртва, на землі́ лежа́ше. Ти же, послушествуя проше́нію бра́тії твоє́й, моли́твою твоє́ю ісціли́л єси́ ю і поучил, да про́чеє уцеломудриться і не назира́єть чужди́я красоти́, тім же і ми, чту́ще такову́ю чистоту́ душі́ твоєя́, вопіє́м ті си́це:","Ра́дуйся, світи́льниче Бо́жия благода́ті, дара́ми Ду́ха Свята́го сві́тло блиста́ющий.","Ра́дуйся, єще́ на землі́ сві́том небе́сним озаре́нний.","Ра́дуйся, сві́том лиця́ твоєго́ ве́лію сві́тлость душі́ твоєя́ проявивий.","Ра́дуйся, о́ним сві́том жену́ нескромную уцілому́дривий.","Ра́дуйся, словеси́ твої́ми духо́вними до́брі ю поучивий.","Ра́дуйся, кри́не ді́вства і чистоти́, на землі́ процві́тшій.","Ра́дуйся, красоту́ лиця́ твоєго́ заві́сою і́ночеськаго куколя сокривавий от нечи́стих воззреній оче́с челові́чеських.","Ра́дуйся, опа́сно себі́ храни́вий от іскуше́нія.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Богосві́тлоє світи́ло бив, о́тче Дими́тріє вели́каго світи́льника пусти́ні Ра́донежськия, богоно́снаго Се́ргия, по́двига єси́ посіти́ти тя в безвестней і бла́тній пусти́ні живу́щаго: єго́ же с любо́вію о Христі́ прия́л єси́ і духо́вним собеседованієм с ним утешился єси́, і от того́ вре́мене друг при́сний і сотаїнник єму́ соді́лался єси́, ни́ні же вку́пі с ним предстої́ши небе́сному престо́лу Трієди́наго Бо́га і сла́дці поє́ши Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя, преподо́бне о́тче Дими́тріє к богоно́сному отцю́ Се́ргію любо́во ве́лію о Христі́ стяжа́вшаго, на собесі́дованіє к нему́ духо́вноє от пусти́ні твоєя́ пешеходившаго і с ним вку́пі бді́нія всено́щния совершавшаго, при них же лучина свіщи́ вам заменяше, моли́тва же ва́ша, я́ко пла́мень о́гненний, до небе́с досяза́ше, диві́мся таково́му содружеству твоєму́ с вели́ким уго́дником Бо́жиїм і си́це тебі́ зове́м:","Ра́дуйся, дру́же святи́х, при́сний Бо́гу.","Ра́дуйся, спостниче і собесі́дниче преподо́бнаго Се́ргия.","Ра́дуйся, всеукраї́нськаго засту́пника і моли́твенника люби́мий сомоли́твенниче.","Ра́дуйся, от уст Сергієвих глубину́ прему́дрости духо́вной почерпнувий.","Ра́дуйся, ве́лію любо́в о Христі́ к нему́ стяжа́вий.","Ра́дуйся, возше́дий на висоту́ соверше́нства духо́внаго.","Ра́дуйся, проникий во глубину́ смире́нія свята́го.","Ра́дуйся, небе́сний челові́че, во пло́ті бесплотним поревнова́вий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дника тя благоумиленнаго позна́в о́тче Дими́тріє, благові́рний вели́кий князь Дими́трій зіло́ тя возлюби́ і отця́ духо́внаго себі́ сотвори́, восприє́мником же от свята́го креще́нія єдиного от синовей свої́х тя ізбра́ да бу́деши при́сний наста́вник і моли́твенник єму́ со ча́ди: ти же, преподо́бне, не возгордился єси́ толи́кою любо́вію к тебі́ вели́каго кня́зя Украї́нськаго, но па́че преуспіва́л єси́ во святі́м смире́нії, зови́й просла́вльшему тя Влади́ці Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ доброді́телей твої́х світ ве́лій во всю страну́ Украї́нськую, преподо́бне о́тче наш Дими́тріє, і мно́зі прихожда́ху к тебі́ іздале́ча наслади́тися богодухнове́нних твої́х уче́ній: би́ша бо уста́ твоя́ полна́ сла́дкаго уче́нія духо́внаго, язи́к же твой, я́ко трость кни́жника скоропи́сця, написа́вшаго на сердця́х челові́чеських словеса́ жи́зні ві́чния. Тім же, я́ко благоумиленнаго учи́теля і к покая́нію ді́йственнаго возбудителя, восхваля́єм тя по достоя́нію си́це:","Ра́дуйся, врачу́ благоїску́сний неду́гов душе́вних.","Ра́дуйся, возбудивий к покая́нію спящия со́вісти.","Ра́дуйся, ум'ягчивий ко ісправле́нію окамене́нния се́рдця.","Ра́дуйся, і́ноков і миря́н ко спасе́нію ві́рний руководи́телю.","Ра́дуйся, о́браз кро́тости духо́вний.","Ра́дуйся, пра́вди Бо́жієй нелицеприя́тний провозві́стниче.","Ра́дуйся, си́льних ми́ра, о пра́вді нерадивших, небоя́зненний обличи́телю.","Ра́дуйся, оби́димих і гони́мих многомо́щний засту́пниче.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рці."]},{"h":"Кондак 7","ps":["Хоті́ніє усе́рдноє імі́л єси́, преподо́бне о́тче, да в безмо́лвії невозбра́нно порабо́таєши Бо́гу, і сего́ ра́ди убіга́я молви́ приходивших к тебі́ люде́й, оста́вил єси́ та́йно оби́тель твою́ і град оте́чествія твоєго́ і со ученико́м твої́м Пахомієм удали́лся єси́ в преді́ли Волого́дськия, в пусти́ню безлюдную, в ней же келію себі́ ма́лу соорудив, і та́мо пребива́л єси́ в по́двизіх пусти́нних, немо́лчно воспіва́я Христу́ Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую оби́тель і́ночеськую, зачинаємую в пусти́ні, ви́дівше окре́стнії жи́теліє грубостію нра́ва содержи́ми, гневахуся на тя, преподо́бне о́тче, і поноша́ху тя, я́ко поселился єси́ на землі́ їх. Ти же по єва́нгельському Христо́ву глаго́лу мі́ста гні́ву не уступая, отше́л єси́ от тоя́ пусти́ні і ко гра́ду Вологде прибли́зился єси́, в предгра́дії єго́ на Прилуціх поселитися возжела́в, да честву́єм тя, я́ко отця́ і первонача́льника і́ноков волого́дських, і песенно тебі́ вопіє́м:","Ра́дуйся, пустиннолюби́вая го́рлице, от шу́ма мирська́го в благооти́шіє пусти́ні отлеті́вшая.","Ра́дуйся, незло́бивая голуби́це, гні́вом неразу́мних челові́к не уязвленная.","Ра́дуйся, му́дрий стра́нниче, іски́й оте́чествія го́рняго.","Ра́дуйся, худиє і многошвенния ри́зи носи́вий.","Ра́дуйся, вери́гами желі́зними ті́ло твоє́ обложи́вий.","Ра́дуйся, крест Христо́в, я́ко ору́жіє непобіди́моє, спу́тника себі́ стяжа́вий.","Ра́дуйся, іко́ну Пресвяти́я Богоро́диці, я́ко сті́ну огражде́нія, всегда́ с собой імі́вий.","Ра́дуйся, пусти́ню бесплодную благода́тно уплодоносивий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць бил єси́ во гра́ді Вологде, преподо́бне о́тче наш Дими́тріє, ни́ні же при́сний предста́тель і засту́пник єго́, ви́дів бо сей град, церква́ми святи́ми благоукраше́нний, возлюби́л єси́ єго́, і по умоле́нію жи́телей єго́ на Прилуціх в предгра́дії мі́сто уєдине́нноє обрі́т, на нем всели́лся єси́, і честни́й крест рука́ма свої́ма соді́лав, водрузи́л єси́, нача́ло оби́телі Спа́совой полага́я і при́сно воспіва́я распе́ншемуся на кресті́ Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, преблаже́нне о́тче, о вре́менних ве́щіх не заботился єси́, і оби́тель твою́ на Прилуціх не толи́ко бога́тством, коли́ко слеза́ми і по́двигами твої́ми моли́твенними созида́л єси́, всеці́ло упова́я на Спа́са Христа́, я́ко Сам препита́єть тя с бра́тією твоє́ю: і та́ко бисть по ві́рі і моли́тві твоє́й: ні в чесо́м бо лише́н бил єси́, но во всіх потре́бних к яситію ізобиловал єси́ Про́мислом Бо́жиїм ди́вним. О сем тя хва́лим і взива́єм си́це:","Ра́дуйся, с по́сохом странничеським во град Вологду прише́дий.","Ра́дуйся, в нем второ́є оте́чествіє себі́ обріти́й.","Ра́дуйся, любо́вію о Христі́ крі́пці єго́ возлюби́вий.","Ра́дуйся, оби́тель Спа́сову в предгра́дії єго́ сооруди́вий.","Ра́дуйся, по́двиги твої́ми сію́ просла́вивий.","Ра́дуйся, я́ко оте́ць чадолюби́вий, моли́твенно назида́я ча́да твоя́ духо́вния.","Ра́дуйся, проро́че ди́вний, бу́дущая, я́ко настоя́щая, прови́дівий.","Ра́дуйся, ціли́телю безме́здний, боля́щих моли́твою твоє́ю ісціли́вий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Все а́нгели небе́снії і святи́я лиці́ сріто́ша тя ра́достно, преподо́бне о́тче Дими́тріє, єгда́ свята́я твоя́ душа́, кончи́ною преподо́бною разрешившаяся от соу́за плотська́го, восхожда́ше во оби́телі го́рнія: і Сам Творе́ць а́нгелов і Святи́й святи́х, Христо́с Госпо́дь, тобо́ю от ю́ности возлю́бленний, увінча́ тя вінце́м нетлі́нния сла́ви і сопричте ли́ку святи́х, ви́ну воспіва́ющих Єму́ піснь хвали́ і славосло́вія: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й челові́чеських благословесіє не довлі́єть к досто́йноє прославле́нію мно́гих по́двигов твої́х, преподо́бне о́тче наш Дими́тріє, і́ми же житіє́ твоє́ свято́є, я́ко цвіта́ми, благоукраша́ється і духо́вно бла́го-уха́єть, от ра́ннія бо ю́ности твоєя́ і до ста́рости масти́тия неосла́бно Бо́гу благоугождал єси́ і во́лю Єго́ святу́ю при́сно твори́л єси́, чесо́ ра́ди кончи́ну пра́ведную, я́ко віне́ць по́двигом твої́м, от Го́спода получи́л єси́, і благоуха́ніє сла́достноє от моще́й твої́х а́біє по кончи́ні твоє́й істече́, всю оби́тель твою́ облагоухав: тім же і ми, таково́є преставле́ніє твоє́ прославля́юще, зове́м ті си́це:","Ра́дуйся, вели́кий уго́дниче Бо́жий, от землі́ преше́дий к оби́телем небе́сним.","Ра́дуйся, возду́х облагоуха́вий восхожде́нієм душі́ твоєя́ святи́я в селе́нія го́рняя.","Ра́дуйся, оби́тель твою́ освяти́вий многоціле́бними твої́ми моща́ми.","Ра́дуйся, я́ко душа́ твоя́ в ру́ці Бо́жієй храни́ма єсть на ві́ки.","Ра́дуйся, я́ко про́чеє не прико́снеться тебі́ ні скорб, ні болі́знь.","Ра́дуйся, я́ко мо́щі твоя́ святи́я ісціле́ніє благода́тния ві́рним істоча́ють.","Ра́дуйся, я́ко іспроси́л єси́ от Го́спода власть над ду́хи нечи́стия.","Ра́дуйся, я́ко предста́тельством твої́м свобожда́єши челові́ки от зла́го їх наси́лія.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спа́са Христа́ умоля́єши за град твой і лю́ди твоя́, преподо́бне чудотво́рче Дими́тріє, сіє́ бо показа́л єси́ я́ві во дні обложе́нія ратного Во́логди, я́влься єди́ній благочести́вій іноки́не, с двуми сві́тлими белоризцями обходя́ сті́ни гра́да і утвержда́я їх, да непоколеби́ми пребу́дуть от нападе́нія вражде́бния ра́ти, я́же вско́рі со студо́м отступи́ от гра́да, не возмо́же єго́ побіди́ти, лю́ди же вологостії прославля́ху і воспіяху Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Го́спода Ісу́са ві́рний раб і уго́дник бил єси́, преподо́бне о́тче Дими́тріє, і от Него́ получи́во ве́лію благода́ть, царю́ земно́му, благові́рному вели́кому кня́зю Іоа́нну, побіди́ти ца́рство Казанськоє помо́гл єси́, я́влься среди́ полко́в украї́нських і побора́я їм ага́ряни нечести́вия по́мощію небе́сною вско́рі взя́ти сто́льний град їх Каза́нь. Сіє́ явле́ніє твоє́ ми вспоминая, благода́рственно зове́м ті:","Ра́дуйся, свя́тче Бо́жий, со святи́м обита́яй, і за грі́шния Бо́га умоля́яй.","Ра́дуйся, уго́дниче Христо́в, от го́рних висо́т к земноро́дним ми́лостиво приникаяй.","Ра́дуйся, любо́в твою́ к оте́чествію земно́му і по сме́рті сохрани́вий.","Ра́дуйся, по́мощ твою́ святу́ю страні́ Украї́нській чуде́сно яви́вий.","Ра́дуйся, я́ко архистрати́г воїм Украї́нським на ага́ряни поборавий.","Ра́дуйся, град Каза́нь взя́ти їм ди́вно помогавий.","Ра́дуйся, град твой Вологду от нападе́ній ра́тних мно́жицею ізба́вивий.","Ра́дуйся, сострада́нія преіспо́лненний і в ми́лості бога́тий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше моле́бноє ми́лостиво прийми́ уго́дниче Бо́жий, преподо́бне о́тче Дими́тріє, і щедро́ти твоя́ ціле́бния да́руй нам в неду́зіх на́ших: тебі́ бо стяжа́хом врача́ ізря́днаго і немздоприїмнаго, при́сно гото́ваго помога́ти нам і ісціля́ти неду́ги на́ша да́нною ті от Го́спода благода́тію. Ю́же прославля́я от благода́рния душі́, вопіє́м тобо́ю благоді́ющему нам Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с твої́х благода́тно просвіща́єши, свя́те чудотво́рче Дими́тріє, не то́кмо град твой і оби́тель твою́, но і всю страну́ Украї́нськую. В ней же, я́ко вели́кий уго́дник Бо́жий, усе́рдно прославля́єшися он ві́рних, бли́жнім і да́льним щедро́ти твоя́ ціле́бния ми́лостиво да́руяй, да всі ра́достно взива́єм си́це:","Ра́дуйся, великоімени́тий всеукраї́нський наш засту́пниче.","Ра́дуйся, ангелоравний челові́че.","Ра́дуйся, звіздо́ у́тренняя, мрак нече́стія прогоня́ющая.","Ра́дуйся, забра́ло необори́моє от враг ви́димих і неви́димих.","Ра́дуйся, молящимся тебі́ на по́мощ ускоряяй.","Ра́дуйся, о́гненноє запале́ніє призива́нієм і́мене твоєго́ угаша́яй.","Ра́дуйся, безпомо́щних ско́рий помо́щниче.","Ра́дуйся, благода́ті Бо́жієй многоціле́бний істо́чниче.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рці."]},{"h":"Кондак 12","ps":["Благода́ті причастноє ізображе́ніє лиця́ твоєго́ дарова́л єси́ лю́дем твої́м в благослове́ніє і утіше́ніє, преподо́бне о́тче Дими́тріє, і от Него́ чудеса́ мно́гая соверши́л єси́, я́ко чудотво́рець пресла́вний. Тім же с ві́рою і любо́вію поклоня́ємся іко́ні твоє́й, святи́й наш предста́телю, і, велича́я возвели́чившаго тя Христа́ Го́спода, хвале́бно зове́м єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая твоя́ чудеса́ і ве́ліє сострада́ніє твоє́ к лю́дем, ті сро́дним, Дими́тріє богоблаже́нне, благоумиле́нно про́сим тя, небе́снаго засту́пника на́шего: принеси́ за ни сердния моли́тви твоя́ ко Го́споду і іспроси́ нам кончи́ну житія́ благу́ю і непости́дную, да по́мощію твоє́ю свято́ю спасе́ніє ві́чноє унаслі́дуєм і вку́пі с тобо́ю водворі́мся та́мо, іді́же присіща́єть світ лиця́ Бо́жия і весели́ть вся от ві́ка пра́ведники. О сем тя мо́лим і зове́м:","Ра́дуйся, благоволе́нієм Пресвята́я Тро́йці осіне́нний.","Ра́дуйся, лицезрі́нія Пресвяти́я Богоро́диці удосто́єнний.","Ра́дуйся, А́гнцю Бо́жию послі́довавий на землі́.","Ра́дуйся, с ді́вственними ли́ки предстоя́й Єму́ на небесі́.","Ра́дуйся, со ізбра́нники Бо́жиїми покланя́яйся Творцю́.","Ра́дуйся, дерзнове́ніє моли́твенноє стяжа́вий к Небе́сному Отцю́.","Ра́дуйся, о нем же ра́дуються і Бо́га сла́в'ять челові́ци.","Ра́дуйся, душ і тіле́с на́ших благода́тноє врачева́ніє.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рці."]},{"h":"Кондак 13","ps":["О вели́кий чудотво́рче і ско́рий в біда́х помо́щниче, преподо́бне о́тче наш Дими́тріє! Тебі́ мо́лимся і тебі́ про́сим с ві́рою к любо́вію: прийми́ ми́лостивно сіє́ ма́лоє хвале́бноє пі́ніє, от усе́рдія нашаго тебі́ приноси́моє, і умоли́ Го́спода Бо́га в день стра́шнаго суда́ Єго́ поми́ловати нас і ізба́вити осужде́нія ві́чнаго, да сподо́бимся блаже́нния ча́сти одесну́ю Єго́ стоя́щих і ра́достно Єму́ воспоє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел о́бразом, а́ще і челові́к по єстеству́, бил єси́ преподо́бне о́тче Дими́тріє: а́нгельськую бо чистоту́ стяжа́л єси́ на землі́, і а́нгельською красото́ю лице́ твоє́ цветяше, я́ко всім видевшим тя чуди́тися благолі́пію твоєму́. Тім же, я́ко ізбра́нника Бо́жия благолі́пнаго душе́ю і ті́лом, ублажа́єм тя пі́сньми си́ми:","Ра́дуйся, благочести́вих роди́телей пречестно́є порожде́ніє.","Ра́дуйся, гра́да Переяславля свято́є прозябе́ніє.","Ра́дуйся, Украї́нськия страни́ духо́вноє украше́ніє.","Ра́дуйся, єва́нгельськаго по Бо́зі житія́ ревни́телю.","Ра́дуйся, от ю́них літ жи́зні твоєя́ єди́наго Христа́ вседу́шно возлюби́вий.","Ра́дуйся, бога́тство тлі́нноє і ку́плю вре́менную презрі́вий.","Ра́дуйся, серафи́мською любо́вію ко Го́споду се́рдце твоє́ воспламенивий.","Ра́дуйся, да́ри Свята́го Ду́ха в ду́шу твою́ досто́йно восприя́вий.","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, преподо́бне о́тче наш Дими́тріє, дру́же і собесі́дниче дру́га Бо́жия преподо́бнаго Се́ргия і оте́чествія твоєго́ при́сний засту́пниче, прийми́ от нас с любо́вію приноси́моє тебі́ хвале́бноє пі́ніє і, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Дими́тріє, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О свяще́нная главо́, преди́вний чудотво́рче, богоно́сне о́тче наш Дими́тріє! Усе́рдно припа́дающе к тебі́, мо́лимся: яви́, нам, смире́нним і грі́шним, многомо́щноє твоє́ заступле́ніє. Се бо гріх ра́ди на́ших, не і́мами дерзнове́нія ко Го́споду проси́ти Єго́ даро́в, нам благопотре́бних, но тебі́, моли́твенника к Нему́ благоприя́тного, предлага́єм і про́сим: іспроси́ нам у бла́гости Єго́ вся я́же на по́льзу душа́м і тілесе́м на́шим: ві́ру, пра́вду, наде́жду несумне́нну, любо́в нелицемі́рну, во іскуше́ніїх му́жество, в злострада́ніях терпі́ніє, в моли́твах постоя́нство, в благоче́стії преуспі́яніє, вожделі́нноє здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, дожди́ благовре́менни, жите́йських потре́б дово́льство, мир во днех на́ших і благослове́ніє сви́ше на вся́кая блага́я діла́ на́ша. Не забу́ди, чудотво́рче святи́й, ми́лостиво посіща́ти оби́тель свою́, гра́ди і ве́сі страни́ на́шея правосла́вния, сохраня́я і соблюда́я їх моли́твами твої́ми от вся́кого зла. Пом'яни́ всіх, ві́ру і любо́в к тебі́ іму́щих і і́м'я твоє́ моли́твенно призива́ющих, і во благи́х проше́нія їх ми́лостиво іспо́лни, осіня́я їх сви́ше святооте́чеським твої́м благослове́нієм. Єй свя́тче Бо́жий, не лиши́ і нас грі́шних твоєго́ многомо́щнаго заступле́нія, но сподо́би нас кончи́ну житія́ благу́ю улучи́ти і Ца́рствіє Небе́сноє унаслі́довати. Да воспоє́м і просла́вим ди́внаго во святи́х свої́х Бо́га на́шего, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Сви́ше от Бо́га, преподо́бне, / благода́ть прия́л єси́ духо́вную, / і от Него́ у́бо позна́лся єси́, блаже́нне, / Того́ ра́ди і ти ду́хом позна́л єси́ лу́чшая Єго́, / бу́дущаго ві́ка пребива́ніє, / і по́стничеськи іспита́вся во свої́х оби́теліх. / І ни́ні со а́нгели ликовству́я, / Спа́су всіх за ни моли́ся, свя́те Дими́тріє, да всі вопіє́м: / Сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 8","ps":["От ю́ности, преподо́бне, крест твой взем, Христу́ послі́довал єси́, / в моли́твах і поще́ніїх, во бді́ніїх же і злострада́ніїх плоть твою́ ізнуря́я. / Ті́мже і Всеви́дящеє О́ко твоя́ труди́ ви́дів, / чудеси́ тя прославля́єть, і всіх зва́ти тебі́ науча́єть: // ра́дуйся, преподо́бне о́тче Дими́тріє, по́стников удобре́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Дими́тріє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Інокентію, єпископу Іркутському","e":"Akathist to St Innocent, Bishop of Irkutsk","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ско́рий в ско́рбіх помо́щниче, святи́телю о́тче Інноке́нтіє, я́ко імі́я ве́ліє дерзнове́ніє пред Го́сподем, от вся́ких нас бід свобожда́й, да с ра́достію зове́м ті:","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгельському жи́тельству на небесі́х поревнова́л єси́, о́тче: по і́мені бо і житіє́ твоє́ непоро́чно бисть на землі́, сего́ ра́ди і возви́сился єси́ до лицезрі́нія Творця́ А́нгелов. Отню́дуже призира́я ви́ну на град сей і лю́ди, усли́ши нас, похва́льная восписующих ті сія́:","Ра́дуйся, неви́нностію А́гнця непоро́чнаго подража́тель би́вий;","Ра́дуйся, воздержа́нієм твої́м а́нгельськоє во пло́ті житіє́ яви́вий.","Ра́дуйся, я́ко а́нгел, Сиби́рськия це́ркве Бо́жия діла́ возвіща́яй;","Ра́дуйся, я́ко архистрати́г си́ли небе́сния, всіх прибіга́ющих к тебі́ от бід сохраня́яй.","Ра́дуйся, непоро́чности і невинности соіме́нний учи́телю;","Ра́дуйся, незло́бія і чистоти́ усе́рдний храни́телю.","Ра́дуйся, убеленний неви́нностію кри́не ра́йськаго прозябе́нія;","Ра́дуйся, умаще́нная чистото́ю ма́слина небе́снаго благослове́нія.","Ра́дуйся, у́ме небе́сних неізрече́нних благ наслажда́яйся;","Ра́дуйся, па́стирю, с му́дрими в ра́дость Пастиренача́льника своєго́ вше́дий.","Ра́дуйся, я́ко світ лиця́ Бо́жия я́сно на небесі́ смотря́єши;","Ра́дуйся, я́ко тім же сві́том осія́нний, притека́ющих к тебі́ неізрече́нно возвеселя́єши.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ві́дий Госпо́дь вели́ка тя би́ти світи́льника во страні́ язи́ков, благоволи́ сокри́ти род і оте́чество твоє́, да яви́шися в землі́ Хинстей, я́коже Мелхиседе́к в Ханаа́нстій, і уві́риши, я́ко не от челові́к прише́л єси́ к нам, но от Бо́га, Єму́ же поє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум просвіще́нний хотя́ імі́ти, богому́дре о́тче, от ю́ности ізбра́л єси́ в мі́сто образова́нія своєго́ ма́тер градо́в правосла́вния ві́ри на́шея і подви́жничества, да жив'я́ среди́ земни́х а́нгелов і взира́я на сконча́ніє жи́тельства їх, подража́тель яви́шися ві́рі їх; ті́мже і сам соді́лался єси́ небе́сним челові́ком. Сего́ ра́ди сли́шиши от нас сія́:","Ра́дуйся, виногра́де многопло́дний, в благораствореннем ю́зі возрасший;","Ра́дуйся, цві́те благово́нний, в Украї́ні процві́тшій.","Ра́дуйся, сла́во і удобре́ніє гра́да Ки́єва;","Ра́дуйся, красото́ і утіше́ніє отце́в Пече́рськия ла́ври.","Ра́дуйся, я́ко ізмла́да му́дрости приліжа́, Боже́ственноє писа́ніє я́сні ізви́кл єси́;","Ра́дуйся, я́ко отложи́во вся мирськи́я сла́сти, Христо́в яре́м носи́ти ізво́лил єси́.","Ра́дуйся, в ю́ності посвятивий в же́ртву прия́тну Го́споду себі́ самаго́;","Ра́дуйся, сохрани́вий невре́дно целому́дріє ді́вства драга́го.","Ра́дуйся, я́ко в земні́м учи́лищі небе́сния прему́дрости учи́вий;","Ра́дуйся, я́ко щито́м ві́ри вся разжже́нния лука́ваго стрі́ли угаси́вий.","Ра́дуйся, я́ко ізді́тська Бо́га возлюби́вий;","Ра́дуйся, я́ко за́повідій Єго́ нело́жний храни́тель би́вий.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою сви́ше позна́ тогда́ благові́рний цар непоро́чноє і свято́є жи́тельство твоє́, о́тче Бо́жий, і́же і ізбра́ тя во апо́стольськоє служе́ніє і предпосла́, я́ко пе́рвенця духо́внаго синоположе́нія, насажда́ти святу́ю ві́ру в землі́ язи́ков чужди́х, неві́дущих пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́єть тебі́, святи́телю о́тче Інноке́нтіє, вся страна́ Сиби́рськая вели́ка учи́теля і ди́вна во ві́рі наста́вника; сего́ ра́ди, я́ко до́бляго побо́рника ві́рним і ско́раго моли́твенника тя чту́ще, с весе́лієм і ра́достію да́ри тебі́ прино́сим такови́я: Ра́дуйся, свяще́нная главо́, ра́зума вода́ми напоя́єма;","Ра́дуйся, плод благоуха́нен житіє́м твої́м от ю́ности явля́яй.","Ра́дуйся, іскорени́телю терно́внаго служе́нія і́дольськаго;","Ра́дуйся, насади́телю лози́ правосла́вния ві́ри.","Ра́дуйся, но́вий апо́столе, облагоуха́вий ві́рою послі́днія конці́ Украї́ни;","Ра́дуйся, до́брий па́стирю, утверди́вий кра́сния но́ги своя́ на восто́ці ца́рства Сиби́ри.","Ра́дуйся, мра́чния страни́ просвіти́телю;","Ра́дуйся, душе́вния темноти озарителю.","Ра́дуйся, враго́во ві́ри Христо́ви разруши́телю;","Ра́дуйся, прельстителей душ христия́нських разителю.","Ра́дуйся, ідолослужи́тельних ста́рець му́дрость посрами́вий;","Ра́дуйся, му́дрих ві́ка сего́ мудрі́йший.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́ря зло́би древляго змі́я обуя́ ца́рство хи́нов, єгда́ не можа́ху отве́рзти ушеса́ ко глаго́лом Ца́рствія Христо́ва, тобо́ю, но́вий апо́столе, возвіща́ємим, і не хотя́ху прия́ти тя, втори́цею на преді́ліх їх я́вльшася, да умудриши я воспіва́ти єди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ві́дуще тя прему́дра учи́теля і і́стиннаго сказа́теля та́їн Бо́жиїх, прихожда́ху к тебі́ не то́чію ста́рці, но і ю́нії, в ни́хже ра́зум напечатлевал єси́ дре́внія і́стини Єва́нгельськия, сего́ ра́ди я́ко па́стиря, просвіти́теля і отця́ на́шего ублажа́юще, зове́м ті:","Ра́дуйся, ра́бе благи́й і ді́лателю до́брий;","Ра́дуйся, іскорени́телю злих і прогони́телю нече́стія бо́дрий.","Ра́дуйся, я́ко сугу́бу мзду небе́сную сугу́ба ра́ди путеше́ствія ко хином прия́л єси́;","Ра́дуйся, я́ко сподо́бился єси́ восприя́ти чуде́с дар і сла́ви віне́ць пресві́тел.","Ра́дуйся, апо́столу Па́влу в по́двизіх служе́нія своєго́ подража́вий;","Ра́дуйся, терпі́нію єго́ в науче́нії безкнижних ю́ношей послі́довавий.","Ра́дуйся, я́ко на па́жити ві́ри пра́вия і при істо́чниці води́ живи́я лю́ди твоя́ па́ствил єси́;","Ра́дуйся, я́ко на зла́ці кра́сні преби́ти твоєму́ ста́ду му́дре наста́вил єси́.","Ра́дуйся, світи́льниче всесві́тлий і вселюби́мий:","Ра́дуйся, па́че звізд ясні́йший і вожделі́ннійший.","Ра́дуйся, виногра́да живо́тнаго святопрозя́бший грозд, вино́ іска́пающий;","Ра́дуйся, святопома́занная главо́, честни́й наш учи́телю.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник превели́ких чуде́с яви́лся єси́ в землі́ на́шей, достославно о́тче, прия́л бо єси́, єще́ на землі́ ті жившу, власть неду́ги ізцеляти, по сме́рті же найпа́че просла́ви тя Бог мно́гими чудотворе́ньми, да всі чудоді́йствующему тобо́ю Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше жи́теліє Іркутстії святу́ю це́рков, в не́йже почива́ше нетлі́нноє і цельбоносноє ті́ло твоє́, уго́дниче Бо́жий, я́ко втору́ю купину́ в пла́мені су́щу, си́лою же твої́х моли́тв невре́дно сохраненную, просла́виша Бо́га; ті́мже і ми, ви́дяще о́ную дони́ні ці́лу, благолепну і я́ві пові́дающую зна́менія і чудеса́ твоя́, воспіва́єм тебі́ си́це:","Ра́дуйся, всю страну́ Сиби́рськую удиви́вий чудеси́, і́миже оби́тель твоя́ освяти́ся;","Ра́дуйся, оруженосець духо́вний, і́мже вся́ка зла́я страсть і болі́знь от ві́рних прого́ниться.","Ра́дуйся, я́ко ізлія́нієм чуде́с от Бо́га обогати́лся єси́;","Ра́дуйся, я́ко неоску́дний істо́чник ізцеленій яви́лся єси́.","Ра́дуйся, я́ко ста́ду твоєму́ по́мощ і заступле́ніє дава́єши;","Ра́дуйся, я́ко чуде́с сія́нії па́ству твою́ просвіща́єши.","Ра́дуйся, невреди́мо от огня́ сохрани́вий це́рков, в не́йже, жив сий, воздевал єси́ о спасе́нії люді́й преподо́бния ру́ці свої́;","Ра́дуйся, я́вственно тім свидетельствовавий, я́ко свя́то бисть почивавшеє в ней нетлі́нноє ті́ло твоє́.","Ра́дуйся, всім безпомо́щним прия́тноє попече́ніє;","Ра́дуйся, коєя́ждо не́мощі ско́рий і безме́здний врачу́.","Ра́дуйся, я́ко і всяк благопотре́бен дар от Го́спода просящим подава́єши;","Ра́дуйся, я́ко прославля́яй тя чудеси́ Бог тобо́ю всіх к Себі́ призива́єть.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Словеса́ апо́стольськая, є́же моли́тися о спасе́нії па́стви твоєя́, я́ко ієра́рх во у́шію своє́ю приє́м, не то́чію в жи́зні, но і по преставле́нії явля́єшися священноді́йствитель Боже́ственних тайн, увіря́я ві́рующих в непреста́ннім ходатайстве о тре́бующих твоєя́ по́мощі і воспіва́ющих Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ пречу́дно, архієре́ю Бо́жий, єгда́ втори́цею яви́вийся зі́льні стра́ждущему, уда́рив в пол жезло́м, я́звою на дре́ві того́ мі́ста уврачева́л єси́ душе́вную я́зву омраче́ннаго неві́рієм; а́біє бо позна́ тя би́ти благода́тнаго врача́ і сла́в'я тя, вопія́ше:","Ра́дуйся, ієра́рше благи́й і ві́рний;","Ра́дуйся, ді́лателю неутоми́мий виногра́да Христо́ва.","Ра́дуйся, служи́телю Госпо́день, о ві́рних умоля́яй;","Ра́дуйся, наста́вниче, грі́шних к небесі́ направля́яй.","Ра́дуйся, та́їн Бо́жиїх і́стинний строї́телю;","Ра́дуйся, моли́твенних рук непреста́нний воздевателю.","Ра́дуйся, я́ко ізбавля́єши от неві́рія;","Ра́дуйся, я́ко ізціля́єши от малоду́шія.","Ра́дуйся, укріпле́ніє му́дростію благоду́шія;","Ра́дуйся, просвіще́ніє сві́тлостію благоче́стія.","Ра́дуйся, прему́дрий пропові́дателю;","Ра́дуйся, пресла́дкий обличи́телю.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́ще ні́когда сановитії гра́да сего́ в неподо́бноє вре́м'я ви́діти і любопи́тною десни́цею осяза́ти нетлі́нієм уже́ процветавшия святи́я мо́щі твоя́, святи́телю Христо́в, потща́шася прикри́ти дерзнове́ніє своє́ благослове́нієм архипа́стиря: но ти, чистоти́ люби́телю і ві́ри рачи́телю, не восхоті́л єси́ яви́ти себі́ їм, науча́я тім не високому́дрствовати, но в смиренному́дрії пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і пресла́вноє чу́до показа́ нам тобо́ю на землі́ всіх чуде́с Творе́ць і Влади́ка, єгда́ тебе́ ра́ди преміни́шася єстества́ уста́ви; среди́ бо лі́та і зно́я мраз і і́ней яви́стася при цільбоно́снім гро́бі твоє́м, є́же зна́менієм бисть, я́ко а́ще і у́мерл єси́ на землі́ пло́тію, но душою во ви́шнім селе́нії всегда́ жив сий, те́плим свої́м хода́тайством посо́бствуєши вопію́щим тебі́:","Ра́дуйся, смиренному́дрія сто́лпе необори́мий;","Ра́дуйся, презренную го́рдость низлага́яй.","Ра́дуйся, люб'ящия чистоту́ душ соблюда́яй;","Ра́дуйся, грі́шних к покая́нію воззива́яй.","Ра́дуйся, ді́лателю чуде́с многославних;","Ра́дуйся, хода́таю і пода́телю дарова́ній многоразли́чних.","Ра́дуйся, заблу́ждших і осліпле́нних наста́вниче;","Ра́дуйся, любопитних і маловерних обличи́телю.","Ра́дуйся, я́ко сла́ву земну́ю в уме́ти вміни́л єси́;","Ра́дуйся, я́ко честь Бо́га Ви́шняго всім се́рдцем взиска́л єси́.","Ра́дуйся, і́мже о си́лі Бо́жієй єстества́ уста́ви преміня́ються;","Ра́дуйся, і́мже по́мисли зло́бнії прогоня́ються.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нно бі ви́діти, ка́ко три по єстеству́ мощная живо́тная, си́лою, да́нною ті сви́ше, обезсилеша, я́ко не можа́ху довлещі до оби́телі твоєя́ єди́наго пу́тника із жи́телей гра́да сего́, вразумля́юща тім, я́коже дре́вле осля́ Валаа́ма, да не і́деть в да́льнюю страну́, не прия́в от тебе́ путеваго напутствія, а́біє же, воспом'яну́в отложенний обі́т свой, позна́ тя скорого помо́щника і возопи́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь всего́ себе́ іспо́лнив любве́ нелицемі́рния к па́стві своє́й, бил єси́ ско́рий помо́щник призива́ющим тя в по́мощ, святи́телю о́тче Інноке́нтіє: не то́чію бо близ притека́ющих к ра́ці моще́й твої́х, но і дале́че отстоя́щих і призива́ющих і́м'я твоє́ ізціля́єши от вся́кия болі́зні. За таково́є у́бо врачева́ніє прийми́ от нас похвали́ сія́:","Ра́дуйся, цільби́ іспо́лнь яви́вийся алава́стре, я́ко лю́ди Христо́ви ароматствуєши твої́ми ізцеленії;","Ра́дуйся, ароматний фіяле, чудеси́ удивля́я, на́рда писти́ка многоці́нний.","Ра́дуйся, істо́чниче, благода́ть ізцеленій ізливающий нам от всечестни́я ра́ки твоєя́ незави́стно.","Ра́дуйся, я́ко ті́ло твоє́ трудолю́бноє вмі́сто масте́й нам во гро́бі оста́вил єси́ істощати ізціле́нія.","Ра́дуйся, я́ко твої́ми моли́твами сліпі́ї прозрі́ша.","Ра́дуйся, я́ко твої́м хода́тайством хромі́ї і безногії ходи́ти нача́ша.","Ра́дуйся, я́ко твої́м заступле́нієм разсла́бленнії ізцелеша;","Ра́дуйся, я́ко твої́м предста́тельством от неізцельния огневичния болі́зні здра́ві би́ша.","Ра́дуйся, покри́тих стру́пами, я́ко прокаже́нних, уврачева́вий;","Ра́дуйся, впа́дших в лихорадочния і тряса́вичния я́зі возста́вивий.","Ра́дуйся, я́ко лише́нних сми́сла здра́вим умо́м снабдеваєши;","Ра́дуйся, я́ко от стра́ха і мечта́ній томи́мих свобожда́єши.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби і го́ркая іспита́нія терпіли́вно под'ял єси́, о́тче, я́ко добр во́їн Христо́в, о́во терп'я́ наві́ти от клеветнико́в злих, о́во же препирался с по́лчищем неві́рних і суєверних і о́во іскушаєм от древляго змі́я, уязвлявшаго тя за же́ртви своя́, із че́люстей єго́ тобо́ю ісхищаємия, но вся сія́ побіжда́я за возлюби́вшаго тя Христа́, немо́лчно воспіва́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє ізнемога́єть ізрещи́ вся ско́рбі, лише́нія, унічиже́нія, болі́зні і страда́нія, я́же ра́ди спасе́нія па́стви твоєя́, свя́те Інноке́нтіє, под'ял єси́. Ті́мже терпі́нію твоєму́ то́чію див'я́щеся і любо́вію побіжда́єми, с благода́рним чу́вствієм вопіє́м:","Ра́дуйся, во́їне Христо́в непобіди́мий;","Ра́дуйся, тверді́йший адама́нте, в терпі́нії невредимий.","Ра́дуйся, я́ко я́рость неблагомислящих, гні́вающихся непра́ведні, претерпі́л єси́;","Ра́дуйся, я́ко превозносящіяся злочести́вим шата́нієм па́ки лю́ті сокруша́єми ви́діл єси́.","Ра́дуйся, же́стоких і злоко́зненних влади́к укроще́ніє;","Ра́дуйся, угнете́нних і стра́ждущих рабо́в ско́роє заступле́ніє.","Ра́дуйся, я́ко коре́нія заблужде́ній і те́рніє неві́рія трудолю́бні історгал єси́;","Ра́дуйся, я́ко Боже́ственних повелі́ній насажде́нія в сердця́х ві́рних мно́гими труди́ возделовал єси́.","Ра́дуйся, смире́нієм свої́м дия́вола побіди́вий;","Ра́дуйся, моли́твою і бді́нним стоя́нієм плоть свою́ умертви́вий.","Ра́дуйся, я́ко кра́сния твої́ но́зі до́бльственні к боре́нію со врага́ми просте́рл єси́;","Ра́дуйся, я́ко до́брі тече́ніє соверши́в, ко Христу́ восхожде́ніє обрі́л єси́.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасе́нія ра́ди от осліпле́нія ста́рцю, очи́ма тя́жко ви́дящу, получи́ти же зрі́ніє хотя́щу і с ві́рою о сем у тебе́ по́мощі прося́щу, ско́ро прите́кл єси́, свя́тче, в хра́мину того́, іді́же єгда́ прикосну́лся єси́ болі́зненній главі́ єго́, а́біє ощути́ он світ во о́чію своє́ю і прозрі́, хваля́ тя і вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну крі́пкую і огражде́ніє необори́моє от всіх скорбе́й і зол імі́єть тя, па́стирю благи́й, страна́ сія́: твої́м бо си́льним заступле́нієм і предста́тельством дони́ні град сей і оби́тель твоя́ сохраня́ються в ми́рі і благоде́нствії. І ми у́бо, спаса́ємії тобо́ю, благода́рственно вопіє́м ті:","Ра́дуйся, ча́ша, єле́й ми́лости к нам Бо́жия содержа́щая;","Ра́дуйся, горо́, Боже́ственнаго на нас гні́ва ту́чі отводя́щая.","Ра́дуйся, я́ко пото́ки ми́ра к нам приво́диши;","Ра́дуйся, я́ко оби́ліє благ хода́тайствуєши.","Ра́дуйся, ми́лости превели́кия і ско́рбним сострада́нія сокро́вище;","Ра́дуйся, простра́нноє Бо́жіяго о па́стві твоє́й промишле́нія прия́телище.","Ра́дуйся, в печа́ліх су́щим увеселе́ніє;","Ра́дуйся, удруче́нних попече́нії жите́йськими утіше́ніє.","Ра́дуйся, в деторожденії ма́терем ско́рий помо́щниче:","Ра́дуйся, в час кончи́ни моли́твенний наш предста́телю.","Ра́дуйся, о ми́лості і ми́ре па́стви твоєя́ ізві́стний рачи́телю;","Ра́дуйся, о́тче честни́й, от вся́каго зла і бі́дствія усе́рдний наш храни́телю.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє і моле́ніє те́плоє пред нетлі́нними моща́ми твої́ми, єди́ним от боляр приноси́моє тебі́, не презрі́л єси́, о́тче, но ско́ро усли́шав і во сні я́влься, облегчи́л єси́ болі́зні і страда́нія єго́, си́це і на́ших моленіій і пі́ній гла́си усли́ши, ієра́рше Христо́в, ві́рі же і любві́ люді́й твої́х воньми́ і сви́ше покро́в твой да́руй хва́лящим тя і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светосіятельна тя світи́льника, чрез се́дмдесят і три лі́та сокрива́єма в землі́ не восхоті́ Госпо́дь оста́вити под спу́дом, є́же іспо́лнитися рече́нію Єго́, а́ки світи́льник на сві́щник поставля́ють, да входя́щії ви́дять світ. Ті́мже і ми во хра́мі сем і всю́ду, я́ко тя зря́ще і тобо́ю просвіща́ємі, дерза́єм глаго́лати сія́:","Ра́дуйся, сві́тлоє на тве́рди церковной світи́ло і Сиби́рськия страни́ сла́во;","Ра́дуйся, церкве́й строї́телю і обогати́телю чудеси́ тіх неску́дний.","Ра́дуйся, пресві́тлая красото́ святи́я оби́телі сея́;","Ра́дуйся, блестящая заре́ ізбра́ннаго тобо́ю гра́да сего́.","Ра́дуйся, сві́щниче всезлати́й і многоці́нний;","Ра́дуйся, би́сере предрагий небе́сний.","Ра́дуйся, облакообразний покро́ве, на ті́снім путі́ спасе́нія нас осіня́ющий;","Ра́дуйся, огневи́дний сто́лпе, в нощі́ неві́дінія і заблужде́ній нас просвіща́ющий.","Ра́дуйся, я́ко святи́нею твоє́ю всіх тре́бующих по́мощі твоєя́ освяща́єши;","Ра́дуйся, я́ко блиста́нієм чуде́с твої́х во вся конці́ страни́ сея́ сія́єши.","Ра́дуйся, я́ко і по преставле́нії твоє́м с на́ми пребива́єши;","Ра́дуйся, я́ко, і жив'я́ в селе́ніїх ра́йських, нас не оставля́єши.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше с небесе́ пода́ждь, преблаже́нне о́тче, с ві́рою і благогові́нієм воспоминающим честно́є твоє́ успе́ніє і пресві́тлоє пренесе́ніє святи́х моще́й твої́х празднующим; і́маши бо дарова́нную ті от Бо́га си́лу і власть подава́ти тре́бующим вся, я́же ко спасе́нію проше́нія, і ни́ні предстоя́ Престо́лу Боже́ственному, моли́ о тебі́ воспіва́ющих: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ хода́тайство і си́льноє заступле́ніє просящим твоєя́ ско́рия по́мощі, восхваля́єм пода́теля всіх благи́х Бо́га, дарова́вшаго в послі́дняя времена́ страні́ сей тебе́, отця́ на́шего чудотво́рця, моли́твенника і засту́пника, ти же не возгнуша́йся нас, грі́шних і недосто́йних рабо́в Єго́, но усли́ши хвале́бними гла́си вопію́щих тебі́:","Ра́дуйся, су́єтства привре́меннаго к бу́їяго воі́стину обличи́телю;","Ра́дуйся, апо́столом равноревностний Єва́нгельським науче́нієм.","Ра́дуйся, му́чеников сострада́льче і красото́;","Ра́дуйся, первопа́стирю і учи́телю христоімени́тих люді́й землі́ сея́.","Ра́дуйся, церко́вноє украше́ніє;","Ра́дуйся, архієре́єв добро́то, свяще́нников і і́ноков похвало́.","Ра́дуйся, я́ко прия́л єси́ трудо́в твої́х воздая́ніє;","Ра́дуйся, крестоно́сному наро́ду на́шему похвало́ і утвержде́ніє.","Ра́дуйся, тіле́с на́ших неуси́пноє хране́ніє;","Ра́дуйся, і душ на́ших к Ца́рствію Небе́сному возведе́ніє.","Ра́дуйся, Бо́гу соверше́нне і всецеле угоди́вий;","Ра́дуйся, віне́ць безсме́ртія наві́ки получи́вий.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О преди́вний чудотво́рче і пресла́вний уго́дниче Христо́в Інноке́нтіє! Воньми́ гла́су моле́ній на́ших, от сокруше́ннаго се́рдця к тебі́ возноси́мому, і богоприя́тним твої́м хода́тайством іспроси́ нам от Христа́ Бо́га на́шего проще́ніє прегріше́ній на́ших, осла́бу і ізбавле́ніє от враго́во ви́димих і неви́димих, і от вся́кия ско́рби, біди́ і напа́стей, да с тобо́ю і со всі́ми святи́ми в селе́нії пра́ведних сподо́бимся пі́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельському жи́тельству на небесі́х поревнова́л єси́, о́тче: по і́мені бо і житіє́ твоє́ непоро́чно бисть на землі́, сего́ ра́ди і возви́сился єси́ до лицезрі́нія Творця́ А́нгелов. Отню́дуже призира́я ви́ну на град сей і лю́ди, усли́ши нас, похва́льная восписующих ті сія́:","Ра́дуйся, неви́нностію А́гнця непоро́чнаго подража́тель би́вий;","Ра́дуйся, воздержа́нієм твої́м а́нгельськоє во пло́ті житіє́ яви́вий.","Ра́дуйся, я́ко а́нгел, Сиби́рськия це́ркве Бо́жия діла́ возвіща́яй;","Ра́дуйся, я́ко архистрати́г си́ли небе́сния, всіх прибіга́ющих к тебі́ от бід сохраня́яй.","Ра́дуйся, непоро́чности і невинности соіме́нний учи́телю;","Ра́дуйся, незло́бія і чистоти́ усе́рдний храни́телю.","Ра́дуйся, убеленний неви́нностію кри́не ра́йськаго прозябе́нія;","Ра́дуйся, умаще́нная чистото́ю ма́слина небе́снаго благослове́нія.","Ра́дуйся, у́ме небе́сних неізрече́нних благ наслажда́яйся;","Ра́дуйся, па́стирю, с му́дрими в ра́дость Пастиренача́льника своєго́ вше́дий.","Ра́дуйся, я́ко світ лиця́ Бо́жия я́сно на небесі́ смотря́єши;","Ра́дуйся, я́ко тім же сві́том осія́нний, притека́ющих к тебі́ неізрече́нно возвеселя́єши.","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ско́рий в ско́рбіх помо́щниче, святи́телю о́тче Інноке́нтіє, я́ко імі́я ве́ліє дерзнове́ніє пред Го́сподем, от вся́ких нас бід свобожда́й, да с ра́достію зове́м ті:","Ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["К тебі́, свя́тче Бо́жий, я́ко к ско́рому помо́щнику і моли́твеннику о спасе́нії моє́м, аз недосто́йний і грі́шний припа́дая молю́ся: не пре́зри мене́ уни́лаго, не́мощнаго, во мно́гая беззако́нія впа́дшаго, і по вся дні і часи́ согріша́ющаго, но воньми́ душі́ моє́й, я́ко скорблю́, і умоли́ Го́спода Бо́га всея́ тва́рі Соді́теля, Єму́же ни́ні предстої́ши в ра́дості святи́х і с ли́ки а́нгелов, поми́ловати м'я і ізвести́ із темни́ці гріхо́вния ду́шу мою́, пре́жде да́же не отиду́ отсю́ду і ктому́ не угото́в явлю́ся на суд Єго́. Єй, о́тче! Не посрами́ мене́, к тебі́ с ві́рою притека́ющаго, а́ще бо і недосто́їн єсьм твоєго́ хода́тайства і заступле́нія, но ти, бив подража́тель человіколю́бія Бо́жия, сотвори́ м'я досто́йна чрез обраще́ніє от злих діл к благо́му житію́, да та́ко душе́ю і ті́лом здрав бив, сла́влю і пою́ ди́внаго во святи́х Свої́х Бо́га на́шего і твоє́ те́плоє заступле́ніє, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Святи́телю, о́тче Інноке́нтіє! При́зри на нас, раб Бо́жиїх (імена́), і на прихо́д (дом) сей; моли́ Христа́ Бо́га, да низпосле́ть нам Ду́ха Своєго́ Свята́го дар, во є́же умудри́ти нас ходи́ти пред Ним во вся́ком благоче́стії і чистоті́. Ми при́сно заблужда́єм от путі́ спасе́нія: руководи́ нас, ми́лостивий наш наста́вниче. Ми не́мощни єсьми́ во ві́рі: утверди́ нас, правові́рія учи́телю. Ми зіло́ убо́зі сотвори́хомся до́брих діл: обогати́ нас, благосе́рдія сокро́вище. Ми при́сно наві́туємі єсьми́ от враг, ви́димих і неви́димих, і озлобля́ємі: помози́ нам, безпо́мощних засту́пниче; да славосло́в'яще і́м'я Бо́жиє во дні і в нощі́, сподо́бимся би́ти наслі́дници і жи́зні ві́чния, і просла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["Свя́тче Бо́жий, па́стирю до́брий, ді́лателю ві́рний виногра́да Христо́ва, святи́телю о́тче Інноке́нтіє! При́зри на град сей і на лю́ди сія́! Моли́ Христа́ Бо́га, да сохрани́ть па́ству твою́ от волко́в, гу́б'ящих ю; да ниспо́слеть Ду́ха Своєго́ Свята́го во є́же умудри́ти нас ходи́ти пред Ним во вся́ком благоче́стії і чистоті́ во вся дні живота́ на́шего, да славосло́в'яще і́м'я Єго́ всесвято́є во дні і в нощі́, сподо́бимся би́ти наслі́дници жи́зні ві́чния, і просла́вим Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Світи́льниче Це́ркве пресві́тлий, / озари́вий луча́ми добро́т твої́х страну́ сію́, / і ісціле́ньми мно́гими притека́ющих к тебі́ с ві́рою / Бо́га просла́вивий, / мо́лим тя, святи́телю о́тче Інноке́нтіє, / огражда́й моли́твами твої́ми град сей // от всіх бід і печа́лі."]},{"h":"Кондак, глас 4","ps":["Непоро́чности соіме́ннаго па́стиря, / пропові́дника ві́ри в язи́ціх Монго́льських, / сла́ву і украше́ніє Ірку́тськия па́стви, / любо́вію восхва́лим всі ві́рнії: / той бо єсть храни́тель страни́ Сиби́рськия // і моли́твенник о душа́х на́ших."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Інноке́нтіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим дванадесяти Апостолам","e":"Akathist to the Holy Twelve Apostles","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії самови́дці і свиді́теліє Сло́ва воплоще́нія, ми́ра ловці́ і сосу́ди Христо́ви благода́ті, Це́ркве пресві́тлия зві́зди, вселе́нния світи́льници і пропові́дници ві́ри, я́ко луча́ми блиста́ющії заря́ми духо́вними, всечестна́я двоєнадеся́тице учени́к Спа́са Христа́ Бо́га, світоно́сную і преблаже́нную па́м'ять ва́шу благоче́стно твори́м ни́ні. Ви же, я́ко Боже́ственнаго сві́та прича́стници і дерзнове́ніє ко Христу́ іму́щії, молі́теся Єму́ прилі́жно, да к сві́ту богоразу́мія нас всіх і́стинно наста́вить, во ві́рі тве́рдій укріпи́ть і в ми́рі глубо́ці соблюде́ть зову́щих вам:","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Ікос 1","ps":["А́нгельськую слу́жбу воплоще́нному нас ра́ди Боже́ственному Сло́ву принося́ще, вселе́нную всю обтекосте, святі́ї апо́столи, я́ко богопосланнії ві́стници гряду́щаго ми́ру спасе́нія. Ті́мже сло́вом і́стини Христо́ви от слове́с ва́ших озареннії і благода́тію Свята́го Ду́ха спасе́ннії чрез ві́ру, всі конці́ ми́ра от дній дре́вніх і до днесь немо́лчно восхваля́ють вас си́це:","Ра́дуйтеся, вселе́нния світи́льники;","ра́дуйтеся, благосла́внії труби́.","Ра́дуйтеся, тве́рдия ві́ри пропові́дники;","ра́дуйтеся, уче́ній небе́сних благовещаннії сказа́телі.","Ра́дуйтеся, церко́внії столпи́;","ра́дуйтеся, разори́тели і́дольськия ле́сти.","Ра́дуйтеся, ізбра́ннії понести́ пред язи́ки Боже́ственноє і́м'я.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 2","ps":["Ви́дяще Го́спода Сла́ви, в зра́кі раба́ во пло́ті прише́дшаго, і сли́шавше Того́ Предте́чею свиді́тельствуєма А́гнця Бо́жия би́ти, гріх ми́ра взе́млющаго, вся в ми́рі оста́вльше, вслід Того́ устреми́стеся, согла́сно всі пою́ще та́ко ізво́лившему о вас Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мнаго восхожде́нія от до́льних на го́рняя яви́ли єсте́ о́браз, богому́дрії апо́столи, єгда́ до́ми, бра́тію і імі́нія своя́ во уме́ти вміни́ли єсте́ і востекли́, себі́ отве́ргшеся, стезе́ю пра́вою к ті́сним врато́м Ца́рствія Христо́ва. Того́ ра́ди досто́йно сли́шіте от всіх сицева́я:","Ра́дуйтеся, вина́ раствореннаго прему́дростію Бо́жієй на трапе́зі духо́вній поле́зно вкуси́вшії;","ра́дуйтеся, губи́тельноє безу́міє жи́зні привре́менния по гла́су, ви зва́вшему, без сумні́нія вся́каго оста́вльшії.","Ра́дуйтеся, сокро́вище духо́вноє на селі́ при путі́ ва́шем обрі́тшії;","ра́дуйтеся, би́сера до́браго ми́слію се́рдця ва́шего іскавшії.","Ра́дуйтеся, на ра́ло Христо́во ру́ці ва́ша несумнительно і тве́рдо во́лею своє́ю возложшії.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укрепленнії, всему́дрії апо́столи, благоразу́мієм ва́шим і огне́м духо́вним вся́кую вра́жию пре́лесть попали́вше, челові́чеський род ві́рою просвіти́ли єсте́. Ті́мже мо́лим ви: омраче́нная гріхми́ душі́ на́ша просвіті́те, да воспря́нем є́же пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще прему́дрость вселе́нную всю сло́вом спаси́тельним просвіти́ти, озарили єсте́ во тьмі і сі́ні сме́ртній сідя́щия лю́ди; просвіті́те у́бо і на́ша душі́, омраче́нния мра́ком страсте́й, да восхва́лим вас та́ко:","Ра́дуйтеся, світи́льници восто́ка ми́сленнаго, тьму неразу́мія прогнавшії ві́рою;","ра́дуйтеся, напоі́вшії зе́млю струя́ми Боже́ственних віща́ній.","Ра́дуйтеся, живоно́сним током слове́с Христо́вих орошающії нас бі́дствующих зно́єм скорбе́й;","ра́дуйтеся, возбраняющії лука́вим по́мислом омраче́ннаго се́рдця на́шего.","Ра́дуйтеся, мре́жею благода́ті із глубини́ потопляющих нас сує́ть ми́ра сего́ любо́вію всіх, с ві́рою взира́ющих к вам, возводя́щії.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 4","ps":["Бу́рею вну́треннею і волна́ми морськи́ми іногда́ в корабли́ обурева́ємі, святі́ї апо́столи, ко Христу́ вопія́сте: «Учи́телю, спаси́ ни, погиба́єм!». Прия́вше же того́ всемогу́щую по́мощ, яви́стеся по благода́ті, вам да́нній, са́мі всіх ко́рмчії, к благоти́шному приста́нищу наде́жно приводящії. І нас, в пучи́ні зол бі́дні м'ятущихся і напа́стьми жите́йськими при́сно коле́блемих, упра́віте ко бре́гу безстра́стія, іді́же всі́ми спасаємими поє́ться Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше от Пастиренача́льника і Го́спода ва́шего призива́ющеє сло́во: «Жа́тва у́бо мно́га, ді́лателей же ма́ло; молі́теся у́бо Господи́ну жа́тви, я́ко да ізведе́ть ді́лателі на жа́тву Свою́», іспо́лнишася, блаже́ннії апо́столи, огнепа́льною ре́вностію сему́ ді́лу Христо́ву послужи́ти, благослове́ннії на по́двиг сей, обтекосте гра́ди і ве́сі мно́гія, благовіству́юще Єва́нгеліє Ца́рствія, ісціля́я всяк неду́г і вся́ку я́зю в лю́діх. Умолі́те у́бо, я́ко вра́таріє Боже́ственнаго Ца́рствія, і нам спасе́ніє обрісти́, со умиле́нієм зовущим вам та́ко:","Ра́дуйтеся, до́брії ві́стници Христо́ви, сослуже́бници ми́сленним чи́ном;","ра́дуйтеся, і́же от ри́барей умудреннії па́че ри́торов.","Ра́дуйтеся, труби́ Христо́ви благогла́снії, ко приста́нищу спасе́нія вся привлекшії;","ра́дуйтеся, Па́стиря до́браго богоізбра́нния о́вці, волко́в ми́сленних во о́вчую кро́тость ві́рою преложившії.","Ра́дуйтеся, уста́ огнедухновенная Христо́ви, от уст іму́щаго поглоти́ти нас врага́ ізбавля́ющії.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 5","ps":["Боготе́чния зві́зди, світлостьми́ Боже́ственних доброді́телей сія́ющії, яви́стеся, всехва́льнії апо́столи, я́ко со́лнце іму́ще, земни́я конці́ обнови́сте. Сві́тлим блиста́нієм ва́шим у́бо і нас озарі́те і страсте́й ізба́віте всіх вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше, апо́столи святі́ї, во о́бразі челові́честім Влади́ку ми́ра і Си́на Бо́жия, усти́ первоверхо́внаго апо́стола Петра́ Христа́ пропові́дасте, і Той я́ко открове́ніє О́тчеє іспові́даніє ва́ше приє́мий. Сего́ ра́ди і ми, во іспові́данії ва́шем утверди́вшеся, ублажа́єм вас та́ко:","Ра́дуйтеся, богоозареннії іспові́дниці неізрече́нния Боже́ственния сла́ви воплоти́вшагося Сло́ва;","ра́дуйтеся, с небе́с приє́мшії благода́ть богосло́вія Христо́ва.","Ра́дуйтеся, мир віща́нії ва́шими соблю́дшії;","ра́дуйтеся, я́ко от Самаго́ Го́спода ублаже́ні би́сте во іспові́данії ва́шем.","Ра́дуйтеся, я́ко от Него́ прия́сте Боже́ственную власть в'яза́ти і ріши́ти гріхи́ челові́ков.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 6","ps":["Пропові́даніє Влади́ки і Го́спода своєго́, я́ко подоба́єть Єму́ мно́го во Ієрусали́мі пострада́ти от ста́рець, і архієре́й, і кни́жник, і убіє́ну би́ти, сли́шавше, дивистеся зіло́, недоумі́юще, ка́ко сбу́дуться писа́нія о сла́ві і че́сти Си́на Челові́чеськаго. Вразумленнії же, я́ко не челові́чеською ми́слію, но неісповіди́мою во́лею Отця́ Небе́снаго путіє́ всі в ми́рі ісправля́ються, научи́стеся смире́нно пі́ти Бо́гу, благоволи́вшему та́ко о Си́ні своє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ со́лнця світлі́є на Фаво́рстій го́ре сла́ва Боже́ственнаго зра́ка Христо́ва пред ва́ми, святі́ї апо́столи, о́нім у́бо ізбра́нним, на го́ру совозшедшим. Ті́мже Мойсе́я і Ілію́ ви́дівше, во о́блак сві́тел вше́дшия, і глас Отчаго свиді́тельства о Єдиноро́днім Си́не с небе́с сли́шавше, толи́кия благода́ті небе́снаго озаре́нія сподобльшимся, усе́рдно возглаша́єм си́це:","Ра́дуйтеся, в непристу́пнім сві́те Христа́ на Фаво́рі облиставшася зревшії;","ра́дуйтеся, от Отця́ свиді́тельствуєма Си́на Бо́жия сли́шавшії.","Ра́дуйтеся, Мойсе́я і Ілію́, явльших Христо́во Божество́, на горі́ сла́ви сретившії;","ра́дуйтеся, бесі́дою тіх о ісхо́ді Христа́, во Ієрусали́мі би́ти хотя́щем, просвіще́ннії.","Ра́дуйтеся, преми́рния сла́ви Христо́вой соо́бщници.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 7","ps":["Хотя́ душепита́тельную угото́вати ми́ру трапе́зу Животворя́щаго Ті́ла і Кро́ве Своєя́ Госпо́дь всіх і Зижди́тель, предизобразі всесвято́є своє́ заколе́ніє і безсме́ртія ча́шу в пропові́данії о хлі́бі жи́зні ві́чния, і єгда́ мно́зі сли́шавшії сло́во сіє́ ропта́ху і блазняхуся і всп'ять ідя́ху от Христа́, ви, апо́столи блаже́ннії, усти́ Си́мона Петра́ єдиноми́сленно реко́сте: «Го́споди, ко кому́ і́дем? Глаго́ли живота́ ві́чнаго і́маши, і ми ві́ровахом і позна́хом, я́ко Ти єси́ Христо́с, Син Бо́га Жива́го». Сіє́ іспові́даніє ва́ше ублажа́юще, те́плі припаде́м ни́ні к Бо́гу, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия Боже́ственния Па́схи, не от Єги́пта, но от Сіо́на гряду́щия, причасти́тися сподо́бистеся, богоблаже́ннії апо́столи, і оми́сте но́зі ва́ша от препоясаннаго ле́нтієм Влади́ки, смире́нія о́браз тім яви́вшаго, собесі́дниці на Ве́чері Та́йній Христа́ Го́спода би́сте. Ті́мже велича́єм вас си́це:","Ра́дуйтеся, в го́рницю Сіонськую я́ко под сінь небе́сную вше́дшії;","ра́дуйтеся, честна́го омове́нія от Влади́ки Христа́ сподо́бленнії.","Ра́дуйтеся, за́повідь Госпо́дню: да бу́деть послі́днім хотя́й пе́рвим би́ти — із уст Учи́теля ва́шего приє́мшії;","ра́дуйтеся, Безкро́вния Же́ртви і слове́сния слу́жби вели́ким Архієре́єм Заві́та Но́ваго, за весь мир приноси́мия, уча́стници.","Ра́дуйтеся, рука́ми чи́стими і усти́ нескве́рними хліб жи́зні і весе́лія Боже́ственнаго ча́шу от рук Тайновершителя Го́спода взе́мшії.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 8","ps":["Стра́нноє віща́ніє своєго́ Учи́теля і Го́спода, я́ко єди́н от вас преда́тель і́мать би́ти, сли́шавша, смутистеся, святі́ї апо́столи, і ско́рбію і стра́хом одержи́ми, «Кто єсть сей?» Учи́теля вопрошасте. Єгда́ же по ма́лім часі́ сбитіє́ сло́ва сего́ стра́шнаго в си́ні погибельнем я́ві откри́ся, ду́хом сокруше́нним принесо́сте Бо́гу псало́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь зако́н і проро́ци, я́же о Христі́ преднаписа́ша, того́ ісполне́ніє в честни́х страда́ніїх, погребе́нії, предивном восстанії Спа́са тридне́внім і сла́внім ви́дівше, глубину́ сія́ вся строївшей прему́дрости Боже́ственния і ра́зума не всю іспитали єсте́ тогда́, бе́здну же суде́б Госпо́дніх не у постигли єсте́, зане́ просве́щени Ду́хом не би́сте. Но во во́лю Христа́ Го́спода себі́ преда́вше, виді́нієм Того́ ра́сп'ята не соблазнистеся, воскресе́нію достиго́сте, ві́рно поклони́стіся і науче́нію Христо́ву себі́ смире́нно подклонисте, к послуша́нію ві́ри і к разумі́нію та́йни любве́ Боже́ственния і нас, апо́столи Христо́ви приведі́те, да поє́м вам та́ко:","Ра́дуйтеся, я́ко не смути́ся се́рдце ва́ше, є́же ві́ровати в Бо́га распина́єма;","ра́дуйтеся, я́ко не в собла́зн і не в безу́міє, но во спасе́ніє си́лою Бо́жиєю виді́ніє Креста́ Госпо́дня прия́ли єсте́.","Ра́дуйтеся, не оста́вленнії си́рими по отше́ствії Владичнем;","ра́дуйтеся, ро́ждіє живоноснії лози́ Христо́вой.","Ра́дуйтеся, я́ко о вас моли́тва Христо́ва пролія́ся, да соблюде́ні бу́дете от неприя́зні і священни во і́стину єва́нгельськаго сло́ва.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 9","ps":["Всю скорб і печа́ль от'я Христо́с от серде́ць вас, друго́в свої́х, многоча́стні і многообра́зні денми четиредесятми явля́яся вам по воскресе́нії Своє́м, с ва́ми же яди́й і пія́й, і вся́ко увіря́я о Своє́м сла́внім возстанії, да бу́дете свиді́теліє Єму́ да́же до послі́дніх землі́. Ті́мже ра́достію несказа́нною іспо́лнені би́вше і та́йнам Ца́рствія Бо́жия наученнії, сою́зом любве́ связу́ємі, єдиноду́шно би́сте вку́пі, глаго́люще: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йства земна́го преви́шшеє та́їнство восхо́да Го́спода на о́блаціх на не́бо от гори́ Ма́сличния, апо́столи Христо́ви, зрі́ти приведеннії, та́мо многолюбезни да́ри науче́нія послі́дняго, я́ко от Влади́ки ми́ра, от Христа́ получи́сте, преми́рноє благослове́ніє от Него́ прия́сте, во Ієрусали́м возврати́стеся с ра́достію ве́лією, ви́ну благослов'я́ще Бо́га. Та́ко о вас благоволи́вшему Промисли́телю ми́ра вели́чія даю́ще хвали́, согла́сно прино́сим вам, воспіва́я си́це:","Ра́дуйтеся, мир от Го́спода, вседшаго на о́блаки небе́сния, приявшії;","ра́дуйтеся, соєдине́ніє го́рніх с до́льними во восхо́ді Христо́ві я́ві узревшії.","Ра́дуйтеся, с собо́ром безпло́тних вознося́щася от землі́ на не́бо восхвалившії;","ра́дуйтеся, на горі́ восхожде́нія Христо́ва світообра́зному лиця́ Єго́ зра́ку послі́дняя от земноро́дних боголі́пно поклонившіїся.","Ра́дуйтеся, і́мже за́повідь научи́ти язи́ки сло́ву Христо́ву даде́ся.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 10","ps":["Спасе́нія путь іща́ обрісти́ учени́чеський лик, Тебе́ ви́дя от землі́ взима́єма, глаго́лаше: «Влади́ко, ка́ко ни́ні оставля́єши раби́ Твоя́ і ка́мо і́деши, рука́ма содержа́й конці́?»; єгда́ же усли́шасте Спа́са, глаго́люща: «Не оста́влю вас, я́же собра́х, но послю́ вам Ду́ха Пресвята́го; ви же, с висоти́ обо́лкшеся си́лою, іді́те во вся язи́ки, глаго́ля віща́нія спасе́нія». Ті́мже у́бо в ра́дості снидо́сте с гори́ Єлео́нськия, сла́в'я Боже́ственноє вознесе́ніє Христо́во, творя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни до́ма, іді́же с Богома́терію апо́столи святі́ї бі́ста, моля́шеся о і́мені Христо́ві, потрясе́ся сви́ше носи́му диха́нію бу́рну, єгда́ в день п'ятидесятний, ісполня́я преждерече́нная, посла́л Христо́с Ду́ха Свята́го, і́же і соше́д на ви ви́дом о́гненним, у́жасом іспо́лнь язи́ков собра́ніє; язи́ки бо глаго́лющих ки́йждо свою́ бесі́ду сли́шаше. Ті́мже ми, наслі́дници тоя́ благода́ті, вас заре́ю богонача́льною облистанних, апо́столи богоно́снії, сла́вим:","Ра́дуйтеся, я́ко по обітова́нію Христо́ву я́ві крести́стеся Ду́хом Святи́м і огне́м;","ра́дуйтеся, я́ко би́сте жили́ще пречи́стій благода́ті.","Ра́дуйтеся, я́ко во вас єстество́м святи́ні своєя́ всели́ся с небесе́ си́ла Ду́ха, от Отця́ ісходя́ща і в Си́ні почива́юща;","ра́дуйтеся, во гла́сі диха́нія Ду́хом восхищеннії провіща́ти вели́чія Бо́жия.","Ра́дуйтеся, я́ко чрез ва́ша свяще́нния глави́ огнь Уті́шителя Ду́ха на зе́млю сни́де.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Святі́й і Живонача́льній Тро́йце в явле́нії Ду́ха Свята́го прине́сше, святі́ї апо́столи, ра́дости і вся́каго ві́дінія іспо́лнистеся і дерзнове́ніє прия́сте, мно́гими зна́меньми і чудеси́ Це́ркве до́броє нача́ло положи́сте і ве́лією си́лою возда́сте свиді́тельство воскресе́нію Го́спода Ісу́са, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоподательноє пропові́даніє ва́ше со смиренному́дрієм і мно́гими слеза́ми і напа́стьми ісполня́шеся; внима́ху же наро́ди глаго́лемим от вас єдиноду́шно, сли́шаще і ви́дяще зна́менія от рук ва́ших бива́ющая, і креща́хуся мно́зі. Ви же Це́ркві утвержда́сте, от мі́ста к мі́сту преходя́ще, да і іни́м градово́м благовісти́ться сло́во Бо́жиє. Сего́ труда́ ва́шего ра́ди взива́єм вам си́це:","Ра́дуйтеся, сою́зом любве́ Христо́вой свя́заннії, любо́в і мир Церквем заві́том ві́чним положи́вшії;","ра́дуйтеся, і́га, єго́же не́мощно бі понести́, на ви́ї учени́к ніка́коже возложи́ти восхоті́вшії.","Ра́дуйтеся, всім вся би́вшії, да вся́ко спасу́ться ні́циї;","ра́дуйтеся, посіща́ти бра́тію во всіх граді́х, в ни́хже пропові́дасте Єва́нгеліє Христо́во, ви́ну тщавшіїся.","Ра́дуйтеся, нощми і денми лю́ди па́стви своєя́ непреста́нно учившії.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 12","ps":["Благода́ті небе́сния прича́стником і самови́дцем Сло́ва, є́же по пло́ті Ма́тере Єго́ успе́ніє ви́діти подоба́ше, є́же на Ней та́їнство, я́ко не то́кмо Спа́сово от землі́ восхожде́ніє у́зрять, но і ро́ждшия Єго́ преставле́ніє свиді́тельствують. Ті́мже приспі́вшу дне́ві Богома́тере отше́ствія отвсю́ду Богонача́льним манове́нієм апо́столи собра́вшеся, Сіо́на дости́гше, і на не́бо предпослаша Ви́шшую Херуви́м, пі́ніє надгро́бноє Пречи́стій творя́ Богокрасною пі́снію: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вная діла́ ва́ша, болі́знем і трудо́м єва́нгельськаго благові́стія див'я́щеся, честна́я ва́ша страда́нія почита́єм, богоізбра́ннії апо́столи: весь бо всю́ду мир проідо́сте, Єва́нгеліє Христо́во колі́ном всім, язи́ком і страна́м пропові́давше. Ті́мже і ми сла́вим вас всі:","Ра́дуйтеся, мре́жею слове́сною улови́вшії вся́каго ро́да ізбра́нних;","ра́дуйтеся, ї́хже сло́вом врата́ сме́рті отверза́хуся і отдая́ху затворе́нная мертвеци́.","Ра́дуйтеся, Кро́вію А́гнця от люде́й пе́рвенці Бо́гу купленнії;","ра́дуйтеся, і́мже храм ски́нії свиді́нія на небесі́х предуготовася.","Ра́дуйтеся, Це́ркве Христо́ви вели́кая сла́во.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 13","ps":["О, всехва́льнії і богоблагословеннії апо́столи, Христо́м нарече́ннії Єго́ дру́зі і служе́нія Це́ркве наслі́дници, ви́шняго престо́ла о́крест обстоя́щії в неув'яда́ємих вінці́х! Моле́ніє на́ше, любо́вію к вам ни́ні проліянноє, приє́мше, сотворі́те всіх Бо́гу моли́тву, да соблюде́ть Це́рков Свою́ святу́ю во єдиноми́слії і ми́ре, па́стирем єя́ да́руєть святи́ню і́мені Єго́ ре́вностно іспові́дати і ві́ри нелицемі́рній дерзнове́ніє показа́ти. Разсі́янния же ві́тром суєму́дрія ча́да да собере́ть во єди́ноє Ца́рство і да сподо́бит та́мо во сві́ті непристу́пнім с собо́ром ва́шим Єму́ немо́лчно воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськую слу́жбу воплоще́нному нас ра́ди Боже́ственному Сло́ву принося́ще, вселе́нную всю обтекосте, святі́ї апо́столи, я́ко богопосланнії ві́стници гряду́щаго ми́ру спасе́нія. Ті́мже сло́вом і́стини Христо́ви от слове́с ва́ших озареннії і благода́тію Свята́го Ду́ха спасе́ннії чрез ві́ру, всі конці́ ми́ра от дній дре́вніх і до днесь немо́лчно восхваля́ють вас си́це:","Ра́дуйтеся, вселе́нния світи́льники;","ра́дуйтеся, благосла́внії труби́.","Ра́дуйтеся, тве́рдия ві́ри пропові́дники;","ра́дуйтеся, уче́ній небе́сних благовещаннії сказа́телі.","Ра́дуйтеся, церко́внії столпи́;","ра́дуйтеся, разори́тели і́дольськия ле́сти.","Ра́дуйтеся, ізбра́ннії понести́ пред язи́ки Боже́ственноє і́м'я.","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Кондак 1","ps":["Ізбра́ннії самови́дці і свиді́теліє Сло́ва воплоще́нія, ми́ра ловці́ і сосу́ди Христо́ви благода́ті, Це́ркве пресві́тлия зві́зди, вселе́нния світи́льници і пропові́дници ві́ри, я́ко луча́ми блиста́ющії заря́ми духо́вними, всечестна́я двоєнадеся́тице учени́к Спа́са Христа́ Бо́га, світоно́сную і преблаже́нную па́м'ять ва́шу благоче́стно твори́м ни́ні. Ви же, я́ко Боже́ственнаго сві́та прича́стници і дерзнове́ніє ко Христу́ іму́щії, молі́теся Єму́ прилі́жно, да к сві́ту богоразу́мія нас всіх і́стинно наста́вить, во ві́рі тве́рдій укріпи́ть і в ми́рі глубо́ці соблюде́ть зову́щих вам:","Ра́дуйтеся, апо́столов двоєнадеся́тице, ми́ра конці́ уче́нієм Христо́вим просвіти́вшії."]},{"h":"Молитва","ps":["Влади́ко всемогу́щий, Го́споди Бо́же наш, ізбра́вий возлю́бленния Своя́ ученики́ і Апо́столи на про́повідь спасе́нія всему́ ми́ру, да́вий їм власть отпуща́ти гріхи́, прийми́ хода́тайства їх о ро́ді челові́чеськом, єго́же і суди́ти с ни́ми і́маши, тіх са́мих, я́ко друго́в Твої́х, нам зіло́ че́стних, дерза́єм, недосто́йнії, в предста́тельство к Тебі́, многопоспішеству́ющеє ко спасе́нію душ на́ших, приводи́ти, моля́щи їх усе́рдно. Святі́ї первоверхо́внії апо́столи Пе́тре і Па́вле, євангели́сти Христо́ви Іоа́нне Богосло́ве і Матфе́є, первозва́нний учениче́ Андре́є, водруже́нієм Креста́ Украї́ну благослови́вий, апо́столи святі́ї Іа́кове, бра́те Госпо́день, со други́м Іа́ковом, Фили́ппе, Варфоломе́є, Фомо́, Си́моне, Іу́до і Матфі́є! Всі святі́ї Богоізбра́нії апо́столи, ізря́днійшії уго́дниці Христо́ви, безбо́жия іскорени́теліє і ві́ри і́стинния насади́телі, помозі́те нам мо́щним ва́шим пред Го́сподом хода́тайством, ізба́витися от вся́каго зла і вра́жия ле́сти, тве́рдо сохраня́ти преда́нную ва́ми ві́ру Правосла́вную, в не́йже ва́шим предста́тельством ні ра́нами, ні преще́нієм, ні мо́ром, ні ко́їм гні́вом от Созда́теля своєго́ ума́лени бу́дем, но ми́рноє зді поживе́м житіє́ і да сподо́бимся ви́діти блага́я на землі́ живи́х, сла́в'яще Отця́ і Си́на і Свята́го Ду́ха, Єди́наго в Тро́йці сла́вимаго і покланя́ємего Бо́га, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Апо́столов первопресто́льници / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Ка́мень Христо́с ка́меня ві́ри прославля́єть сві́тло, / ученико́в преізря́дна, / і с Па́влом весь дванадесяточи́сленний собо́р днесь; / ї́хже па́м'ять соверша́юще ві́рно, // сих Просла́вльшаго прославля́єм."]},{"h":"Величання","ps":["Велича́єм вас, святі́ї дванадесяточи́сленнії апо́столи, весь мир уче́ньми свої́ми просвети́вшия і вся конці́ ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Акафіст преподобному Симеону Мироточивому, цареві Сербському","e":"Akathist to our Venerable Father Symeon the Myrrh-streamer, King of Serbia","secs":[{"h":"Кондак 1","ps":["Ізбра́нний воєво́до і царю́ Се́рбськия землі́, лі́ствице сві́тлая ві́ри правосла́вния, преподо́бне Симео́не, наро́да се́рбськаго засту́пниче і святи́х хра́мов зижди́телю, святи́я Ла́ври преди́вний устрої́телю і смире́нний і́ноков наста́вниче, прийми́ моле́нія правосла́вних чад твої́х, соблюди́, о́тче наш, от єресе́й ві́ру і́стинную, держа́ву і наро́д наш от губи́телей сохрани́, ві́рноє ста́до твоє́ от лю́тих волко́в огради́ і свяще́нния догма́ти церко́вния защити́. Прийми́ на́ша пі́нія і похвали́, я́же смире́нно прино́сим ті, і моле́ній нас, грі́шних, не пре́зри, із глубини́ серде́чния вопію́щия:","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель ізбра́ тя от чре́ва ма́тере твоєя́, о́тче Симео́не, да послу́жиши Єму́ во вся дні живота́ твоєго́ і да прославля́єши доброді́тельми свої́ми Пресвяту́ю Тро́йцю во ві́ки віко́в. Сві́тло сія́єть со́лнце твоєго́ і́ночеськаго жи́тельства, преподо́бне Симео́не. Ти предпоче́л єси́ земни́м уте́хам бла́га Небе́сная, ізбра́в сокро́вища некра́домая і нетлі́нная, віне́ць ца́рства земна́го ні во что же вміни́л єси́, презрі́в людські́я по́чести, держа́ву свою́ си́ну своєму́ Стефа́ну вві́рил єси́ і повелі́л єму́ пра́вити му́дре. Ни́ні восхваля́юще благоче́стіє твоє́, богому́дре, вопіє́м ті похва́льная:","Ра́дуйся, царю́ Се́рбськия землі́, Крест Христо́во возлюби́вий.","Ра́дуйся, свяще́нния Студе́ници сві́те незаходи́мий.","Ра́дуйся, побо́рниче святи́я ві́ри правосла́вния.","Ра́дуйся, блаже́нний храмозда́телю і ревни́телю красоти́ церко́вния.","Ра́дуйся, богонра́вноє і́ночеськоє житіє́ возлюби́л єси́.","Ра́дуйся, богуми́льськоє нече́стіє істреби́л єси́.","Ра́дуйся, лозо́ Се́рбськия Це́ркві многопло́дная.","Ра́дуйся, Бо́жия Ма́тері сосу́де ізбра́нний.","Ра́дуйся, ми́лости духо́вния істо́чниче преізоби́льний.","Ра́дуйся, раздая́телю благода́ті Христо́вой ще́дрий.","Ра́дуйся, мона́шеськаго воздержа́нія учи́телю преди́вний.","Ра́дуйся, апо́стольськаго преда́нія храни́телю ві́рний.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще мирськи́я сла́ви тлін і бистроте́чность, преподо́бне Симео́не, о́тче наш, мир і вся, я́же драга́я в нем, презрі́л єси́, ми́лостині преоби́льний раздая́тель яви́лся єси́ і оби́телей Бо́жиїх украси́тель бил єси́, я́ко звізда́ світоно́сная в Землі́ Се́рбськия возсія́вши. Ца́рський віне́ць і сла́ву возненави́діл єси́, блаже́нне Симео́не, мона́шеськаго чи́на взиску́я, мир оста́вил єси́, і оби́тель сві́тлую устро́їв, Богоро́дице ту́ю посвяти́л єси́, ісполня́я обі́т свяще́нний, постриже́ніє прия́л єси́, па́м'ять сме́ртную блюдя́, ло́жем гроб себі́ ізбра́л єси́, о́тче богому́дре. Крест Христо́в на ра́мена возложи́в, вопіє́ши непреста́нно Го́сподеві: Аллилу́я."]},{"h":"Ікос 2","ps":["Научи́л єси́ боголюби́вую па́ству твою́, преподо́бне о́тче Симео́не, ка́ко єсть пра́во ві́ровати во Святу́ю Тро́йцю і храни́ти святи́є догма́ти, да всі єди́ними уста́ми воспоє́м Єди́ному Бо́гу во Святі́й Тро́йці, Отцю́ і Си́ну, і Свято́му Ду́ху. Ми же, ча́да твоя́, сла́вим ві́рно І́стиннаго Бо́га, Пресвяту́ю Тро́йцю, Є́юже ти просла́влен і дарова́н нам єси́ я́ко засту́пник і хода́тай за гріхи́ на́ша, і моли́твенник Го́сподеві во ві́ки. Прийми́ недосто́йная моле́нія на́ша, прийми́ смире́нная піснопі́нія на́ша, я́же со стра́хом і любо́вію прино́сим ті, воспіва́я си́це:","Ра́дуйся, богому́дре о́тче Симео́не.","Ра́дуйся, ревни́телю ві́ри правосла́вния.","Ра́дуйся, христолюби́вий власти́тель держа́ви своєя́.","Ра́дуйся, вла́стний прогони́телю є́ресі скве́рния.","Ра́дуйся, Симео́не, благода́ті Ду́ха Бо́жия іспо́лненний.","Ра́дуйся, рабо́тниче на ни́ві Христо́вой неутоми́мий.","Ра́дуйся, подви́жниче Студе́ницькой Ла́ври неусипа́ємий.","Ра́дуйся, плод ми́лостині оби́льно Го́сподеві принеси́й.","Ра́дуйся, похвалу́ Небе́сную стяжа́вий.","Ра́дуйся, оби́телі святи́я і хра́ми воздви́гнувий.","Ра́дуйся, Святи́я гори́ тве́рдий храни́телю.","Ра́дуйся, вели́кия Хиланда́рськия Ла́ври покрови́телю.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тя, о́тче Симео́не, єгда́ возгорі́ся пла́мень алка́нія живота́ ві́чнаго в се́рдці твоє́м. Умножа́я по́двиги і труди́ своя́, всеці́ло преда́л єси́ ду́шу свою́ Защи́тнику Єди́ному, Бо́гу Живо́му і Крі́пкому і я́ко єле́нь возжажда́в духо́внаго питія́, ко Христу́ устреми́лся єси́. Ста́рче Симео́не любе́зному си́ну-ста́рцю посла́ніє отпра́вил єси́, да восхва́лять ку́пно Го́спода за вся ми́лости Єго́. Я́ко звізда́ огнезра́чная возсія́л єси́, доброді́телі я́ко лучи́ сві́та умно́жив, о́тче Симео́не, на го́ру Афо́нськую возше́л єси́, ду́шу си́на твоєго́ ра́дости ісполня́я, хвале́нія те́плия от него́ прия́л єси́. Ми же при́сно с тобо́ю і вели́ким си́ном твої́м Са́ввою воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше воі́стину по́мощ Бо́жию на вся́коє вре́м'я, о́тче Симео́не, се бо на тебі́ оправди́шися обітова́ніє псалмопе́вця-царя́, я́ко дасть ті Госпо́дь по се́рдцю твоєму́ і весь сові́т твой іспо́лнить. За́повіді Христо́ви па́че сла́ви возлюби́в, на вся́ком мі́сті жи́тельства твоєго́ тоя́ іспо́лнил єси́. От свята́го Са́вви посла́ніє получи́в, на го́ру Афо́н неме́дленно устреми́лся єси́, бу́дто глас Бо́жий усли́шавши. Лобза́нієм ра́достним і слеза́ми сві́тлими ста́рець-син ста́рця-отця́ срі́тил єси́ і єди́ними уста́ми і єди́ним се́рдцем о́ба воспе́ли хвалу́ Бо́гові і Пресвяті́й Богоро́дице. Ті́мже і ми усе́рдно воспіва́єм си́це:","Ра́дуйтеся, равноапо́стольнії отці́, Симео́не і Са́вво.","Ра́дуйтеся, сла́внаго Хиланда́ра зижди́тели.","Ра́дуйтеся, се́рбськаго подви́жничества нача́льниці.","Ра́дуйтеся, Пресвяти́я Богоро́диці служи́телі.","Ра́дуйтеся, носи́тели і́га Христо́ва ві́рнії.","Ра́дуйтеся, мно́жество оби́телей землі́ Се́рбськия украси́теліє.","Ра́дуйтеся, ві́рнії на́ші пред Бо́гом засту́пниці.","Ра́дуйтеся, кра́сноє пусти́нноє житіє́ возлюби́вшії.","Ра́дуйтеся, уго́дниці Бо́жії, вінці́ небе́сния стяжа́вшії.","Ра́дуйтеся, сироти́ і убо́гія ми́лующії.","Ра́дуйтеся, се́рбськаго і́ночества нача́льниці.","Ра́дуйтеся, се́рбськаго духове́нства світи́льници.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["По отше́ствії твоє́м, о́тче Симео́не, на Святу́ю го́ру, бу́рю ві́треннюю, нестроє́нія і ско́рби лю́тия враг на́шего спасе́нія воздви́гл єси́ в держа́ві твоє́й. Дух за́висти че́рния сино́м твої́м Ву́каном овладе́, і бра́та проти́в бра́та воздви́же, во є́же той непра́ведно віне́ць і держа́ву восхи́тить. Брань междоусо́бную возмути́л єси́ Ву́кан і сму́ту крова́вую прине́сл єси́. Кто мо́жеть ісчести́ го́ркия сле́зи і вздо́хи тя́жкия твоя́, кто не подиви́ться терпі́нію і смире́нію твоєму́ преподо́бне Симео́не. Ти бо моли́лся єси́ со слеза́ми Святі́й Засту́пнице го́ри Афо́нськия, да ізба́вить держа́ву твою́ і лю́ди твоя́ от вся́ких бід і напа́стей. Тім же і ми о Пресвяті́й Ді́ві с наде́ждой вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Єгда́ мона́си Святи́я го́ри Афо́нськия усли́шаша, царю́ Се́рбськия землі́, о приби́тії твоє́м в оби́тель Ватопе́дськую, і не узрі́ша ні вінця́ ца́рськаго, ні би́сера многоці́ннаго, но то́кмо оде́жди і́ночеськия убо́гія і сві́тлий лик твой, зіло́ удиви́шася. О́браз смире́нія і кро́тости яви́л єси́ їм, ста́рче святи́й, іспроси́вши благослове́нія і духо́вния по́мощі, я́ко іспо́лнил єси́ заві́т Христо́в, я́же смири́вий себі́ возви́ситься. Святи́й Са́вва, син твой, возвесели́лся ду́хом і возра́довался зіло́, я́ко мо́жеши єму́ помощі́. Ми же, ві́рная ча́да твоя́, прославля́юще просла́вльшаго тя Го́спода, с наде́ждою і любо́вію серде́чно вопіє́м ті:","Ра́дуйся, світи́льниче мона́шества се́рбськаго.","Ра́дуйся, Се́рбії Небе́сния зижди́телю.","Ра́дуйся, во́їне духо́вний, бісо́вськия стра́сті побіди́вий.","Ра́дуйся, засту́пниче наш пред Го́сподом неутоми́мий.","Ра́дуйся, пра́вило житія́ і́ночеськаго крестоно́снаго.","Ра́дуйся, храни́телю ві́ри правосла́вния.","Ра́дуйся, мечу́, богуми́льськую є́ресь посіка́ющий.","Ра́дуйся, сосу́де благода́ті Христо́вой і́стинний.","Ра́дуйся, царю́, оби́телі мно́гія украси́вий.","Ра́дуйся, о́тче, во іскуше́ніях тя́жких ві́ру сохрани́вий.","Ра́дуйся, святу́ю ти́хость Христо́ву стяжа́вий.","Ра́дуйся, смире́ніє па́че сла́ви возлюби́вий.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Богодарова́нне о́тче Симео́не, ти єси́ звіздо́, ві́рою і доброді́тельми сві́тло просія́вшая, ти єси́ світи́льник ве́лій, в пучи́ні морсті́й су́щим яви́вийся, научи́ нас і ни́ні заві́ти і́ночестії пра́ведно соблюсти́ і благода́ть Свята́го Ду́ха стяжа́ти нам помози́, да отве́рзуться на́ші о́чі духо́внії і у́зрим я́сно сі́ті де́монстії. Моли́ся за ни ко Го́споду, преподо́бне, да возрасте́м в благоче́стії і чистоті́, я́же Ца́рствія Небе́снаго приобщі́мся і разу́мно Пресвяті́й Тро́йце єди́ними уста́ми воспої́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Удивля́хуся ті кня́зі Царя́-гра́да ка́ко мирську́ю сла́ву і по́чести презрі́л єси́, ка́ко віне́ць ца́рський і держа́ву Се́рбськую оста́вил єси́ і, на го́ру святу́ю возше́д, крест жи́тельства і́ночеськаго на ра́мена возложи́л єси́. Духо́вния о́чі к не́бу вознесо́х, в покая́ніє погрузи́лся єси́, ко Христу́ моля́ся неуста́нно. Всі святі́ї оби́телі Афо́нстії со смире́нієм і любо́вію посіти́л єси́, о́тче Симео́не, ста́рець-син ста́рцю-отцю́ в ді́лі сем благо́м с ра́достію споспішествова́л єси́. Ті́мже вопіє́м ті, преподо́бне, прийми́ моле́нія на́ша і похвали́ на́ша не пре́зри, я́же воспіва́єм ті такова́я:","Ра́дуйся, о́тче Симео́не, во́лею Го́споду послі́довавий.","Ра́дуйся, ку́пно с си́ном-ста́рцем Са́ввою в Каре́ю прише́дий.","Ра́дуйся, святі́ї оби́телі бога́тно уще́дривий.","Ра́дуйся, Пресвяті́й Богоро́дице во Іверо́ні поклони́вийся.","Ра́дуйся, царю́ пра́ведний, ми́лостивно Го́сподом усли́шанний.","Ра́дуйся, доброді́тельми свої́ми на горі́ Святі́й Афо́нстій просія́вший.","Ра́дуйся, благи́й пало́мниче, всіх Афо́нських святи́х отце́в почти́й.","Ра́дуйся, Вели́кую Ла́вру Афана́сія красно́ одари́вий.","Ра́дуйся, блаже́нне о́тче, я́ко і́м'я твоє́ написа́ся в Кни́гі Живота́.","Ра́дуйся, я́ко світоза́рний лик твой просла́вися во вік ві́ка.","Ра́дуйся, ми́лостивний засту́пниче си́рих і убо́гих.","Ра́дуйся, от ми́сленних волко́в защити́вий о́вці слове́сния.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Мона́си і прості́ї Афо́нськия землі́ ве́лію твоєму́ нестяжа́нію удиви́шася, я́ко посто́м і моли́твою крі́пко подвиза́лся єси́, ца́рський віне́ць і держа́ву ні во что же вміни́в, кро́тость, смире́ніє і послуша́ніє і́ночеськоє ізбра́л єси́, преподо́бне. Ви́димо оби́телі Афо́нстії ми́лостинею уще́дрил єси́, в глубині́ серде́чній Го́спода возславля́я, я́ко подоба́єть і́ноку, нищету́ Христо́ву возлюби́л єси́, я́ко царю́ мно́гія оби́телі возставля́я. Прийми́ хвале́нія недосто́йних раб твої́х, о́браз смире́нія лю́дем свої́м яви́в, і в Ца́рствії Бо́жиєм Небе́сную Се́рбію сотвори́в, я́ко с любо́вію вопіє́м с тобо́ю Го́сподеві: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ли єси́ я́ко два лучу́ зві́зди у́тренняя, преподо́бне Симео́не, є́же твоє́ ца́рськоє і мона́шеськоє житіє́, ца́рствовал бо єси́ над страстя́ми свої́ми, послуша́ніє храни́л єси́ і́ночеськоє і́стинно. Світ Єва́нгельськаго Словесі́ озаря́л ду́шу твою́, преподо́бне, ре́вность по До́му Бо́жию снеда́ла тя, о́тче наш, печа́ль серде́чная о лю́діх держа́ви твоєя́ возставля́ла на моли́тву непреста́нную. Того́ же предста́тельством і нас сохрани́, Пресвята́я Тро́йце. Пом'яни́, Го́споди, оби́телі і хра́ми, я́же той воздви́гл єси́, мона́шеськоє во́їнство в Се́рбії основа́вий, пі́ніями смире́нними прославля́ємий си́це:","Ра́дуйся, благи́ми діла́ми Бо́га просла́вивий.","Ра́дуйся, святи́й лучу́ Со́лнця Ві́чнаго.","Ра́дуйся, мно́гія сироти́ і убо́гія храни́телю.","Ра́дуйся, хра́мов Бо́жиїх і оби́телей попечи́телю.","Ра́дуйся, доброді́телей істо́чник неісчерпа́ємий.","Ра́дуйся, цві́те благости́ні неув'яда́ємий.","Ра́дуйся, сла́во і похвало́ оби́телі Хиланда́рськия.","Ра́дуйся, ку́пно с преподо́бним Са́ввою в раю́ ца́рствуєши.","Ра́дуйся, преподо́бне Симео́не, звіздо́ незаходи́мая.","Ра́дуйся, цілому́дрія світи́ло ди́вноє.","Ра́дуйся, благода́ті Свята́го Ду́ха стяжа́телю.","Ра́дуйся, духо́внаго би́сера слове́снаго раздая́телю.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Єгда́ приї́де вре́м'я твоєго́ отше́ствія в Небе́сную оби́тель, преподо́бне, тогда́ усли́шал єси́ обітова́ніє от Го́спода своєго́: До́брі, ра́бе благи́й і ві́рний: о ма́лі бил єси́ ві́рен, над мно́гими тя поста́влю: вни́ди в ра́дость Го́спода твоєго́. Тогда́ же духо́внаго отця́ своєго́, вку́пі і ста́рця-си́на призва́, да вознесу́ть моле́нія ко Пресвяті́й Тро́йце о душе́ твоє́й. Са́вва преподо́бний оте́ць наш, ку́пно же с бра́тією оби́телі твоєя́ вознесли́ пі́нія і моле́нія ко Го́сподеві да при́йметь тя во оби́телі Своя́, ло́жем ті вре́тище убо́гоє послужи́ша і ізголо́вієм ка́меніє би́ша. Лобза́я о́браз Пречи́стия Ма́тере, воспі́л єси́, о́тче преподо́бне: Вся́коє диха́ніє да хва́лить Го́спода, Аллилу́я."]},{"h":"Ікос 7","ps":["Ві́рний ра́бе Христа́ Преві́чнаго яви́лся єси́, о́тче Симео́не мироточи́ве, єгда́ наста́ час отше́ствія твоєго́ в оби́телі Небе́сния, призва́л єси́ ста́рця-си́на своєго́ Са́вву преподо́бнаго, да іспо́лнить вся потре́бная по чи́ну святи́х оте́ць на́ших. Той же прости́ся с тобо́ю і возпла́ка го́рко, я́же приї́де вре́м'я уга́снути звізді́ невече́рней афо́нськаго мона́шества, ті́мже і ми воспіва́єм ті сицева́я:","Ра́дуйся, моли́твенниче наш неусипа́ємий і вселюби́мий.","Ра́дуйся, ма́слина многопло́дная і мироточи́вая.","Ра́дуйся, і́ночеських заві́тов ревни́телю.","Ра́дуйся, А́нгелов і святи́х Бо́жиїх собесі́дниче.","Ра́дуйся, лозо́ Це́ркві Се́рбськия сла́вная.","Ра́дуйся, ка́меню ві́ри Правосла́вния.","Ра́дуйся, ни́щих і сиро́т утіше́ніє і по́моще.","Ра́дуйся, неуси́пний наш пред Го́сподом моли́твенниче.","Ра́дуйся, істреби́телю вся́кия лжі і непра́вди.","Ра́дуйся, таї́нниче небе́сния благода́ті.","Ра́дуйся, святи́й хода́таю Ла́ври Хиланда́рськия.","Ра́дуйся, досто́йний носи́телю вінця́ ца́рськаго.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Все і́ночеськоє во́їнство оби́телі Хиланда́рськия жа́лостними уязви́шася се́рдці, мона́си і прості́ї возпла́каша го́рко, Са́вва преподо́бний возслези́ша і ча́да духо́внії возрида́ша, я́ко оста́вил єси́ нас, Симео́не, мироточи́ве о́тче наш, в сві́тлия оби́телі Небе́сния ду́хом всели́лся єси́, ті́лом же чу́дно с на́ми пребива́я. Па́че всіх ста́рець-син твой ско́рбен бисть, я́ко бра́та і си́на по ду́ху лиши́лся єси́, єго́же на го́ру Афо́нськую привле́кл єси́, да спасе́ніє улучи́ть. Возскорбе́ша і́ноки Афо́нстії, я́ко ми́лостивнаго дая́теля не обріто́ша, і моли́тви те́плия Го́сподеві вознесли́ єсте́, да напису́єть ті в Кни́гу Живота́ ку́пно і си́на твоєго́, о́тче Симео́не богому́дре, ми же благода́рственно поє́м Го́сподеві: Аллилу́я."]},{"h":"Ікос 8","ps":["В оби́телі Ві́чния отше́л єси́, преподо́бне о́тче Симео́не, із са́да кра́снаго, земна́го рая́, оби́телі Хиланда́рськия, є́же ку́пно с си́ном свої́м Са́ввою преподо́бним насади́л єси́, і іді́же святи́й обі́т положи́л єси́ моли́тися ко Го́споду Сил до́ндеже світи́ла небе́сная лучи́ своя́ на зе́млю іспуща́ють. При́зри на моле́нія недосто́йних чад твої́х, преподо́бне, і восхвали́ти Го́спода нам помози́, да благода́рно зове́м ті:","Ра́дуйся, насе́льниче Небе́сних оби́телей.","Ра́дуйся, тайнозри́телю Святи́я Тро́йці.","Ра́дуйся, святи́я правосла́вния ві́ри насади́телю.","Ра́дуйся, в печа́ліх і ско́рбіх ве́лій уті́шителю.","Ра́дуйся, свяще́ннаго ми́ра ціле́бний істо́чниче.","Ра́дуйся, благода́ть чудотворе́ній по кончи́ні стяжа́вий.","Ра́дуйся, наш ми́лостивний пред Бо́гом хода́таю.","Ра́дуйся, пра́ведниче, во успе́нії нас не оста́вивий.","Ра́дуйся, Ві́чнаго Живота́ наслі́дниче.","Ра́дуйся, многоці́нний Госпо́день світи́льниче.","Ра́дуйся, мирото́чними моща́ми с на́ми преби́вий.","Ра́дуйся, засту́пниче за земно́є своє́ Оте́чество ві́рний.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Бог преві́чний неізрече́нною своє́ю му́дростію, я́ко восхоті́ просла́вити тя і утіше́ніє лю́дем дарова́ти, благода́ті ве́лія іспо́лни святи́я мо́щі твоя́, я́же рі́ки ми́ра благово́ннаго істочи́л єси́ нам. По́стниче Хиланда́рський яви́лся єси́, подви́жниче гори́ Афо́нстій просла́вился єси́, помози́ ни моли́твами свої́ми, влади́ко Небе́сния Се́рбськия землі́, от враг ви́димих і неви́димих защити́ ни покро́вом свої́м, да всі совоку́пно просла́вим тя і воспоє́м просла́вльшему тя ми́ром істече́нія Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Ки́їми пі́сненними похвали́ восхва́лим твоя́ по́двиги і труди́, преподо́бне о́тче Симео́не. Ка́ко глас Бо́жий усли́шал єси́ і душе́ю во ве́чность устреми́лся єси́, іді́же всі святі́ї упокоєва́ються, ка́ко послу́шник ста́рця-си́на своєго́ яви́лся єси́ і крест і́ночеський на ра́мо своє́ воздви́гл єси́. Ви́діша Са́вва отше́ствіє твоє́ ко Го́споду і возпла́каша го́рко, ти же ли́ком просія́в сві́тло запові́дал єму́ моли́тися те́пло о душе́ своє́й. Ми же, недосто́йнії і грі́шнії раби́ твої́, мо́лимтися і взива́єм си́це:","Ра́дуйся, о́тче Симео́не, і́ноков сла́во і похвало́.","Ра́дуйся, А́нгельськими си́лами в Небе́сния оби́телі вознесе́нний.","Ра́дуйся, на́ша смире́нная моли́тви і проше́нія не презрі́вий.","Ра́дуйся, благода́ті Бо́жієй іспо́лненний.","Ра́дуйся, Ца́рствія Христо́ва сонаслі́дниче.","Ра́дуйся, ста́рче, му́дрость і́стинную стяжа́вий.","Ра́дуйся, на́ша крі́пкая наде́ждо на Небесі́ і упова́ніє.","Ра́дуйся, гори́ Афо́нстій і Держа́ви Се́рбстій ра́дованіє.","Ра́дуйся, со Христо́м соєдини́вийся.","Ра́дуйся, наш те́плий хода́таю пред Бо́гом яви́вийся.","Ра́дуйся, я́ко предстої́ши Престо́лу Святи́я Тро́йці неуси́пно.","Ра́дуйся, я́ко мо́лишися о ча́діх твої́х неотсту́пно.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Во Оте́честві я́ко чужді́й преби́л єси́, но́вий Авраа́ме Се́рбськия землі́, преподо́бне о́тче Симео́не. Ізбра́л бо єси́ Град Небе́сний і бла́га ві́чнії, сокро́вища предпоче́л єси́, іді́же ні черв, ні тля тлить, і іді́же та́тіє не подко́пивають, ні кра́дуть. Оте́чество Небе́сноє ізбра́в, плоди́ духо́внії і цві́ти небе́снії возрасти́л єси́ на ни́ві душі́ своєя́, я́ко се́рдце твоє́ преби́ше, іді́же бі сокро́вище твоє́, ті́мже Бог просла́вить тя, чудотво́рче мироточи́ве. Моли́ся за ни ко Го́споду со всі́ми святи́ми, воспіва́я красно́: Аллилу́я."]},{"h":"Ікос 10","ps":["Помо́щник і моли́твенник бисть нам, богоно́сне о́тче Симео́не, чудотво́рче мироточи́ве. Святи́я мо́щі твої́ во Оте́чество земно́є со Афо́нськия гори́ возврати́лися єси́ і чу́дом мироточе́нія просла́влени би́сте по моли́твам ста́рця-си́на твоєго́, преподо́бнаго отця́ Са́вви. Многоми́лостиве о́тче Симео́не, умоли́ Го́спода Сил, да спасе́ть ду́ші на́ша, вопію́щия ті такова́я:","Ра́дуйся, Симео́не мироточи́ве, неду́гов на́ших ісціли́телю.","Ра́дуйся, се́рбськия лю́діє ра́досте і утіше́ніє.","Ра́дуйся, вели́кия Хиланда́рськия ла́ври зижди́телю.","Ра́дуйся, Се́рбськия це́ркве прославле́ніє.","Ра́дуйся, в печа́ліх вели́кий уті́шителю.","Ра́дуйся, вінця́ нетлі́ннаго стяжа́телю.","Ра́дуйся, ско́роє скве́рния є́ресі посіче́ніє.","Ра́дуйся, неізсяка́ємий чуде́с істо́чниче.","Ра́дуйся, тайнозри́тель Пресвяти́я Тро́йці.","Ра́дуйся, учи́телю мона́шеських доброді́телей.","Ра́дуйся, святи́х кано́нов ревни́телю.","Ра́дуйся, Бо́жиїх хра́мов украси́телю.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Неісчерпа́ємоє чуде́с мо́ре всім істоча́яй, преподо́бне о́тче Симео́не мироточи́ве, ми же пі́нія похва́льная прино́сим ті немощна́я, уго́дниче Христо́в. Не отри́ни ма́лоє приноше́ніє на́ше, недосто́йних чад твої́х, святі́ї мо́щі твоя́ бо лобиза́єм і со умиле́нієм поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льниче ди́вний Се́рбськия землі́, лампа́до негаси́мая пред Го́сподем, преподо́бне о́тче Симео́не мироточи́ве, на горі́ Святі́й не восхоті́л єси́ би́ти, но в бі́лую Ла́вру Студе́ницю возврати́лся єси́, да просвіти́ться свята́я оби́тель сія́, да припаде́м к моще́м твої́м і со слеза́ми возопії́м ті такова́я:","Ра́дуйся, о́тче, явле́нієм свої́м свята́го Са́вву удиви́вий.","Ра́дуйся, я́ко преподо́бний Са́вва жела́ніє твоє́ іспо́лни.","Ра́дуйся, в святу́ю Студе́ницю возврати́вийся.","Ра́дуйся, чудеса́ми ве́ліїми просла́вленний.","Ра́дуйся, я́ко сино́в свої́х Стефа́на і Ву́кана соєдини́вий.","Ра́дуйся, вражду́ющих чад примири́вий.","Ра́дуйся, сердца́ ожесточе́нния ум'ягчи́вий.","Ра́дуйся, притека́ющих к тебі́ с ві́рою не оста́вивий.","Ра́дуйся, свяще́нним ми́ром іска́телей ми́ра пома́завий.","Ра́дуйся, немощни́х святи́м ми́ром ісціли́вий.","Ра́дуйся, благоуха́нієм духо́вним Оте́чество облагоуха́вий.","Ра́дуйся, всі́ми ві́рними с благодаре́нієм воспіва́ємий.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Прославля́юще ми́рноє преставле́ніє твоє́, преподо́бне о́тче Симео́не, воспіва́єм ті, драги́й сосу́де ду́ха Свята́го, і усе́рдно мо́лим тя, звіздо́ Се́рбськия землі́, да научи́ши ни покая́нію і да сохрани́ши от непра́вия ві́ри, да наста́виши ни на пра́вия стезі́. О, світоно́сний лучу́ святи́я Студе́ници, прославля́єм просла́вльшаго тя Го́спода, і согла́сно вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Со умиле́нієм воспіва́єм прославле́ніє твоє́, преподо́бне, ублажа́єм тя, многомо́щне наш моли́твенниче пред Го́сподем, усли́ши глас моле́нія на́шего і проше́нія пред нетлі́нними моща́ми твої́ми не пре́зри, но заступи́ і спаси́ ни, да с ра́достію благода́рні воспоє́м ті сицева́я:","Ра́дуйся, Симео́не, лозо́ многопло́дная ро́да Нема́ничей.","Ра́дуйся, похвало́ і сла́во сві́тлой Студе́ници.","Ра́дуйся, защи́тниче і світи́льниче і́ночества Се́рбськаго.","Ра́дуйся, лучу́ Сві́та Несотворе́ннаго.","Ра́дуйся, кри́не Христо́в, да́рующий ми́ро ісціле́ній.","Ра́дуйся, сві́тлая звіздо́, Бо́жия чудеса́ явля́ющая.","Ра́дуйся, красото́ Студе́ници неув'яда́ємая.","Ра́дуйся, сокро́вищнице благода́ті неізчерпа́ємая.","Ра́дуйся, істо́чниче целе́бнаго ми́ра неізсяка́ємий.","Ра́дуйся, крі́пкоє Оте́чества на́шего огражде́ніє.","Ра́дуйся, хра́мов і оби́телей ще́дрий украси́телю.","Ра́дуйся, лука́ваго змі́я сла́вний побіди́телю.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О всехва́льний, вели́кий чудотво́рче, преподо́бне о́тче Симео́не Мироточи́ве, прийми́ смире́нноє моле́ніє на́ше, в похвалу́ ті кро́тко приноси́моє, умоли́ Го́спода Сил да сохрани́ть ни во вся дні живота́ на́шего, да да́руєть ми́лость на Суді́ Стра́шнім і Вели́цім, во є́же обріте́м спасе́ніє і с тобо́ю і всі́ми святи́ми с ра́достію воспоє́м Го́сподеві: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель ізбра́ тя от чре́ва ма́тере твоєя́, о́тче Симео́не, да послу́жиши Єму́ во вся дні живота́ твоєго́ і да прославля́єши доброді́тельми свої́ми Пресвяту́ю Тро́йцю во ві́ки віко́в. Сві́тло сія́єть со́лнце твоєго́ і́ночеськаго жи́тельства, преподо́бне Симео́не. Ти предпоче́л єси́ земни́м уте́хам бла́га Небе́сная, ізбра́в сокро́вища некра́домая і нетлі́нная, віне́ць ца́рства земна́го ні во что же вміни́л єси́, презрі́в людські́я по́чести, держа́ву свою́ си́ну своєму́ Стефа́ну вві́рил єси́ і повелі́л єму́ пра́вити му́дре. Ни́ні восхваля́юще благоче́стіє твоє́, богому́дре, вопіє́м ті похва́льная:","Ра́дуйся, царю́ Се́рбськия землі́, Крест Христо́во возлюби́вий.","Ра́дуйся, свяще́нния Студе́ници сві́те незаходи́мий.","Ра́дуйся, побо́рниче святи́я ві́ри правосла́вния.","Ра́дуйся, блаже́нний храмозда́телю і ревни́телю красоти́ церко́вния.","Ра́дуйся, богонра́вноє і́ночеськоє житіє́ возлюби́л єси́.","Ра́дуйся, богуми́льськоє нече́стіє істреби́л єси́.","Ра́дуйся, лозо́ Се́рбськия Це́ркві многопло́дная.","Ра́дуйся, Бо́жия Ма́тері сосу́де ізбра́нний.","Ра́дуйся, ми́лости духо́вния істо́чниче преізоби́льний.","Ра́дуйся, раздая́телю благода́ті Христо́вой ще́дрий.","Ра́дуйся, мона́шеськаго воздержа́нія учи́телю преди́вний.","Ра́дуйся, апо́стольськаго преда́нія храни́телю ві́рний.","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний воєво́до і царю́ Се́рбськия землі́, лі́ствице сві́тлая ві́ри правосла́вния, преподо́бне Симео́не, наро́да се́рбськаго засту́пниче і святи́х хра́мов зижди́телю, святи́я Ла́ври преди́вний устрої́телю і смире́нний і́ноков наста́вниче, прийми́ моле́нія правосла́вних чад твої́х, соблюди́, о́тче наш, от єресе́й ві́ру і́стинную, держа́ву і наро́д наш от губи́телей сохрани́, ві́рноє ста́до твоє́ от лю́тих волко́в огради́ і свяще́нния догма́ти церко́вния защити́. Прийми́ на́ша пі́нія і похвали́, я́же смире́нно прино́сим ті, і моле́ній нас, грі́шних, не пре́зри, із глубини́ серде́чния вопію́щия:","Ра́дуйся, преподо́бне о́тче Симео́не Мироточи́вий, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О преподо́бне о́тче Симео́не, Студе́ницький чудотво́рче. Влади́ко Се́рбськия землі́ Стефа́не і мона́шества похвале́ніє Симео́не преди́вний, во дні земна́го ца́рствія твоєго́ нікто́же неуті́шен оти́де от тебе́, но всім ра́дость і утіше́ніє ми́лостивно дарова́л єси́. Упаси́ виногра́дник твой, о́тче преподо́бне, да не пре́дани бу́дем в сі́ті сатани́, змі́я лука́ваго. Просвіти́ о́чі на́ша с висоти́ Небе́сния, да плі́на гріхо́внаго ізбі́гнем. Посіти́, сві́те, не́мощ на́шу, вразуми́ і напра́ви ни на стезі́ свя́тости, да ніколи́же оста́вить ни люби́ Бо́жия, да не престає́ть моли́тва твоя́ заступа́ти Оте́чество твоє́. О богоно́сне чудотво́рче, я́ко зві́зди небе́снії просія́ли чудеси́ твоя́ во всіх земля́х христия́нських. Да́руй нам от скве́рних гріхо́вних страсте́й свобожде́ніє і введи́ ни во ві́чноє Ца́рство Животворя́щей і Неразді́льній Тро́йці, да ми с тобо́ю і всі́ми святи́ми бу́дем ві́чно прославля́ти і сла́вити Бо́га. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Боже́ственною благода́тію просвіти́вся, / і по сме́рті показу́єши сві́тлость житія́ твоєго́, / істоча́єши бо ми́ро благоуха́нія / притека́ющим к ра́ці моще́й твої́х, / і лю́ди твоя́ наста́вил єси́ к сві́ту Богоразу́мія, / Симео́не о́тче наш, / Христа́ Бо́га моли́ // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 6","ps":["А́нгельськоє возлюби́в на землі́ житіє́, / миродержа́ніє і мир оста́вив, / поще́нієм Христу́, Симео́не, послі́довал єси́, / к Нему́же лю́б'ящих тя апо́стольськи наста́вил єси́, вопія́: // возлюбі́те Бо́га, я́коже Он возлюби́ нас."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Симео́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Никиті Печерському, єпископу Новгородському","e":"Akathist to St Nicetas of the Caves, Bishop of Novgorod","secs":[{"h":"Кондак 1","ps":["Возбра́нний воєво́до і па́стирю свяще́ннійший Вели́каго Нова́града, Це́ркве утвержде́ніє, Христо́в ієра́рше Ники́то, прийми́ от нас усе́рдно приноси́мая тебі́ благохвале́нія і твої́ми моли́твами от бід і напа́стей ізбавля́й всегда́ любо́вію тебі́ зову́щих:","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті на землі́ яви́лся єси́ воі́стину чу́дний Ники́то, с пло́тію бо я́ко безпло́тен пожи́л єси́, ті́мже, со безпло́тними ни́ні водворя́яся, прийми́ от нас земноро́дних піснь сію́:","Ра́дуйся, Ники́то, А́нгелов равностоя́телю.","Ра́дуйся, ієра́рше, преподо́бних сожи́телю.","Ра́дуйся, власть пасти́ слове́сния о́вці от Бо́га прия́вий.","Ра́дуйся, сві́том твої́х уче́ній па́ству твою́ осія́вий.","Ра́дуйся, преди́вний цілому́дрія храни́телю.","Ра́дуйся, по́стничеськаго житія́ і́стинний люби́телю.","Ра́дуйся, світоза́рная мо́лніє, Но́вград Вели́кий ве́село озаря́ющая.","Ра́дуйся, луче́ світосія́нная, де́монськую тьму разгоня́ющая.","Ра́дуйся, ра́дости ві́рним пода́телю.","Ра́дуйся, в печа́ліх і болі́зніх на́ших ско́рий предста́телю.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 2","ps":["Ви́дяще стра́нний і чу́дний житія́ твоєго́ о́браз, Христо́в святи́телю Ники́то, вельми́ удивля́ємся, размишля́юще же твоя́ многотру́дния по́двиги, поє́м Бо́гу на сія́ тебі́ укріпи́вшему: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний пода́ждь нам сви́ше, ієра́рше, да возмо́жем по достоя́нію восхвали́ти доброді́тельноє твоє́ житіє́, тебі́ же любо́вію вопи́ти:","Ра́дуйся, мно́гими доброді́тельми просія́вий.","Ра́дуйся, пло́ті твоєя́ жела́нія обузда́вий.","Ра́дуйся, ра́зум твой в послуша́ніє ві́ри пліни́вий.","Ра́дуйся, се́рдце твоє́ чи́сто сохрани́вий.","Ра́дуйся, ра́зумом Христо́вим обогати́вийся.","Ра́дуйся, я́ко а́нгел в житії́ твоє́м яви́вийся.","Ра́дуйся, разруши́телю страсте́й душетлі́нних.","Ра́дуйся, сокро́вище слове́с богодухнове́нних.","Ра́дуйся, гро́зноє бісо́вськоє устраше́ніє.","Ра́дуйся, пречу́дноє в челові́ціх удивле́ніє.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго от ю́ности осіни́ тя, богому́дре, і показа́ селе́ніє і дом Ду́ха Всесвята́го, Єму́же і о нас помоли́ся, о́тче че́стне, тя ублажа́ющих, Бо́гу же зову́щих: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще вели́ка тя, о, Ники́то, засту́пника і ско́раго в напа́стіх помо́щника, моле́бно тебе́ призива́єм і с весе́лієм к па́м'яті твоє́й воспіва́єм:","Ра́дуйся, ско́рий послу́шателю к тебі́ прибіга́ющих.","Ра́дуйся, скорб'я́щим душа́м утіше́ніє.","Ра́дуйся, отча́янних ісправле́ніє.","Ра́дуйся, Судію́ Пра́веднаго за грі́шния лю́ди умоля́яй.","Ра́дуйся, чту́щия тя от печа́лі і бід ізбавля́яй.","Ра́дуйся, унива́ющих всежела́нний посіти́телю.","Ра́дуйся, неду́жних ми́лостивейший ціли́телю.","Ра́дуйся, уго́дниче Христо́в преізря́дний.","Ра́дуйся, цві́те ра́йський прекра́сний.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й многом'яте́жнаго ми́ра возненави́дів, о́тче, всіх красо́т єго́ устрани́лся єси́, во оби́тель же всели́вся і а́нгельський чин восприї́м, со А́нгели піл єси́ Христо́ві: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав христоподража́тельную жизнь богоно́сних і вели́ких оте́ць, тім в житії́ уподо́битися возревнова́л єси́, сего́ ра́ди в затво́р всели́вся, сугу́бим по́двигом себі́ предає́ши, ті́мже досто́йно сли́шиши:","Ра́дуйся, подви́жниче Бо́жий преусе́рднейший.","Ра́дуйся, мона́шествующих превели́кая сла́во.","Ра́дуйся, святи́х пустинножи́телей доброді́тельними обогати́вийся нра́ви.","Ра́дуйся, равноа́нгельно Бо́гу послужи́вий.","Ра́дуйся, А́нгелом ра́вную і честь получи́вий.","Ра́дуйся, до́блій і́ночеських по́двигов ревни́телю.","Ра́дуйся, усе́рдний Христо́вих за́повідей ісполни́телю.","Ра́дуйся, вра́жиїх наві́тов бо́дрий прогони́телю.","Ра́дуйся, соверше́нства христия́нськаго ізя́щнійший учи́телю.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 5","ps":["Боготе́чнаго твоєго́ житія́ не терп'я́, человіконенави́стник іскуше́ніє льсти́вно тебі́ подлага́єть, во о́бразі а́нгела тебі́ яви́вся і преста́ти моли́тися научи́в: ти же а́ще і прельще́н бил єси́ хи́тростію єго́, оба́че не до конця́ поги́бл єси́ во іскуше́нії; моли́твами бо бра́тії спасе́н, Христу́ вопія́л єси́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще і́ноці стра́нную вещ на тебі́ явля́ємую, я́ко от ве́тхих то́кмо Боже́ственних Писа́ній к тебі́ приходя́щих поуча́єши, от Но́ваго же Заві́та нічесо́же глаго́ля, уразумі́ша прельще́на би́ти тя, преподо́бне, сего́ ра́ди о́бщую о тебі́ моли́тву сотво́рше, дия́вола отгоня́ють і із затво́ра ізво́дять тя. Ми же тебі́, я́ко самому́ іскуше́ну би́вшу і нам іскуша́ємим помога́ти могу́щу, не престає́м зва́ти:","Ра́дуйся, от врага́ человікоуби́йці лю́ті пострада́вий.","Ра́дуйся, всю глубину́ бісо́вськия ле́сти на себі́ іспита́вий.","Ра́дуйся, моли́твами подви́жников от ро́ва поги́белі восхище́нний.","Ра́дуйся, от рабо́ти дия́воли Го́сподем освобожде́нний.","Ра́дуйся, на неви́димия враги́ і нам крі́пкий помо́щниче.","Ра́дуйся, во іскуше́ніїх жите́йських всегда́шній нам посо́бниче.","Ра́дуйся, прило́г вся́каго зла от чту́щих тя отража́яй.","Ра́дуйся, всему́ благо́му вход отверза́яй.","Ра́дуйся, бісо́вськия си́ли крі́пкоє низложе́ніє.","Ра́дуйся, гріхми́ пове́рженних тве́рдоє возведе́ніє.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дници твоєго́ спасе́нія би́вше і́ноці Пече́рстії, от дия́вола тя ісхи́тивше, на і́стинний путь наставля́ють: ти же, о́тче Ники́то, позна́в го́ркоє твоє́ прельще́ніє, покая́ніє со слеза́ми Бо́гу прине́сл єси́, моля́ся і зови́й: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко світоза́рноє со́лнце на тве́рди церко́вній, дия́вола іскуше́нія ізбі́г і по́стничеськими по́двиги укріпи́вся: ті́мже і нас наві́тов лука́ваго свободи́, да зове́м ті:","Ра́дуйся, крест твой терпіли́вно на ра́мі носи́вий.","Ра́дуйся, ми́сленнаго тім Амали́ка низложи́вий.","Ра́дуйся, дарова́нія Боже́ственнаго Ду́ха прия́вий.","Ра́дуйся, в житії́ стра́ждущим ми́лостивно помога́яй.","Ра́дуйся, те́плі к тебі́ притека́ющих треволне́нія страсте́й ізміня́яй.","Ра́дуйся, оби́димих ско́рий засту́пниче.","Ра́дуйся, обурева́ємих благопопечи́тельний защи́тниче.","Ра́дуйся, би́стрий спаси́телю в напа́стіх су́щим.","Ра́дуйся, скоропредста́тельний помо́щниче зову́щим.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 7","ps":["Хотя́ Христо́с Госпо́дь, Вели́кий Архієре́й, святи́тельською украси́ти тя вла́стію, на свяще́нний престо́л Вели́каго Нова́града возво́дить тя, на нем же возсі́д, світи́ло многосві́тлоє гра́ду твоєму́ яви́лся єси́, всіх просвіща́я і зва́ти Бо́гу науча́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вград Вели́кий приї́м тя от Го́спода па́стиря і учи́теля, ра́довашеся, преподо́бне, зря твої́х доброді́телей ісправле́ніє, і в пі́сніх свяще́нних дони́ні взива́єм тебі́:","Ра́дуйся, учи́телю свяще́ннійший, от Бо́га нам дарова́нний.","Ра́дуйся, архієре́ю Бо́жий святи́й предизбра́нний.","Ра́дуйся, усе́рдний благові́рія побо́рниче, і у́ме височа́йший.","Ра́дуйся, Христо́вих велі́ній пропові́дниче сладча́йший.","Ра́дуйся, Вели́каго Нова́града пречу́дноє украше́ніє.","Ра́дуйся, безкро́вния же́ртви непоро́чно Бо́гу приноси́вий.","Ра́дуйся, во ві́рі Правосла́вній па́ству твою́ утверди́вий.","Ра́дуйся, я́ко мно́гия просвіти́л єси́ твої́м архипа́стирським сло́вом.","Ра́дуйся, святи́телю, і нас твої́х чад сподо́би ста́ти пред Бо́жиїм престо́лом.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 8","ps":["Стра́нно Бо́га вочелові́чшася на́шего ра́ди спасе́нія па́стві твоє́й пропові́дал єси́, Ники́то, і і́дольських суєві́рій мрак разгна́л єси́, Іпоста́сній Прему́дрості зови́й: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ всім в па́стві твоє́й ско́рий помо́щник, святи́телю, засту́пник оби́димим, ни́щим пита́тель, си́рим і вдови́цям защи́тник, на похвалу́ всіх подвиза́я вопи́ти тебі́:","Ра́дуйся, во вся́ких ну́ждах ско́роє поможе́ніє.","Ра́дуйся, в печа́ліх би́строє утіше́ніє.","Ра́дуйся, от оби́д і озлобле́ній свобожда́яй.","Ра́дуйся, о́гненнаго запале́нія град твой ізбавля́яй.","Ра́дуйся, ми́лости сокро́вище многоці́нноє.","Ра́дуйся, бога́тство нам подава́яй нетлі́нноє.","Ра́дуйся, обурева́ємих приста́нище ти́хоє.","Ра́дуйся, гони́мих і оби́димих прибі́жище вели́коє.","Ра́дуйся, мно́гія лю́ди от поги́белі ісхи́тивий.","Ра́дуйся, о́вці твоя́ от во́лка лю́таго сохрани́вий.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 9","ps":["Вся́кий род і во́зраст ві́рних Вели́каго Нова́града усе́рдно чтить сві́тлий день твоєя́ па́м'яті, святи́телю Ники́то, в о́ньже собра́вшеся моле́бно зове́м ті: бу́ди нам в печа́ліх уті́шитель, в озлобле́ніїх помо́щник, в болі́зніх врач ско́рий, да тобо́ю злих ізба́вльшеся ра́достно зове́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий язи́к не мо́жеть по достоя́нію ізобрази́ти все вели́чіє любве́ твоєя́ к твоєму́ слове́сному ста́ду, приснопа́м'ятне, не то́чію бо во вре́менній твоє́й жи́зні, но і к небе́сним отше́д, оте́чеськи назира́єши всіх вопію́щих к тебі́ с любо́вію такова́я:","Ра́дуйся, наста́вниче превели́кий спасе́нія.","Ра́дуйся, согріша́ющих ісправле́ніє.","Ра́дуйся, земни́я сла́сти презрі́вий.","Ра́дуйся, в го́рнія оби́телі возлеті́вий.","Ра́дуйся, Це́рков Нова́града святи́тельством украси́вий.","Ра́дуйся, чад твої́х богому́дренними глаго́ли просвіти́вий.","Ра́дуйся, лю́б'ящих тя неізрече́нния ісполня́яй ра́дости.","Ра́дуйся, я́ко твої́ми моли́твами ві́чния сме́рти свобожда́ємся.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́ще ві́рнії от бід і скорбе́й, ко гро́бу твоєму́ свяще́нному моле́бно притека́єм. Ти же, о, чудотво́рче святи́й, помози́ нам, немощни́м, утоли́ скорб на́шу і на путь пра́вий заблужда́ющих наста́ви нас, да спасе́ннії тобо́ю, хвале́бними гла́си зове́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і покро́в ти єси́, о́тче, всім челові́ком с ві́рою к тебі́ прибега́ющим, ті́мже і нам, прося́щим твоєго́ заступле́нія, бу́ди огражде́ніє крі́пкоє, да в тебі́ утвержда́ющеся всегда́ вопіє́м:","Ра́дуйся, бі́ди і печа́лі от лю́б'ящих тя отгоня́яй.","Ра́дуйся, всім тебі́ призива́ющим ско́рую по́мощ подава́яй.","Ра́дуйся, крі́посте і огражде́ніє благочести́вих.","Ра́дуйся, гро́зний наказа́телю нечести́вих.","Ра́дуйся, от честни́х моще́й ісціле́ніє неоску́дно істоча́яй.","Ра́дуйся, жела́ємих нам благ насади́телю.","Ра́дуйся, находя́щих напа́стей отгони́телю.","Ра́дуйся, наді́ющихся на тя защище́ніє.","Ра́дуйся, душ на́ших сла́дкоє утіше́ніє.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 11","ps":["Пі́нія всеумиле́нная приноша́ху тебі́ лю́діє Новогра́дстії во обрі́тенії твої́х многоціле́бних моще́й, святи́телю, от них же і чудеса́ ве́лія с ві́рою приходя́щим яви́л єси́, Бо́гу, во святи́х Свої́х Ди́вному науча́я пі́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, на сві́щниці гра́да на́шего возсія́вшую, зрим тебі́, всесвяще́ннейший о́тче Ники́то, блиста́нієм бо чуде́с всіх озаря́єши, любо́вію тебі́ зову́щих:","Ра́дуйся, звіздо́ небосві́тлая, от ю́га Украї́ни возсія́вшая.","Ра́дуйся, Но́вград Вели́кий сія́нієм твої́м облиста́вшая.","Ра́дуйся, во сві́ті невече́рнім обита́яй.","Ра́дуйся, і нам во мра́ці гріхо́внім блужда́ющим просвіще́ніє низпосила́яй.","Ра́дуйся, свіще́, Боже́ственним пла́менем возжже́нная.","Ра́дуйся, світи́льниче Христо́в де́монськими ві́три не угаше́нний.","Ра́дуйся, єго́же восходя́ща на го́рняя А́нгели сріто́ша.","Ра́дуйся, єму́же ра́йськая врата́ с весе́лієм отверзо́ша.","Ра́дуйся, со Христо́м ликовству́яй во сла́ві.","Ра́дуйся, Трисія́нния Зари́ наслажда́яйся я́ві.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам у Спа́са Христа́, о́тче преподо́бний, простри́ нам ру́ку по́мощі, покри́й нас те́плим твої́м заступле́нієм, і ві́чния ра́дости сподо́би дости́гнути, да с тобо́ю во ві́ки віко́во вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ до́блественния по́двиги, ублажа́єм достохва́льную кончи́ну, торжеству́єм же і па́м'ять твою́ свяще́нную, преподо́бне, і, чудя́щеся житію́ твоєму́, похва́льная тебі́ вопіє́м:","Ра́дуйся, в го́рнія оби́телі превознесе́нний.","Ра́дуйся, в небе́сния черто́ги со сла́вою введе́нний.","Ра́дуйся, сла́ви отце́в преі́скренні возжела́вий.","Ра́дуйся, преми́рноє наслі́діє бога́тно восприя́вий.","Ра́дуйся, святи́тельським вінце́м увінча́нний.","Ра́дуйся, за чту́щих тя моли́твенниче неуста́нний.","Ра́дуйся, посіти́телю в не́мощіх лежа́щих.","Ра́дуйся, уті́шителю уни́лих і скорб'я́щих.","Ра́дуйся, с небе́сних круго́в на моле́нія на́ша ми́лостивно призира́яй.","Ра́дуйся, чту́щих тя проше́нія ско́ро ісполня́яй.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 13","ps":["О, всехва́льний і преди́вний святи́телю Христо́в Ники́то! Прийми́ усе́рдно ма́лоє сіє́, от нас грі́шних приноси́моє, моле́ніє і потщи́ся ско́ро умоли́ти Бо́га і Влади́ку, да ізба́вить нас от вся́ких бід і озлобле́ній і бу́дущия му́ки свободи́ть зову́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті на землі́ яви́лся єси́ воі́стину чу́дний Ники́то, с пло́тію бо я́ко безпло́тен пожи́л єси́, ті́мже, со безпло́тними ни́ні водворя́яся, прийми́ от нас земноро́дних піснь сію́:","Ра́дуйся, Ники́то, А́нгелов равностоя́телю.","Ра́дуйся, ієра́рше, преподо́бних сожи́телю.","Ра́дуйся, власть пасти́ слове́сния о́вці от Бо́га прия́вий.","Ра́дуйся, сві́том твої́х уче́ній па́ству твою́ осія́вий.","Ра́дуйся, преди́вний цілому́дрія храни́телю.","Ра́дуйся, по́стничеськаго житія́ і́стинний люби́телю.","Ра́дуйся, світоза́рная мо́лніє, Но́вград Вели́кий ве́село озаря́ющая.","Ра́дуйся, луче́ світосія́нная, де́монськую тьму разгоня́ющая.","Ра́дуйся, ра́дости ві́рним пода́телю.","Ра́дуйся, в печа́ліх і болі́зніх на́ших ско́рий предста́телю.","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Кондак 1","ps":["Возбра́нний воєво́до і па́стирю свяще́ннійший Вели́каго Нова́града, Це́ркве утвержде́ніє, Христо́в ієра́рше Ники́то, прийми́ от нас усе́рдно приноси́мая тебі́ благохвале́нія і твої́ми моли́твами от бід і напа́стей ізбавля́й всегда́ любо́вію тебі́ зову́щих:","Ра́дуйся, те́плий засту́пниче наш Ники́то, святи́телю преди́вний."]},{"h":"Молитва","ps":["О, архієре́ю Бо́жий, святи́телю Ники́то, усли́ши нас, грі́шних раб твої́х, сте́кшихся днесь в свяще́нний храм сей, моля́щихся тебі́ і к свяще́нній твоє́й ра́ці притека́ющих, і умиле́нно вопію́щих: я́коже сідя́ на престо́лі святи́тельства во Вели́ком Нові́граді сем, і єди́ною належа́щу бездо́ждію, дождь моли́твами свел єси́, і па́ки гра́ду сему́ о́гненним пла́менем обше́дшу, моли́твою пла́мень о́гненний угаси́л єси́. І ни́ні мо́лим тя: о, святи́телю Христо́в Ники́то, моли́ся ко Го́споду, є́же ізба́вити Вели́кий град Но́вград сей і вся гра́ди і страни́ христия́нськия от тру́са, пото́па, гла́да, огня́, гра́да, меча́ і от всіх враго́во ви́димих і неви́димих, я́ко да ізбра́нних ра́ди моли́тв твої́х спаса́ємі, сла́вим Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха і твоє́ ми́лостивноє предста́тельство, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Наслади́вся, Богому́дре, воздержа́нія / і жела́ніє пло́ті твоєя́ обузда́в, / на престо́лі святи́тельства сел єси́, / і я́ко звізда́ многосві́тлая, просвіща́я ві́рних сердця́ / заря́ми чуде́с твої́х, / о́тче наш, святи́телю Ники́то, / і ни́ні моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Інший тропар, глас 2","ps":["Небе́снаго простра́нства жела́я, / от ю́ности в ті́сні мі́сті затвори́лся єси́, / в не́мже прельще́н бив от врага́, / па́ки смире́нієм і послуша́нієм побіди́л єси́ преле́стника крі́пці, Ники́то, / і ни́ні, предстоя́ Христо́ві, // моли́ спасти́ся всім нам."]},{"h":"Кондак, глас 6","ps":["Архієре́йства са́ном почти́вся / і чи́сті Чисті́йшему предстоя́, / прилі́жно моле́ніє за лю́ди твоя́ приноси́л єси́, / я́ко і дождь моли́твою свел єси́, / овогда́ же і гра́да запале́нія угаси́л єси́. / І ни́ні, святи́телю Ники́то, / моли́ Христа́ Бо́га, / спасти́ лю́ди твоя́ моля́щіяся, / да всі вопіє́м ті: // ра́дуйся, святи́телю, о́тче преди́вний."]},{"h":"Інший кондак, глас 1","ps":["Побіди́во вра́жия ле́сти до́блі / і сві́тло доброді́тельми просія́в, / святи́тельства оде́ждою обле́клся єси́, пресла́вне Ники́то, / в не́мже сві́том житія́ твоєго́ і чудеси́ сія́я па́че со́лнця, / мно́гих просвіти́в, приве́л єси́ Христо́ві, // Єго́же моли́ о нас, пою́щих тя."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Ники́то, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Іову, ігумену Почаївському","e":"Akathist to our Venerable Father Job, Abbot of Pochaiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Го́спода, благи́й ра́бе і ві́рний, уго́дниче Христо́в, преподо́бне о́тче наш І́ове, твої́м заступле́нієм і предста́тельством огражда́єми, похва́льная воспису́єм ті, пові́дающе благи́я по́двиги і чудеса́ твоя́, і благода́рственная возсила́єм моле́нія просла́вльшему тя Го́споду і Царю́ сла́ви. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду і Пречи́стій Єго́ Ма́тері, Присноді́ві Богоро́дице, от вся́ких нас бід свободи́, зову́щих ті:","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Ікос 1","ps":["А́нгела земна́го нра́вом і челові́ка небе́снаго житіє́м соді́ла тя Влади́ка а́нгелов і всея́ ви́димия і неви́димия тва́рі; ті́мже просла́вив тя, я́ко сообра́зна я́вльшася предуві́дінію Єго́, благоволи́л єсть і нам яви́ти сла́вноє житіє́ і пренебе́сноє прославле́ніє твоє́, да воспіва́єм ті си́це:","Ра́дуйся, от утро́би ма́тернія ізбра́нний на по́двиг служе́нія Царю́ Небе́сному;","Ра́дуйся, і́менем Іоа́нна, благода́ті тезоімени́таго, і́мже по рожде́нії нарече́н бил єси́, я́ко печа́тію благода́ті запечатле́нний.","Ра́дуйся, я́ко прия́л єси́ і́м'я Крести́теля Госпо́дня, єму́же пустиннолю́бним житіє́м до́брі поревнова́л єси́;","Ра́дуйся, я́ко ізмла́да усли́шал єси́ вну́тренній глас призва́вшаго тя Го́спода.","Ра́дуйся, я́ко десятоле́тен сий, сему́ гла́су охо́тно послі́дуя, уклони́лся єси́ от о́чію люби́мих ті роди́телей і во оби́телі Уго́рницькой всели́лся єси́;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дяще і́ноці Уго́рницькії доброді́тельноє житіє́ твоє́ і благи́я нра́ви, уго́дниче Бо́жий, по двою́ лі́тіх кро́ткаго і трудолю́бнаго послуша́нія твоєго́ во оби́телі своє́й, возложи́ша на тя а́нгельський чин, і, я́коже предобразу́я многотру́дния по́двиги твоя́, я́же Христа́ ра́ди под'я́ти імі́л єси́, І́овом тя нареко́ша, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум сви́ше літ подава́я тебі́, Бог ра́зумов умудри́ тя во ві́дінії сих, я́же ко спасе́нію, я́ко преуспіва́ти тебі́ в путі́ Госпо́дні і благопоспіши́ти па́че всіх, су́щих во оби́телі. Ті́мже і на сте́пень свяще́нства, а́ще і по мно́зім отриця́нії твоє́м, а́біє во урече́нний во́зраст подведе́н бил єси́. Сих ра́ди прийми́ от нас хвале́бная пі́нія сія́:","Ра́дуйся, сві́том ра́зума Боже́ственнаго от ю́ности твоєя́ осія́нний;","Ра́дуйся, во сві́ті лиця́ Бо́жия тьму неві́дінія і плотськи́х мудрова́ній во всем житії́ твоє́м от себе́ отгна́вий.","Ра́дуйся, розго́ плодоно́сная, ді́ли богоуго́дними приви́тая к і́стинной лі́торасли вертогра́да Госпо́дня;","Ра́дуйся, кри́не, прозя́бший благоче́стіє от роси́ Ду́ха Свята́го.","Ра́дуйся, кла́се, плод духо́вной ві́ри, наде́жди і любве́ боже́ственния стори́цею прине́сший;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, є́юже облече́н бил єси́ во уго́дноє благода́ті Боже́ственния ору́діє, толи́кий пла́мень ре́вности Бо́жия возжже́ в се́рдці твоє́м, я́ко неуси́пнаго ра́ди хвале́нія Го́спода і вели́кий а́нгельський о́браз по рукоположе́ні вско́рі восприя́ти ізво́лил єси́, і́менем Іоа́нна во схимона́сіх па́ки нарече́нний, я́ко іспо́лнь сугу́бия благода́ті Бо́жия і нави́кнувий пі́ти непреста́нно серафи́мськую піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи дарова́нія многоразли́чная от Го́спода, воі́стину не возмо́гл єси́ утаї́тися от совреме́нник твої́х, от ни́хже мно́зі нача́ша приходи́ти к тебі́ по́льзи ра́ди душе́вния; благочести́вий же Остро́жський князь Константи́н іспроси́ тя во оби́тель свою́ Кре́стную на о́строві Ду́бенстем, іді́же і во ігу́мена вско́рі поста́влен бил єси́, науча́я всіх зва́ти тебі́:","Ра́дуйся, вмісти́лище всіх сокро́вищ Госпо́дніх;","Ра́дуйся, раздая́телю коєму́ждо на по́льзу даро́в духо́вних, я́же прия́л єси́ от Го́спода.","Ра́дуйся, я́ко ревну́я по правосла́вію, во оби́телі Ду́бенстей писа́нієм книг боже́ственних проти́ву у́нії, тогда́ пе́рвіє яви́вшейся, богому́дренно упражня́лся єси́;","Ра́дуйся, я́ко сего́ ра́ди і бра́тію свою́ на по́двиг распростране́нія правосла́вних книг богому́дренно подвиза́л єси́.","Ра́дуйся, я́ко благослове́нію твоєму́ і внуше́нію, є́же от Ду́ха Свята́го, послі́дуя, Остро́жський князь первопеча́тную слове́нськую Би́блію во утіше́ніє ві́рних тисне́нію предаде́;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 4","ps":["Вре́менния че́сти, є́юже стужа́ху ті мно́зі от правосла́вних, ку́пно же і озлобле́ній многоразли́чних за любо́в к Правосла́вію от клевре́тов у́нії хотя́ ізба́витися, уми́слил єси́ ізбі́гнути от нача́льства, є́же вя́щши два́десяти літ імі́л єси́ на о́строві Ду́бенстем. Сего́ ра́ди тай оста́вил єси́ оби́тель свою́ Кре́стную, і, во є́же сокри́тися от треволне́ній ми́ра сего́ мном'яте́жнаго, во о́бразі проста́го і́нока прите́кл єси́ на го́ру Поча́євськую, іздре́вле сві́тлостію чуде́с премно́гих сія́ющую, зови́й Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Усли́шаша і уразумі́ша се́рдцем і душе́ю і́ноці Поча́євстії преізби́точествующий в тебі́ істо́чник благода́ті Бо́жия, о́тче наш І́ове, я́ко сицева́го тя наста́вника зіло́ подви́жна і іску́сна благоволи́ імі́ти Пресвята́я Богоро́диця во Своє́й, небесі́ подо́б'ящейся, оби́телі; ті́мже о́бщим моле́нієм со слеза́ми а́біє во ігу́мена себі́ поста́виша тя, взива́я тебі́:","Ра́дуйся, гра́де, верху́ гори́ стоя́й і ізоби́луяй ви́шніми добро́тами;","Ра́дуйся, сокро́вищнице, богатя́щая нас духо́вними би́сери.","Ра́дуйся, сто́лпе, указу́яй путь пра́вий хотя́щим обрісти́ єго́;","Ра́дуйся, світи́ло, на за́паді Украї́ни в просвіще́ніє на́ше возсія́вшеє.","Ра́дуйся, по сліда́м всеблаже́ннаго Феодо́сія Кі́єво-Пече́рськаго о́бщих житі́й на горі́ Поча́євстій первонача́льниче;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ уподо́бился єси́, всеблаже́нне, сія́я ді́ли благи́ми і богоуго́дними на горі́ Поча́євстій; ї́хже ра́ди мно́зі во слід тебе́ направля́ху стопи́ своя́ от распу́тій гріхо́вних, о́вії у́бо на ну́жди оби́телі твоєя́ от імі́ній свої́х принося́ще, о́вії же отце́м духо́вним во іспові́даніє гріхо́в свої́х нарочи́то тебі́ ізбира́юще, я́ко всім о тебі́ Бо́гу служа́щим і тобо́ю на спасе́нія стезі́ наставля́ємим, со дерзнове́нієм пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів тя ієросхимона́х Досифе́й, учени́к твой, уго́дниче Бо́жий, дре́внім отце́м в житії́ своє́м послі́дующа, начерта́ нам пресла́вная діла́ і вели́кия по́двиги твої́; і́мже удивля́ющеся, сицеви́м вінча́єм тя пісносло́вієм:","Ра́дуйся, я́ко в ті́сній і те́мній пеще́рі гори́ Поча́євськия та́йно от взо́ров челові́чеських многолі́тні свя́то подвиза́лся єси́;","Ра́дуйся, я́ко іногда́ чрез три дні, овогда́ же чрез ці́лую седьми́цю єди́н в пеще́рі той богоми́слія ра́ди затворе́н бил єси́.","Ра́дуйся, я́ко єди́ною моля́щуся ті внутр єя́, облиста́ тя світ неізрече́нний, на до́лзі не престая́ осіява́ющи сопреде́льную с пеще́рою це́рков;","Ра́дуйся, я́ко ничи́мже, то́чію слеза́ми, із глубини́ серде́чния ізлива́ющимися, во времена́ о́ни пита́вийся.","Ра́дуйся, я́ко необи́чнаго ра́ди ізможде́нія пло́ті і до́лгих стоя́ній согни́ на нога́х ті́ло твоє́ і да́же от косте́й отпада́ше;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дивати Правосла́віє жела́я во страна́х свої́х, всеблаже́нне, я́коже на о́строві Ду́бенстем, си́це і на горі́ Поча́євстій, кни́ги боже́ственния в поуче́ніє ві́рним подава́л єси́, єще́ же і ти́пом печа́тати ти́я во своє́й типогра́фії Поча́євстій повеліва́л єси́ і ку́пно с ни́ми посла́нія архієре́йськая і моли́тви многоразли́чния, во є́же всім, чту́щим їх і по о́нім моля́щимся, пі́ти Бо́гу нело́жно: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко заря́, не от восто́ка, но от за́пада Украї́нськаго восходя́щая, уго́дниче Бо́жий, єгда́ нужд ра́ди церко́вних от обдержа́щія у́нії бил єси́ в богоспаса́ємом гра́де Ки́єве на собо́рі святи́х оте́ць, іді́же во святі́й Кі́єво-Пече́рськой Ла́вре, єя́же преподо́бними отця́ми, от зла́го наше́ствія Бати́єва спаса́вшимися, і оби́тель Поча́євськая дре́вле основа́ся, кля́твенно обіща́лся єси́ ку́пно со іни́ми во ві́рі правосла́вній, оте́честій крі́пко і неізмі́нно стоя́ти, ніколи́же і ніка́коже о отступле́нії в інове́ріє не ми́слити і к сему́ всеукраї́нський наро́д увіщава́ти, да сли́шиши от всіх:","Ра́дуйся, я́сноє зерца́ло апо́стольських преда́ній;","Ра́дуйся, живоприї́мний істо́чниче і́стинних кафоли́чеських пра́вил.","Ра́дуйся, єрети́чеських басносло́вій прему́дрий істреби́телю;","Ра́дуйся, глубини́ правосла́вних догма́тов іску́сний ізме́рителю.","Ра́дуйся, боже́ственний орга́не, возшуми́вший нам уче́ніє спаси́тельноє;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ Христо́с Госпо́дь і Преблага́я, Пречи́стая Ма́тер Єго́ яви́ти в тебі́, о́тче, несказа́нноє смотре́ніє Своє́ о святі́й горі́ Поча́євстій, дарова́ша ті си́лу і прему́дрость благопоспі́шно подвиза́тися проти́ву злі́йшаго врага́ оби́телі твоєя́, злове́рнаго боля́рина Андре́я; єго́же ти судо́м пра́вим іму́щество монасти́рськоє, велі́нієм єго́ погра́бленноє, возврати́ти пону́дил єси́, і сего́ в примире́ніє с собо́ю і со і́ноками свої́ми приве́л єси́, поя́ Бо́гу суда́ і пра́вди: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє тобо́ю показа́ Госпо́дь оби́телі Поча́євстій неізслі́димоє промишле́ніє Своє́, єгда́ жела́нію твоєму́ послі́дуя, імени́тий боля́рин Фео́дор і Є́ва, благоро́дная жена́ єго́, іждиве́нієм свої́м сооруди́ша верху́ гори́ Поча́євськия це́рков вели́кую і пресла́вную, я́ко вмісти́тися в ней цільбоно́сній стопі́ Бо́жия Ма́тере; іді́же і іко́ну Єя́ чудотво́рную поста́вил єси́, сли́шащи от всіх:","Ра́дуйся, Тро́йці Живонача́льния, во Єя́же і́м'я но́вий храм сам освяти́л єси́, ізбра́нний побо́рниче;","Ра́дуйся, Пречи́стия Богоро́диці, ра́ди стопи́ Єя́ і іко́ни Поча́євськия, преізя́щний покло́нниче.","Ра́дуйся, я́ко ревну́я о благоустроє́нії оби́телі твоєя́, свої́ми рука́ми сади́ на горі́ Поча́євстій насажда́л єси́;","Ра́дуйся, я́ко снабже́нія ра́ди оби́телі і всея́ ві́си Поча́євськия водо́ю самоли́чні пруди́ у подно́жія гори́ Поча́євськия іскопа́л єси́.","Ра́дуйся, все монасти́рськоє іму́щество во бді́ніїх свої́х, найпа́че же но́щію, многокра́тні от тате́й храни́вий, і сих тобо́ю уловля́ємих на путь і́стинний наставля́яй;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 8","ps":["Стра́нно і чу́дно житіє́ твоє́, си́це і успе́ніє твоє́, преподо́бне о́тче, хотя́щу бо ті преста́витися от привре́менния жи́зні сея́, толи́кия прозорли́вости сподо́бился єси́ от Го́спода, я́ко день і час отше́ствія твоєго́ пре́жде седьми́ці проре́кл єси́. Во урече́нний же день і час, по Боже́ственній литургі́ї, тобо́ю же сами́м соверше́нней, а́біє кромі́ вся́кия болі́зні ми́рно отше́л єси́ ко Го́споду, не престая́ пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі в стра́хі наро́д Поча́євський і про́чії окре́стнії лю́діє, ви́дяще сві́тлость, от гро́ба твоєго́ ісходя́щую чрез седьм літ по успе́нії твоє́м, уго́дниче Бо́жий; недоуміва́ху бо, отку́ду і ко́єя ра́ди вини́ сія́ луча́ ісхожда́ше. Тогда́ сам яви́лся єси́ в со́нном виді́нії митрополи́ту Ки́євському Діони́сію, ізвіству́я, я́ко хо́щеть Бог чрез него́ откри́ти святи́я мо́щі твоя́; є́же сли́шав, архієре́й правосла́вний возглаша́ше о тебі́:","Ра́дуйся, ді́лателю до́брий, от у́тра до ве́чера столе́тнія жи́зні твоєя́ де́лавий благоче́стно во вертогра́ді духо́внім;","Ра́дуйся, тяготу́ і вар многотру́днаго житія́ твоєго́ ра́ди Го́спода охо́тно поне́сший.","Ра́дуйся, я́ко сего́ ра́ди душа́ твоя́ не оста́вися во а́ді, ніже́ плоть твоя́ ви́ді істлі́нія;","Ра́дуйся, благи́й ра́бе і ві́рний, за безме́рниє по́двиги твої́ вше́дий в ра́дость Го́спода своєго́.","Ра́дуйся, світи́льниче, о не́мже не восхоті́ Бог, да под спу́дом пребива́єть, но да на сві́щниці всенаро́днаго зрі́нія і поклоне́нія поста́виться;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ земно́є превосходя́щия глаго́ли твоя́ сли́шав Діони́сій, а́ще і слага́ше ти́я в се́рдці своє́м, оба́че, я́ко му́дрий і іску́сний богосло́в, уме́дли от ді́ла того́, до́ндеже трети́цею яви́лся єси́ єму́, отмще́нієм претя́, а́ще би повелі́ннаго не іспо́лнил вско́рі; уразумі́в же от проізволе́нія Бо́жия би́ти ді́ло сіє́, прите́к а́біє со всім кли́ром на го́ру Поча́євськую і іспита́вши ізві́стно о богоуго́дном житії́ твоє́м, повелі́ откри́ти гроб, в не́мже обрі́те честни́я мо́щі твоя́ кромі́ вся́каго тлі́нія, благоуха́нія несказа́ннаго іспо́лненни; і та́ко внесе́ ти́я в це́рков Живонача́льния Тро́йці, ублажа́юще тя і пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство вся́коє не мо́жеть ізрещи́ вели́чества пресла́вних зна́меній і чуде́с твої́х, я́же нача́л єси́ явля́ти по откри́тії моще́й твої́х, всеблаже́нне о́тче: мно́зі бо от наро́да, разли́чними неду́ги одержи́мії, прите́кши к многоціле́бній ра́ці твоє́й, ісціле́ніє прия́ша. Я́коже бо в животі́ твоє́м вся́кия доброді́телі і благости́ні іспо́лнен бил єси́, си́це і по сме́рті добро́ твори́ти не престає́ши всім, с ві́рою призива́ющим тя і вопію́щим о Бо́зі сицева́я:","Ра́дуйся, зерно́ пшени́чноє, по апо́стольському глаго́лу із земна́го тлі́нія проізра́стшеє, да мног плод духо́вний тре́бующим принесе́ши;","Ра́дуйся, дре́во, насажде́нноє при істо́чниці цільбоно́сния води́ от стопи́ Бо́жия Ма́тере, да всі жа́ждущії от тебе́ питіє́ жи́зні почерпа́ють.","Ра́дуйся, пра́ведниче, по сло́ву псало́мському, я́ко фі́нікс процвіти́й от гори́ Поча́євськия, да а́лчущих пра́вди і вся́кия благости́ні і́стинно і благонра́вієм напита́єши;","Ра́дуйся, у́зи разруше́нія пе́рстнаго в нетлі́нії своє́м благода́тію Бо́жиєю расто́ргнувий, да от вся́ких губи́тельних неду́гов стра́ждущим врачевство́ і ісціле́ніє подає́ши.","Ра́дуйся, в ми́рі Желі́зом рече́нний, несокруши́мую крі́пость і си́лу немощни́м душе́ю і ті́лом сви́ше принося́й;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ученика́ твоєго́ Досифе́я от обдержа́щаго єго́ смертоно́снаго неду́га, о́тче преподо́бне, а́нгели во твоє́ обще́ніє призва́л єси́, с ни́миже і ви́дін бил єси́ во сві́тлості необи́чней, предстоя́ Бо́жієй Ма́тері, но́щію в це́ркві Пресвяти́я Тро́йці, плать, ми́ром ціле́бним чуде́сно напоє́нний, боля́щему посила́я, да отре́ть їм ті́ло своє́, і а́біє гряде́ть в це́рков на всено́щноє бді́ніє прилучи́вшагося ра́ди вели́каго пра́здника всеми́рнаго Воздви́женія Креста́ Госпо́дня, поя́ Бо́гу, си́лою кре́стною укріпля́ющему святи́х Свої́х на по́мощ ві́рним: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і огражде́ніє от враго́во ви́димих і неви́димих достоя́нію твоєму́, в не́мже, о́тче, жи́тельствовал єси́ і ни́ні пребива́єши в нетлі́ннім тілесі́ твоє́м. Сего́ ра́ди єгда́ нечести́вії ісма́їлити обидо́ша го́ру Поча́євськую во вре́м'я бра́ні Зба́ражськой, а́біє яви́лся єси́ верху́ єя́ на о́блаціх небе́сних, в сві́тлости необи́чней предста́тельствующи пред Свято́ю Ді́вою Богоро́дицею, да не преда́сть в нево́лю супоста́том оби́телі, іді́же бил єси́ ігу́меном; є́же ви́дівше і́ноці і лю́діє, во оби́телі обложе́ннії, припа́дающе к ра́ці честни́х моще́й твої́х, вопія́ху тебі́:","Ра́дуйся, со а́нгельськими си́лами предстоя́й Цари́це Небе́сній проти́ву полко́м неві́рних ага́рян;","Ра́дуйся, ї́хже стріла́ми, на глави́ їх возвраща́ющимися, я́ко мо́лнією їх порази́вий.","Ра́дуйся, я́ко сего́ ра́ди вразі́ Креста́ Христо́ва спі́шні отбіго́ша от оби́телі Поча́євския, друг дру́га во у́жасі поража́юще;","Ра́дуйся, я́ко мно́зі от них стра́хом Бо́жиїм наставля́ємі, христия́нськую ві́ру приє́мше, на послуша́нії монасти́рстем в Поча́єві да́же до кончи́ни своєя́ преби́ша.","Ра́дуйся, я́ко предста́тельством твої́м к Богоро́диці вся блага́я ві́рним во ізбавле́нії їх прийдо́ша;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє не довлі́єть к прославле́нію пренебе́снаго вели́чества твоєго́ і вла́сті, я́же от Го́спода, всеблаже́нне о́тче; я́ко не то́чію правосла́вним, но і латиноуни́том, єгда́ попуще́нієм Бо́жиїм во вла́сті їх бя́ше гора́ Поча́євськая, неісче́тния да́ри і благодія́нія ниспосила́л єси́, о́вих у́бо от духо́в нечи́стих, о́вих от болі́зней і смертоно́сних ран ісціля́ющи, о́вих же поуча́ющи судо́м тя́жким і виді́ніями многообра́зними, да чтуть тя, я́ко і́стиннаго слугу́ Бо́жия; є́же сі́ї і нача́ша твори́ти, доне́ліже честни́я мо́щі твоя́, ку́пно со оби́телію Поча́євською, не бя́ху па́ки возвраще́ни в одержа́ніє правосла́вним, с пі́снію о тебі́ Бо́гу благода́рственною: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко светоприї́мная свіща́, єле́єм благода́ті возже́нная, я́ко све́точ многосві́тлий, на висоті́ стоя́й, светопода́тельне сія́єши всім конце́м землі́, о́тче наш І́ове; сего́ ра́ди і восто́к тя ублажа́єть, і сі́вер велича́єть, і юг восхваля́єть, і за́пад по премно́гу прославля́єть. Ми же во сві́ті лиця́ твоєго́ теку́ще к сві́ту невече́рнему і к ра́зуму боже́ственному наставля́ємі, вопіє́м ті от полноти́ серде́чния:","Ра́дуйся, преві́чнаго Архієре́я Христа́ ві́рний служи́телю, за благоче́стіє своє́ архієре́йськима рука́ма із спу́да земна́го із'я́тий і откри́тий для всенаро́днаго почита́нія;","Ра́дуйся, Царя́ Небе́снаго і Влади́ки непобіди́мий ратобо́рче, благочести́вих же Царе́й на́ших спобо́рниче і утвержде́ніє.","Ра́дуйся, моли́твенниче і сопредстоя́телю Пресвяти́я Богоро́диці непреста́нний, ку́пно с іко́ною Єя́ честно́ю і стопо́ю цільбоно́сною от всіх, на го́ру Поча́євськую притека́ющих, почита́ємий;","Ра́дуйся, а́нгелов Бо́жиїх і святи́х на небесі́ купножи́телю преізря́дний, во хра́мі, честно́му і́мені твоєму́ посвяще́нном на землі́, от приходя́щих к тебі́ ублажа́ємий.","Ра́дуйся, сто́лпе ві́ри, про́мислом Бо́жиїм на кра́йнем за́паді Украї́нськия землі́ водруже́нний, да всім от ві́ри і праоте́чеськаго благоче́стія заблу́ждшим синово́м за́пада інозе́мнаго путь до́брий к і́стинному правові́рію, є́же в Це́ркві на́шей Правосла́вній, показу́єши;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 12","ps":["Благода́тію, да́нною ті сви́ше, чудоді́йствуя на горі́ Поча́євстій, преподо́бне, не оставля́єши ни і во вре́м'я сіє́; но я́коже дре́вле, си́це і до дне́шняго дне, не то́чію притека́ющії к ра́ці многоціле́бних моще́й твої́х, но і всі отдале́че тебі́ призива́ющії і на тя упова́ющії сліпі́ї презира́ють, хромі́ї хо́дять, разсла́бленнії возстаю́ть, бісну́ющіїся ісціля́ються, стра́ждущії утіша́ються, угрожа́ємії злим пове́трієм от смертоно́сния я́зви ізбавля́ються, землі́ плодоно́сіє подає́ться, гра́ди і до́ми от тру́са, пото́па і огня́ спаса́ються, во є́же всім от тебе́ вспомоществу́ємим, і та́ко тобо́ю хва́лящимся, пі́ти Бо́гу в ра́дованії се́рдця своєго́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресла́вноє о тебі́ смотре́ніє Бо́жиє і чудеса́ твоя́, преподо́бне о́тче, мо́лим тя всеусе́рдно, раби́ твої́, не забу́ди нас і во вся дні живота́ на́шего, но всегда́ пребива́й с на́ми, да твої́м заступле́нієм і по́мощію огражда́єми, спаса́ємі і ізбавля́ємі от всіх зол ви́димих і неви́димих, вопіє́м ті:","Ра́дуйся, ми́лости превели́кия сокро́вище;","Ра́дуйся, Боже́ственнаго проявле́нія о лю́діх прия́телище.","Ра́дуйся, ненаде́жних наді́яніє;","Ра́дуйся, са́мих отча́янних спасе́ніє.","Ра́дуйся, єго́же благопоспе́шними моли́твами от ві́чния сме́рти свобожда́ємся і безконе́чния жи́зні сподобля́ємся;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 13","ps":["О,прехва́льний і пречу́дний о́тче І́ове! Прийми́ ни́ні сіє́ ма́лоє моле́ніє на́ше, тебі́ от любве́ серде́чния приноси́моє, і твої́м богоприя́тним хода́тайством іспо́лни во благи́х вся проше́нія на́ша, к тебі́ бо в ну́ждах прибіга́єм і на тебі́ по Бо́зі і Богоро́дице все упова́ніє на́ше возлага́єм, прославля́ющи тя, і тобо́ю прославля́ємому Пода́телю всіх благ, Влади́ці жи́зні і сме́рті, поя́ усе́рдно: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела земна́го нра́вом і челові́ка небе́снаго житіє́м соді́ла тя Влади́ка а́нгелов і всея́ ви́димия і неви́димия тва́рі; ті́мже просла́вив тя, я́ко сообра́зна я́вльшася предуві́дінію Єго́, благоволи́л єсть і нам яви́ти сла́вноє житіє́ і пренебе́сноє прославле́ніє твоє́, да воспіва́єм ті си́це:","Ра́дуйся, от утро́би ма́тернія ізбра́нний на по́двиг служе́нія Царю́ Небе́сному;","Ра́дуйся, і́менем Іоа́нна, благода́ті тезоімени́таго, і́мже по рожде́нії нарече́н бил єси́, я́ко печа́тію благода́ті запечатле́нний.","Ра́дуйся, я́ко прия́л єси́ і́м'я Крести́теля Госпо́дня, єму́же пустиннолю́бним житіє́м до́брі поревнова́л єси́;","Ра́дуйся, я́ко ізмла́да усли́шал єси́ вну́тренній глас призва́вшаго тя Го́спода.","Ра́дуйся, я́ко десятоле́тен сий, сему́ гла́су охо́тно послі́дуя, уклони́лся єси́ от о́чію люби́мих ті роди́телей і во оби́телі Уго́рницькой всели́лся єси́;","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нний от Го́спода, благи́й ра́бе і ві́рний, уго́дниче Христо́в, преподо́бне о́тче наш І́ове, твої́м заступле́нієм і предста́тельством огражда́єми, похва́льная воспису́єм ті, пові́дающе благи́я по́двиги і чудеса́ твоя́, і благода́рственная возсила́єм моле́нія просла́вльшему тя Го́споду і Царю́ сла́ви. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду і Пречи́стій Єго́ Ма́тері, Присноді́ві Богоро́дице, от вся́ких нас бід свободи́, зову́щих ті:","Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий, і оби́телі Поча́євския украше́ніє."]},{"h":"Молитва","ps":["О, всесвяти́й і пресла́вний уго́дниче Бо́жий, преподо́бне о́тче наш І́ове, при́сний о нас ко Го́споду моли́твенниче і те́плий предста́телю о душа́х на́ших! К тебі́ всеумиле́нно ни́ні притека́єм, і, помина́юще по́двиги і чудеса́ твоя́, я́же сотвори́л єси́ і твори́ши на землі́, про́сим і мо́лим твою́ благости́ню: я́коже тве́рдо і неізмі́нно потруди́лся єси́ во ві́рі Христа́ Бо́га на́шего, і сію́ до конця́ в себі́ і во всіх при́сних твої́х ці́лу і невреди́му сохрани́вий от вся́ких прираже́ній вра́жиїх і єресе́й тлітво́рних, си́це і нас в Правосла́вії і єдиноми́слії укріпи́, отгоня́ющи моли́твами твої́ми вся́кую тьму неві́рія і неправоми́слія от серде́ць і помишле́ній на́ших; послужи́вий Го́споду і Бо́гу твоєму́ ді́ли благи́ми і неізрече́нним самоотверже́нієм в труді́х, бді́ніїх і поще́ніїх, наста́ви нас на путь вся́кия доброді́телі і благости́ні, ізбавля́ющи от іскуше́ній і гріхо́в, удаля́ющих нас от Бо́га і поверга́ющих в бе́здну зла все житіє́ на́ше; яви́вийся іногда́ с Пречи́стою Ді́вою Богоро́дицею верху́ гори́ Поча́євськия во спасе́ніє оби́телі твоєя́ от наше́ствія і обложе́нія ага́рянскаго, і ни́ні ускори́ на по́мощ Благочести́війшему Госуда́рю на́шему Імпера́тору [і́м'ярік] і всему́ правосла́вному і боголюби́вому Ца́рству на́шему проти́ву всіх враго́в на́ших вні́шніх і вну́тренних, утвержда́я мир і тишину́ в землі́ на́шей, да твої́ми моли́твами і предста́тельством, ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́; і всім, к тебі́ притека́ющим і припа́дающим к ра́ці честни́х і многоціле́бних моще́й твої́х і твоєя́ по́мощі і заступле́нія тре́бующим, неоску́дния ми́лості незави́стно подава́яй, не оста́ви і нас си́рих і безпо́мощних, тебі́ моля́щихся, ізбавля́ющи от вся́кия ско́рби, гні́ва і ну́жди, от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нник і междоусо́бния бра́ні. Єй, уго́дниче Бо́жий, при́зри ми́лостивно от престо́ла Царя́ сла́ви, Єму́же ти ни́ні предстої́ши со арха́нгели і а́нгели і со всі́ми святи́ми, на оби́тель твою́ (сію́) Поча́євськую, є́юже ти дре́вле му́дро пра́вил єси́, назда́в ю всехва́льним і ди́вним житіє́м твої́м, і сохрани́ ю моли́твами твої́ми, і вся́кий град і страну́, і всіх отовсю́ду, на мо́рі і на су́ші, в пусти́нях і в злоключе́ніїх многоразли́чних тебе́ призива́ющих, от всіх зол ви́димих і неви́димих; да та́ко твоє́ю по́мощію і хода́тайством спаса́ємі, во ві́ці сем і по сконча́нії живота́ на́шего сподо́бимся ку́пно с тобо́ю сла́вити і воспіва́ти всечестно́є і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва, що читається перед мощами","ps":["О, всеблаже́нне і богоно́сне о́тче наш І́ове! І́ночеськаго ангелоподо́бнаго житія́ богому́дрий наста́вниче, ві́ри Правосла́вния Восто́чно-Кафоли́чеськия проти́в лжемудрова́ній За́пада непреобори́мий защи́тниче і побо́рниче, богопре́данних уста́вов Це́ркве і преда́ній оте́чеських ві́рний блюсти́телю і стро́гий взиска́телю, свя́тости і чистоти́, цілому́дрія і нестяжа́нія, трудолю́бія і богоми́слія, поста́ і бді́нія вели́кий ревни́телю, долготерпі́нія і злострада́нія неутоми́мий і непобіди́мий ратобо́рче, о́браз кро́тости, зерца́ло смире́нія, примі́р незло́бія, по́стников удобре́ніє, ді́вственников похвало́, мона́хов і схимона́хов ра́досте. По і́мені твоєму́, преподо́бне о́тче, я́коже і дре́вняго о́наго І́ова, многострада́льна і пра́ведна, і житіє́ твоє́ бисть пра́ведно і непоро́чно от младе́нчеських пеле́н, всі́ми ді́ли благи́ми, я́ко многоці́нним би́сером, благоукраше́нно і благоду́шним терпі́нієм чрез мно́га лі́та скорбе́й і болі́зней, па́че зла́та і сребра́, в горни́лі іскуше́нних, просія́вши. Єще́ бо су́щи двана́десяти то́чію літ, восприя́л єси́ на ся і́го Христо́во с вели́ким о́бразом мона́шеським і да́же до ста́рости і престарі́нія вя́щше дев'яти́десяти літ, благоду́шно і неосла́бно, непоползнове́нно і небла́зненно поне́сл єси́, проше́д всяк путь пра́вди і святи́ні в пості́ і моли́тві, в колінопреклоне́ніїх і бді́ніїх і та́ко на висоту́ доброді́телей ізря́дну, вспомоществу́єм благода́тію Бо́жиєю, по степе́нем возше́л єси́, я́ко всім диви́тися і ублажа́ти тя за премно́гую доброді́тель і любому́дріє твоє́, не то́чію в преді́ліх оте́чествія твоєго́, но і в страна́х о́крест су́щих, о чесо́м сли́шав боголюби́вий князь Остро́жський і вельми́ возжела́в імі́ти тя руководи́теля себе́ на путі́ спасе́нія і Крестовоздви́женськой оби́телі своє́й, я́же на о́строві Ду́бенстем, предстоя́теля і наста́вника моле́нієм любве́ своєя́ привлече́ тя, отону́дуже і святі́й оби́телі Поча́євськой, я́ко сокро́вище ве́ліє і неоціне́нноє, дарова́лся єси́. Ті́мже і пра́ведний Судія́ і мздовозда́тель Бог, І́же вість су́щия Своя́, пре́жде да́же не би́ти їм, обіща́вий ві́рним рабо́м Свої́м за труди́ і по́двиги їх во сла́ву Єго́ і́мені возда́ти стори́цею, сви́ше призрі́ на смире́ніє твоє́ і вознесе́ тя, і просла́ви тя на землі́ живи́х, дарова́в духоно́сному тілесі́ твоєму́ дар нетлі́нія і благода́ть врачева́нія неду́гов душе́вних і тіле́сних, для всіх, с ві́рою і любо́вію ко всечестні́й ра́ці твоє́й притека́ющих, а моли́тві твоє́й си́лу і крі́пость непобіди́мую, враго́во ви́димих і неви́димих устраша́ющую і поража́ющую. Єгда́ бо іноплеме́нници о́ни ісмаєли́тстії, ї́хже Госпо́дь Бог єще́ в пра́отці їх от ро́да і до́му Авраа́мля отри́ну, вразі́ Креста́ Христо́ва, облего́ша го́ру і оби́тель Поча́євськую, хотя́ще ю до конця́ разори́ти, тогда́ ти, о́тче прехва́льне, бил єси́ хода́тай святи́ми твої́ми моли́твами ко всемогу́щему і всеблаго́му Бо́гу і к Преблагослове́нній Ді́ві Марі́ї Богоро́дице, і бла́гостію, тебі́ от Бо́га да́нною, і предста́тельством Пресвяти́я Богоро́диці отгна́л єси́ все безу́міє супоста́тов тіх і, всю я́рость їх разруши́в і крі́пость побіди́в, сотвори́л єси́ їх біжа́ти со стра́хом і тре́петом. При́зри у́бо і ни́ні о́ком благоутро́бія твоєго́, прилі́жно мо́лим тя, обстоя́ще святи́я і многоціле́бния мо́щі твоя́ і усе́рдно лобиза́юще я, при́зри на нас, недосто́йних чад і рабо́в твої́х, вступи́вших в стезі́ твої́, но немогу́щих пра́во по ним ше́ствовати, і на мі́сто сіє́, от літ дре́вніх богоізбра́нноє і чудеси́ просла́вленноє, в не́мже і́м'я твоє́ призива́ється і єго́же ти по́ти трудо́в твої́х богоуго́дних ороси́л і возді́лал єси́, і огради́ єго́ і нас моли́твами твої́ми от вся́каго наві́та вра́жия і зла́го обстоя́нія, сохраня́я і соблюда́я всіх і ка́ждаго в ми́рі і тишині́, во ві́рі нелицемі́рній і богоуго́дном жи́тельстві. Пода́ждь же, уго́дниче Бо́жий, і всім, приходя́щим сі́мо і твоєя́ по́мощі і заступле́нія і́щущим, бла́гость і ми́лость от Христа́ Бо́га на́шего і Пречи́стия Єго́ Ма́тере, да нікто́же ізи́деть отсю́ду в тугеі і ско́рби, в печа́лі і сі́тованії, постижде́н і посра́млен в наді́янії своє́м, но ки́йждо, по мі́рі ві́ри і любве́ своєя́, да восприї́меть себі́ поне́ ні́кую отра́ду і утіше́ніє, облегче́ніє і подкріпле́ніє, защи́ту і по́мощ, во сла́ву Бо́га Трисвята́го, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Многострада́льнаго пра́отця долготерпі́ніє стяжа́в, / Крести́телеву воздержа́нію уподобля́яся, / Боже́ственния же ре́вности обою́ приобща́яся, / тіх імена́ досто́йно прия́ти сподо́бился єси́ / і і́стинния ві́ри бил єси́ пропові́дник безбоя́знен: / ті́мже мона́хов мно́жества ко Христу́ приве́л єси́ / і вся лю́ди в Правосла́вії утверди́л єси́, / І́ове преподо́бне о́тче наш, // моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар на знайдення мощей, глас 4","ps":["Возло́ж на ся і́го Христо́во от ю́ности, / преподо́бне о́тче І́ове, / многолі́тні свя́то подвиза́лся єси́ / на по́прищі благоче́стія во оби́телі Уго́рницстей і на о́строві Ду́бенстем, / і, прише́д ко горі́ Поча́євстій, / зна́менанней цільбоно́сною стопо́ю Пресвяти́я Богоро́диці, / в ті́сній пеще́рі ка́менній / богоми́слія ра́ди і моли́тви многокра́тно заключа́лся єси́, / і, благода́тію Бо́жиєю укріпля́яся, / му́жественно потруди́лся єси́ / на по́льзу Це́ркве Христо́ви і оби́телі твоєя́, / ку́пно же і проти́ву враго́в Правосла́вія і благоче́стія христия́нськаго, / і, наста́вив сицево́му ополче́нію і́ночествующих, / побіди́телі тіх предста́вил єси́ Влади́ці і Бо́гу. // Того́ моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ і́стинния ві́ри столп, / єва́нгельських же за́повідей ревни́тель, / горди́ні обличе́ніє, / смире́нним же предста́тель і науче́ніє: / ті́мже і ублажа́ющим тя гріхо́в отпуще́ніє іспроси́, / і оби́тель твою́ невріди́му сохрани́, // І́ове о́тче наш, многострада́льному подо́бний."]},{"h":"Інший кондак на знайдення мощей, глас 8","ps":["Возсія́ от спу́да земна́го сокро́вище нетлі́нноє моще́й твої́х, / уго́дниче Бо́жий, / я́ко, благоче́стно пожи́во во ві́рі Христа́ Бо́га на́шего, / дости́гл єси́ доброді́телей соверше́нства, / і, оста́вль сла́дость житія́ преходя́щаго, / в пеще́рі гори́ Поча́євськия в поще́ніїх, моли́твах і труді́х свя́то подвиза́лся єси́, / і ті́ми ті́ло твоє́ ув'яди́л єси́. / Ни́ні же, преше́д к Бо́гу в безм'яте́жний і ві́чний поко́й, / мо́лишися о всіх с ві́рою к тебі́ прибіга́ющих. / Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий // і оби́телі Поча́євския украше́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче наш І́ове, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святим цілителям, безсрібникам і чудотворцям","e":"Akathist to the Holy Healers, Unmercenaries and Wonderworkers","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії помо́щници стра́ждущих, вра́чеве неду́гующих і чудотво́рці преди́внії, святі́ї безме́зднії ціли́телі ми́лостивії, похва́льная воспису́єм вам, засту́пником на́шим і в ско́рбіх уті́шителем. Ви же, я́ко іму́щії дерзнове́ніє ко Всемилостивому́ Спа́су на́шему, ізба́віте от страсте́й і болі́зней всіх ві́рою і любо́вію воспіва́ющих вам:","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Ікос 1","ps":["А́нгелов і челові́ков Творе́ць ізбра́ вас, враче́й, ціли́телей і чудотво́рцев свято́є сосло́віє, я́ко любо́вію і сострада́нієм ко всім лю́дем горя́щих, і дарова́ вам сугу́бую благода́ть, да бу́дете ізбавля́ти от бід, скорбе́й, болі́зней і вся́ких лю́тих іскуше́ній всіх чту́щих святу́ю па́м'ять ва́шу і с любо́вію восхваля́ющих вас та́ко:","Ра́дуйся, святи́й Проро́че, Предте́че і Крести́телю Госпо́день Іоа́нне, душі́ на́ша покая́нієм обновля́яй.","Ра́дуйся, святи́й пра́ведний Симео́не, Богомладе́нця Христа́ на ру́ці свої́ приє́мий і ни́ні всіх младе́нцев Богодарова́нний храни́телю.","Ра́дуйся, святи́й Апо́столе і Євангели́сте Іоа́нне Богосло́ве, возлю́бленний Христо́в учениче́, лю́б'ящим і чту́щим тя любо́вію воздава́яй.","Ра́дуйся, му́чениче Лонгине, от ка́плі Кро́ве Го́спода о́чі свої́ ісціли́вий і благода́ть обріти́й духо́вноє прозрі́ніє лю́дем дарова́ти.","Ра́дуйтеся, святі́ї му́ченици Зинаїдо і Филонилло, сро́дниці Апо́стола Па́вла, сугу́бо боля́щим послужившия.","Ра́дуйтеся, священному́чениче Киприя́не і му́ченице Іусти́но, от бісо́в і злих челові́к волхвова́нія крі́пції засту́пниці.","Ра́дуйся, великому́чениче Дими́тріє Солунський, ми́ро благово́нноє всім боля́щим на ісціле́ніє істоча́яй.","Ра́дуйся, Кесаріє Назіянзине, царе́й благочести́вих врачу́, от мно́гих тя́жких неду́гов богому́дрий ціли́телю.","Ра́дуйся, великому́ченице Варва́ро, а́гнице всеблаже́нная, от внеза́пния сме́рті ві́рних ізбавля́ющая.","Ра́дуйся, великому́ченице Єкатери́но, ді́во прему́драя, ізбра́нний сосу́де чистоти́, омраче́ніє ума́ на́шего просвіща́ющая.","Ра́дуйся, великому́ченице Анастасі́є, неду́ги заключе́нних в темниціх врачевавшая і от мно́гих скорбе́й нас ізбавля́ющая.","Ра́дуйся, му́ченице Фомаї́до, цілому́дрія ра́ди ду́шу свою́ положившая і плотські́я стра́сті побіжда́ти лю́дем помога́ющая.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 2","ps":["Ви́дів Тя, Ма́ти Всепречи́стая, на Кресті́ пригвожде́нний Син Твой і Бог у Креста́ предстоя́щу і болі́зненно Єму́ состраждущую, возлю́бленному ученику́ Своєму́ Апо́столу Іоа́нну Тя в Ма́тер нарече́ і сим весь род челові́чеський Тебі́ усинові, да бу́деши воі́стину Ма́тер всім скорб'я́щим, стра́ждущим, недугующим, в біда́х і тя́жких обстоя́ніїх су́щим, Си́на Твоєго́ Христа́ Бо́га призива́ющим і пою́щим Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський не мо́жеть пости́гнути вели́каго Твоєго́ милосе́рдія, Пресвята́я Влади́чице Богоро́дице, Ти бо єси́ необори́мая огра́да, охраня́ющая ни от вся́ких болі́зней душе́вних і тіле́сних і заступа́ющая всіх прибіга́ющих к Тебі́ с моли́твою, печа́льним утіше́ніє, скорб'я́щим ра́дованіє, оби́димим Засту́пнице, бедствующим по́моще, больни́х Ціли́тельнице, грі́шних Спору́чнице. Ті́мже іму́щи ма́тернєє о всіх попече́ніє, благоізво́лила єси́ ускори́ти на по́мощ ізбра́нником Бо́жиїм, враче́м і целителем, ї́хже па́м'ять пра́зднующе, воспіва́єм си́це:","Ра́дуйтеся, Пресвяти́я Влади́чиці Богоро́диці ізбра́ннії служи́телі.","Ра́дуйтеся, ча́да Єя́ ві́рнії і возлю́бленнії.","Ра́дуйтеся, Засту́пниці Усе́рдния ро́да христия́нськаго благогові́йнії почитателі.","Ра́дуйтеся, во́лі Тоя́ святи́я ісполни́тели.","Ра́дуйтеся, все упова́ніє на Ма́тер Бо́жию возложи́вшії.","Ра́дуйтеся, небе́сную по́мощ от Нея́ восприї́мшії.","Ра́дуйтеся, ми́лостивоє заступле́ніє Бо́жия Ма́тере ко всім боля́щим і стра́ждущим лю́дем приклоняющії.","Ра́дуйтеся, ве́ліє дерзнове́ніє к Ней стяжа́вшії.","Ра́дуйтеся, я́ко Преблагослове́нную Ма́тер Го́спода ходатайстовати о нас умоляєте.","Ра́дуйтеся, я́ко благослове́нієм Єя́ здра́віє і крі́пость неісці́льно боля́щим дони́ні возвраща́єте.","Ра́дуйтеся, во дні і нощі́ моли́тви к Цари́це Небесе́ і землі́ со слеза́ми возносившії.","Ра́дуйтеся, я́ко с Не́ю о спасе́нії всіх люде́й правосла́вних ко Христу́ ру́ці воздеваєте.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго укріпля́єм, святи́й проро́че Бо́жий Іліє́, по́слан бив от Го́спода в Саре́пту Сидо́нськую к жені́ вдови́ці препитатися во гла́ді, оба́че імі́я чудотворе́нія благода́ть, умно́жил єси́ му́ку і єле́й в до́му єя́ до сконча́нія гладнаго вре́мене і моли́твою твоє́ю воскреси́л єси́ уме́ршаго єя́ си́на, поя́ Бо́гу благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще єди́но попече́ніє, є́же Отцю́ Небе́сному благоугожда́ти і ві́рно Єму́ служи́ти і вели́кия ре́вности по Бо́зі іспо́лненнії святі́ї проро́ци Бо́жії, по сло́ву Апо́стола, «ві́рою побіди́ша ца́рствія, соді́яша пра́вду, получи́ша обітова́нія, загради́ша уста́ львов, угаси́ша си́лу о́гненную, ізбіго́ша о́стрея меча́, возмого́ша от не́мощі, обрати́ша в бі́гство полки́ чужди́х», ни́ні же, во Ца́рствії Небе́снім пребива́юще, врачу́ють я́зви неісці́льния і вся́кий же неду́г всім нам, скорбми́ і болі́зньми отягченним, с ві́рою і наде́ждою вопію́щим си́це:","Ра́дуйтеся, ра́зум свой во́лі Бо́жієй покори́вшії.","Ра́дуйтеся, сві́том прему́дрости от Бо́га озареннії.","Ра́дуйтеся, посланці Отця́ Небе́снаго і провозві́стници святи́х Єго́ велі́ній.","Ра́дуйтеся, зна́менії і чудеси́ Боже́ственную і́стину утвержда́вшії.","Ра́дуйтеся, бу́дущая, я́ко настоя́щая провидевшії.","Ра́дуйтеся, я́ко врачи́ благоїскуснії, лю́ди от вся́кия болі́зні ісціля́ющії.","Ра́дуйтеся, во вре́м'я гла́да ві́рних пита́телі.","Ра́дуйтеся, недугующим і разсла́бленним ско́рії помо́щници.","Ра́дуйтеся, отча́янним наде́жду на спасе́ніє подаю́щії.","Ра́дуйтеся, ми́ро целебноє благода́ті нам істоча́ющії.","Ра́дуйтеся, благода́тію Бо́жиєю ме́ртвих воскрешавшії.","Ра́дуйтеся, Судію́ Пра́веднаго за грі́шния лю́ди умоляющії.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 4","ps":["Бу́ря скорбе́й і напа́стей, воздвиза́ємая зло́бою ми́ра сего́, не осла́би ві́ри і любве́ твоєя́ ко Го́споду, Апо́столе святи́й Іа́кове, пе́рвий Ієрусали́мський архієре́ю і учи́телю: ти бо Боже́ственним Ду́хом просвіти́вся, Бо́га Сло́ва пропові́дал єси́ і восприя́л єси́ благода́ть єле́єм святи́м ціли́ти всіх я́зви же і неду́ги, глаго́ля в посла́нії своє́м, я́ко моли́тва ві́ри спасе́ть боля́щаго, і воздви́гнеть єго́ Госпо́дь: мно́го бо мо́жеть моли́тва пра́веднаго поспішеству́єма. Ті́мже і ни́ні ісціле́нія істоча́єши всім к твоєму́ заступле́нію притекающим і о тебі́ Бо́гу вопію́щим: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше ві́рнії ве́лію ва́шу к стра́ждущим любо́в і чуде́сноє врачева́ніє ва́ше, Апо́столи святі́ї, от всіх конце́в землі́ устремля́хуся к вам с ві́рою в ціле́бную благода́ть Бо́жию, во вас ді́йствующую, і́бо Сам Госпо́дь, по сло́ву Апо́стола, даде́ вам власть на ду́хи нечи́стия, я́ко да ізгоні́те їх, і запові́да ціли́ти всяк неду́г і вся́ку болі́знь, глаго́ля: «Боля́щия ісціля́йте, прокаже́нния очища́йте, ме́ртвия воскреша́йте, бі́си ізгоня́йте; ту́не прия́сте, ту́не даді́те». Сего́ ра́ди от любве́ серде́чния прино́сим вам со смире́нієм і ві́рою похвали́ сія́:","Ра́дуйтеся, благові́стія Єва́нгельськаго труби́.","Ра́дуйтеся, вся конці́ вселе́нния просвіти́вшії.","Ра́дуйтеся, серафи́мською пла́менною любо́вію ко Го́споду горевшії.","Ра́дуйтеся, Це́ркви Христо́ви сла́во і утвержде́ніє.","Ра́дуйтеся, Пресвяті́й Влади́чице Богоро́дице ві́рно послужи́вшії.","Ра́дуйтеся, покро́вом Єя́ осененнії.","Ра́дуйтеся, от Самаго́ Го́спода Ісу́са Христа́ благода́ть і си́лу ціли́ти неду́жних приявшії.","Ра́дуйтеся, на стезю́ покая́нія нас наставля́ющії.","Ра́дуйтеся, даро́в духо́вних всегда́шнії подателі.","Ра́дуйтеся, болі́зней душе́вних і тіле́сних ціли́телі благода́тнії.","Ра́дуйтеся, не́мощі немощни́х на себі́ носи́вшії.","Ра́дуйтеся, спасе́нію мно́гих душ челові́чеських послужи́вшії.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник ди́вних чуде́с яви́лся єси́, святи́телю о́тче Нико́лає, прия́л бо єси́ от Го́спода дар неду́ги душе́вния і тіле́сния врачева́ти, бі́си ізгоня́ти і всіх су́щих в біда́х ско́ро от тіх ізбавля́ти. Ті́мже прибіга́єм к тебі́, я́ко плі́нних свободи́телю, ни́щих засту́пнику і благоді́телю, врачу́ благода́тному і ми́лостивому, да спаса́ємі святи́м предста́тельством твої́м, воспіва́єм о тебі́ Христу́ Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє вас, отці́ богоно́снії, святи́телі Христо́ви, не то́кмо учи́телей духо́вних і к жи́зні ві́чній путеводи́телей, но і ціли́телей от вся́ких тіле́сних і душе́вних неду́гов - хвалу́ Го́споду воздаваша. Ми же за мно́гая і неісче́тная ісціле́нія ва́ша, на ни ізлива́ємая, ублажа́єм вас, ми́лостивих предста́телей і чудотво́рцев, похвала́ми си́ми:","Ра́дуйтеся, Єди́ному Бо́гу, в Тро́йці сла́вимому, ві́рно послужи́вшії.","Ра́дуйтеся, многоразли́чними дарова́ньми Ду́ха Свята́го укрепленнії.","Ра́дуйтеся, ві́ри і́стинния дерзнове́ннії пропові́дници.","Ра́дуйтеся, апо́стольських преда́ній храни́тели.","Ра́дуйтеся, архієре́ї Бо́жії, до́брі упа́сшії слове́сноє ста́до ва́ше.","Ра́дуйтеся, от єресе́й і раско́лов огражде́ніє.","Ра́дуйтеся, заблу́ждших на путь пра́вий наставля́ющії.","Ра́дуйтеся, бісо́в і́менем Христо́вим ізгоняющії.","Ра́дуйтеся, любо́вію ва́шею всіх покрива́ющії.","Ра́дуйтеся, благода́тную ро́су ісціле́ній ві́рним істоча́ющії.","Ра́дуйтеся, болі́зньми тя́жкими одержи́мих прему́дрії врачевателі.","Ра́дуйтеся, о всем ми́рі печа́льници і моли́твенниці.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 6","ps":["Пропові́дуєть весь мир христия́нський ве́ліє чу́до, тобо́ю сотворе́нноє, священному́чениче Вла́сіє, єгда́ жена́ ні́кая, іму́щая си́на своєго́ близ сме́рти лежа́ща, положи́ єго́ при но́гу твоє́ю, пла́чущи і вопію́щи о ісціле́нії єго́: ти же, о́тче, і́менем Спаси́теля ісціли́л єси́ єго́, глаго́ля: «А́ще в челові́ціх і в скотах что таково́є случи́ться, і пом'яне́ть кто і́м'я моє́, тому́ Ти, Го́споди, ускори́ на по́мощ». Ті́мже мо́лим тя: не лиши́ тоя́ благода́ті і нас, да і ми здра́ви су́ще ті́лом і душе́ю поє́м Бо́гу благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в сердця́х ва́ших світ Боже́ственния любве́ і благода́ті, святи́телі Христо́ви і страстоте́рпці, кро́вію свяще́нную оде́жду свою́ украси́вшії; ті́мже просла́ви вас Госпо́дь, ви́дя ва́ше безмі́рноє ко всім сострада́ніє, я́ко соблюдаєте от вся́кия болі́зні не то́чію челові́ки, но і скоти́, і до́ми ві́рних вся́ких благ ісполня́єте. Не отри́ніте у́бо і нас, грі́шних, скорбми́, болі́зньми і мно́гими печа́льми обурева́ємих, і помозі́те всім вопію́щим вам такова́я:","Ра́дуйтеся, душі́ своя́ за ві́ру Правосла́вную положи́вшії.","Ра́дуйтеся, служи́телі Бо́жия себі́ би́ти пред мучи́телі іспові́давшії.","Ра́дуйтеся, страсте́м Христо́вим му́жественнії подража́телі.","Ра́дуйтеся, свяще́нную оде́жду ва́шу кровми́ страда́ній обагри́вшії.","Ра́дуйтеся, я́ко ва́ми от мно́гих ран грі́шнії ізбавля́ються.","Ра́дуйтеся, я́ко ва́ми от вся́ких болі́зней ві́рнії свобожда́ються.","Ра́дуйтеся, неісчерпа́ємії істо́чници ісціле́ній.","Ра́дуйтеся, я́ко возложе́нієм рук ва́ших і зві́ри от болі́зней ісціля́ються.","Ра́дуйтеся, нетлі́нієм моще́й ва́ших сла́вно от Бо́га возвеличеннії.","Ра́дуйтеся, мно́гими чудеси́ от них ві́рних возвеселившії.","Ра́дуйтеся, ісціле́нія во сла́ву Бо́жию соверша́ющії.","Ра́дуйтеся, ті́ми нас к прославле́нію Бо́га призива́ющії.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти милосе́рдіє Своє́ лю́дем, дарова́ нам тя, великому́чениче Пантелеї́моне, вели́каго ціли́теля болі́зней душе́вних і тіле́сних і прогони́теля духо́в зло́би поднебе́сних: ти бо ми́лости Бо́жия подо́б'яся, от Самаго́ Вседержи́теля Спа́са по достоя́нію іменова́ніє всеми́лостиваго приє́м, я́ко сострада́телен бил єси́ і ми́луєши всіх, сугу́бо подая́ ісціле́нія, сло́вом благода́ті врачу́я і к ра́зуму Боже́ственному наставля́я ві́рних, подвиза́я їх пі́ти Пода́телю всіх благ Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ ми́лость рабо́м Свої́м Человіколю́бець Госпо́дь, єгда́ благоволи́ яви́ти сонм святи́х му́чеников, моли́твенников, ціли́телей душ і тіле́с на́ших і хода́таєв спасе́нія ві́чнаго: ви бо, святі́ї му́ченици, імі́юще ві́ру во Христа́, адама́нта тверді́йшую, му́жественно претерпі́ли єсте́ от гони́телей темни́чния у́зи і страда́нія, смерть же лю́тую прия́вше, же́ртвою благоприя́тною Бо́гу яви́стеся, і ни́ні, Небе́сному Престо́лу всіх Влади́ки предстоя́ще, неоску́дно ісціле́нія істоча́єте всім с ві́рою прибегающим к вам і зовущим та́ко:","Ра́дуйтеся, пресві́тлому му́ченичеському ли́ку сопричтеннії.","Ра́дуйтеся, я́ко муче́нія ва́ша зря́ще, мно́жество люде́й ко Христу́ обрати́шася.","Ра́дуйтеся, Го́споду своєму́ да́же до сме́рти послужи́вшії.","Ра́дуйтеся, чудотво́рці пресла́внії, на утіше́ніє нам дарова́ннії.","Ра́дуйтеся, святі́ї вра́чеве, болі́зні на́ша ісціля́ющії.","Ра́дуйтеся, сві́том доброді́телей ва́ших і нас духо́вно просвіща́ющії.","Ра́дуйтеся, в со́ніїх і виді́ніїх стра́ждущих посещающії.","Ра́дуйтеся, в біда́х і напа́стіх по́мощ нам подаю́щії.","Ра́дуйтеся, боля́щих младе́нцев і отроко́в прибі́жище і ісціле́ніє.","Ра́дуйтеся, скорбе́й роди́телей їх врачева́ніє.","Ра́дуйтеся, на мита́рствах возду́шних ві́рним по́мощ явля́ющії.","Ра́дуйтеся, о спасе́нії на́шем Го́спода умоляющії.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці на землі́ себі́ помишля́юще, святі́ї бра́тія, вра́чеве-безсре́бреници Космо́ і Дамія́не, нічесо́же от тлі́нних веще́й ми́ра сего́ стяжа́ти себі́ не возжелали єсте́, всегда́ іму́ще Христа́, ді́йствующа во вас, і си́лою Того́ боля́щих ісціля́єте, врачевство́ бо ва́ше істо́чник єсть неісчерпа́ємий, на всяк день умножаємий. Не оста́віте у́бо і нас благода́тною ва́шею по́мощію, да всі с ві́рою і любо́вію воззове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все житіє́ ва́ше на землі́ любо́вію к Бо́гу і бли́жнім іспо́лнено бисть, святі́ї вра́чеве-безсре́бреници, ми́ро благоуха́нноє ісціле́ній істоча́ющії, от бід і скорбе́й ізбавля́ющії, печа́лі утоляющії всіх почита́ющих вас. Благодари́м і велича́єм просла́вившаго вас Го́спода, дарова́вшаго нам ди́вний богосві́тлий собо́р моли́твенников, ціли́телей і чудотво́рцев, Єго́же, святі́ї безсре́бреници, умолі́те спасти́ся всім пою́щим вам такова́я:","Ра́дуйся, святи́й Апо́столе Луко́, і́стинний врачу́ духо́вний, Єва́нгеліє всей тва́рі пропові́давий.","Ра́дуйся, святи́телю Спиридо́не Тримифу́нтський, вели́кий чудотво́рче, вся́ку болі́знь і я́зву ісціля́яй і ме́ртвих пресла́вно воскреша́яй.","Ра́дуйся, священному́чениче Анти́по Пергамський, дия́вольськую си́лу попра́вий і всім христия́ном благода́тная ісціле́нія да́руяй.","Ра́дуйся, святи́телю Модесте, похвало́ свята́го гра́да Ієрусали́ма, істо́чниче ми́лости неізсяка́ємий і чудотво́рче.","Ра́дуйся, великому́чениче Арте́міє, мучи́теля, злочести́ваго царя́, побіди́телю, страсте́й разжже́ніє угаша́яй і ду́хи нечи́стия прогоня́яй.","Ра́дуйся, священному́чениче Ермола́є, па́стирю до́брий Христо́ва стада́ і свята́го Пантелеї́мона Ціли́теля і́стинний учи́телю.","Ра́дуйтеся, три одноіменния і єдинонра́вния дво́їці бра́тій Космо́ і Дамія́не богому́дрії, вра́чеве-безсре́бренници, боля́щих стра́сті ту́не ісціля́ющії.","Ра́дуйтеся, му́ченици Ки́ре і Іоа́нне, Боже́ственнії вра́чеве, я́ко чудоді́йствуєте непреста́нно, вся неду́ги на́ша ісціля́юще.","Ра́дуйся, му́чениче Діоми́де, врачу́ душ і тіле́с, і́стинний і непобіди́мий страстоте́рпче, даро́в Боже́ственних іспо́лненний.","Ра́дуйтеся, Фо́тіє сла́вний і богому́дрий Аники́то, дво́їце страда́льцев, огнь і муки́ проше́дшії і віне́ць побі́дний приявшії.","Ра́дуйся, му́чениче Фалале́є, врачу́ ізря́дний, тя бо даде́ Влади́ка Христо́с на ісціле́ніє всім ві́рним.","Ра́дуйся, му́чениче Три́фоне, дар Боже́ственних ісціле́ній прия́вий, от ко́зней дия́вола нас охраня́яй.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє і челові́чеськоє удиви́ся ді́лу милосе́рдія Госпо́дня, я́ко дарова́ нам, грі́шним, в по́мощ і заступле́ніє тя, преподо́бне о́тче Сампсо́не, врача́ преізряднаго і ми́лостиваго, благода́ть ісціле́ній подаю́щаго, єди́ним прикоснове́нієм руки́ своєя́ царя́ ісціли́вшаго, моли́твенника благоприя́тна, а́лчущих і ни́щих пита́теля і су́щих в ну́ждіх побо́рника вели́ка. Ті́мже всі ві́рнії ві́дуще тя, я́ко служи́теля Христо́ва і преподо́бним отце́м прича́стника, вопію́ть о тебі́ благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть по достоя́нію восхвали́ти вас, преподо́бнії і богоно́снії отці́ на́ші, я́ко наста́вников мона́хов і А́нгелов собеседников, і просла́вити по́двиги і діла́, ї́хже твори́ли єсте́ на землі́. Оба́че і по преставле́нії мно́гая і пресла́вная чудеса́ і ісціле́нія твори́ти не престаєте, честни́я бо мо́щі ва́ша подо́бни Силоа́му, іді́же хромі́ї, неду́жнії, разсла́бленнії і одержи́мії духа́ми зло́би здра́віє улуча́ють: і́бо ра́ди по́двигов ва́ших прия́сте от Го́спода власть ціли́ти болі́зні неісці́льния, утоля́ти стра́сті на́ша, возбужда́ти в лю́діх плач о грісі́х, да чи́стою со́вістію і сокруше́нним се́рдцем воспіва́єм вам похвали́ сія́:","Ра́дуйтеся, житію́ безпло́тних поревновавшії.","Ра́дуйтеся, во всем христия́нстім ми́рі я́ко вели́кия ціли́телі просла́вленнії.","Ра́дуйтеся, о́браз житія́ пра́веднаго нам показу́ющії.","Ра́дуйтеся, побіжда́ти мир, плоть і дия́вола нам помога́ющії.","Ра́дуйтеся, мно́гая чудеса́ і зна́менія от моще́й ва́ших явля́ющії.","Ра́дуйся, я́ко моще́й ва́ших де́мони трепе́щуть.","Ра́дуйтеся, от Го́спода власть на ду́хи нечи́стия приє́мшії.","Ра́дуйтеся, си́лою Бо́жиєю їх прогоняющії.","Ра́дуйтеся, бездетним роди́телем чадоро́діє да́рующії.","Ра́дуйтеся, омраче́нних умо́м просвіти́телі богому́дрії.","Ра́дуйтеся, сосу́ди, єле́й милосе́рдія Бо́жия істоча́ющії.","Ра́дуйтеся, живоно́сния істо́чници, струї́ ісціле́ній нам ізлива́ющії.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ душі́ люде́й, неду́гом пія́нства одержи́мих, Всеми́лостивий Госпо́дь дарова́ помо́щников і ціли́телей от зли́я стра́сті сея́: свята́го му́ченика Вонифатія, преподо́бнаго Мойсе́я Му́рина, преподо́бнаго Варлаа́ма Серпуховська́го і іни́х мно́гих уго́дников Свої́х і подви́жников. Ми же, прекло́ньше колі́на і руки́ своя́ просте́рше к вам, святі́ї отці́ і ма́тері, мо́лим вас: умолі́те Го́спода дарова́ти ісціле́ніє погиба́ющим от пія́нства бра́тіям і сестра́м на́шим, житія́ тре́звеннаго і цілому́дреннаго нача́ло положи́ти всіх нас сподо́біте, да возмо́жем побіди́ти борющий нас гріх і непреста́нно сла́вити Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ бисть і заступле́ніє всім стра́ждущим лю́дем чу́дний о́браз Богома́тере, пред ни́мже ні́кий крестьянин, ісполня́я повелі́ніє преподо́бнаго Варлаа́ма Серпуховська́го, отслужи моле́бен і от стра́сті винопи́тія ісціли́ся: та бо іко́на, Неупива́ємою Ча́шею імену́ємая, ісціле́нія да́руєть отчаявшимся і погиба́ющим, найпа́че же болезнующим пія́нством. Ті́мже мо́лим Тя, Пречи́стая Влади́чице: ісціли́ нас, стра́ждущих от страсте́й гріхо́вних, моли́твами святи́х ціли́телей і чудотво́рцев, помо́щников на́ших Богодарованних, к ни́мже благода́рственно взива́єм си́це:","Ра́дуйтеся, от мучительнаго неду́га пія́нства стра́ждущих ізбавля́ющії.","Ра́дуйтеся, к і́скреннему покая́нію і ісправле́нію їх приводящії.","Ра́дуйтеся, глубину́ милосе́рдія Богома́тере стра́ждущим показу́ющії.","Ра́дуйтеся, я́ко благода́тію Єя́ мно́гія от стра́сті пія́нства ісціля́ються.","Ра́дуйтеся, отча́янним наде́жду на по́мощ подаю́щії.","Ра́дуйтеся, от ро́ва поги́бельнаго безнадежния спасающії.","Ра́дуйтеся, к по́двигу воздержа́нія всіх призива́ющії.","Ра́дуйтеся, от смертоно́снаго зе́лія нас ограждающії.","Ра́дуйтеся, от страсте́й, я́ко от сна поги́бельнаго, нас пробуждающії.","Ра́дуйтеся, всім борющимся с гріхми́ покрови́телі Богодарованнії.","Ра́дуйтеся, к но́вому, пра́ведному і трезвенному житію́ нас направляющії.","Ра́дуйтеся, я́ко моли́твами ва́шими духо́вную на́шу жа́жду утоляєте.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Пресвяті́й Тро́йце лю́діє землі́ на́шея прино́сять, прославля́юще тя, преподо́бне о́тче Се́ргіє, я́ко вели́каго засту́пника, ціли́теля і уті́шителя правосла́вним христия́ном, в держа́ві на́шей і по всему́ ли́ку землі́ обитающим, і́бо да́нною тебі́ Бо́жиєю благода́тію сліпи́я просвіща́єши, от тіле́сних і душе́вних болі́зней ісціля́єши, от де́монськаго наси́лія свобожда́єши, от напа́стей огражда́єши і вся на́ша проше́нія во бла́го ісполня́єши, вопія́ возлю́бленному тобо́ю Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници світоприє́мнії от і́стиннаго Сві́та озаря́ємії, яви́стеся, святі́ї землі́ на́шея: ієра́рсі і преподо́бнії, священному́ченици і му́ченици, Христа́ ра́ди юро́дивії і святи́х дів і жен сосло́віє, с ни́миже собо́р новому́чеников і іспові́дников Ру́ських, вку́пі іменуємії і неіменуємії, ві́домії на́ми і неві́домії. Лю́діє же, обремене́ннії гріха́ми, болі́зньми і скорбми́ мно́гими, обріто́ша вас засту́пников і ціли́телей: подаєте́ бо во вся дні битія́ наро́да на́шего врачева́ніє страсте́м неісці́льним, сліпи́м прозрі́ніє, глухи́м сли́шаніє, разсла́бленним здра́віє, стра́ждущим раковими я́звами ісціле́ніє і всім благода́ть ізлива́єте, ра́достію озаря́юще се́рдця ві́рних, чту́щих вас і воспіва́ющих с любо́вію такова́я:","Ра́дуйся, преподо́бне Ага́пите, пе́рвий врачу́ безме́здний в землі́ на́шей і вели́кий чудотво́рче.","Ра́дуйся, святи́телю Алексі́є, па́стирю і учи́телю прему́дрий землі́ на́шея, ісціле́нія струї́ ві́рним істоча́яй.","Ра́дуйся, преподо́бне Серафи́ме Саро́вський чудотво́рче, врачу́ ско́рий і благода́тний.","Ра́дуйся, святи́й пра́ведний Іоа́нне Кроншта́дтський, Це́ркве Правосла́вния моли́твенниче і чудотво́рче преди́вний.","Ра́дуйся, святи́й пра́ведний Іоа́нне Ру́ський, во іспові́данії Христа́ пострада́вий, боля́щих младе́нцев при́сний врачева́телю.","Ра́дуйтеся, святі́ї царственнії страстоте́рпці: Нико́лає, Алекса́ндро, Алексі́є, О́льго, Татіа́но, Марі́є і Анастасі́є, за зе́млю на́шу пред Бо́гом моли́твенниці і пресла́внії чудотво́рці.","Ра́дуйся, святи́телю Кримський і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий.","Ра́дуйся, преподо́бне о́тче Серафи́ме Вирицький, житіє́м і по́двиги дре́вніх оте́ць подража́телю, дар чудоді́йственния благода́ті приє́мий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє Поча́євський, врачу́ безме́здний, си́лою Бо́жиєю неісче́тния чудеса́ і ісціле́нія соверши́вий.","Ра́дуйся, преподо́бная княги́не Євфроси́ніє, Бо́гу угоди́вшая і дар ісціле́ній от Него́ прия́ти сподо́бившаяся.","Ра́дуйся, свята́я блаже́нная Ксе́ніє, безу́мієм мни́мим безу́міє ми́ра обличи́вшая і дар чудоді́йственния по́мощі от Христа́ стяжа́вшая.","Ра́дуйся, преподобному́ченице Вели́кая княги́не Єлисаве́то, духо́вною і тіле́сною красото́ю возсія́вшая і лю́дем і́стинную любо́в і милосе́рдіє показа́вшая.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 12","ps":["Благода́ть, ю́же даде́ вам Госпо́дь Бог, ціли́ти вся неду́ги душе́вния і тіле́сния, днесь нас собра́, да почти́м святу́ю па́м'ять ва́шу, святі́ї вра́чеве, ціли́телі і чудотво́рці. Ті́мже у́бо, благогові́йні взира́юще на честну́ю іко́ну ва́шу, уго́дниці Бо́жії, і со умиле́нієм серде́ць к ней припа́дающе, мо́лим вас: не то́кмо от неду́гов і болі́зней нас ісцілі́те, но чу́дним сві́том Бо́жиїм на́шу жизнь озарі́те, благослові́те нас ми́ром і любо́вію, пода́йте нам тве́рдую ві́ру, чистоту́ жи́зні і страх Бо́жий, от гріхо́вния поги́белі нас соблюді́те, да ва́шим заступле́нієм дости́гнем Небе́снаго оте́чества, іді́же с ва́ми воспої́м Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Го́спода, ди́внаго во святи́х Свої́х, хва́лим і прославля́єм ни́ні святи́й і вели́кий собо́р ціли́телей і чудотво́рцев, с ни́мже Сама́ Пречи́стая Ді́ва Богоро́диця, Арха́нгели і А́нгели, Боже́ственнії Апо́столи, проро́ци і святи́телі, му́ченици і преподо́бнії, блаже́ннії і всі пра́ведници ликовству́ють. Сла́вим і велича́єм просла́вльшаго вас Христа́ Бо́га на́шего, ізлившаго на вас оби́ліє Свої́х даро́в благода́тних; вас же, святи́х помо́щников і предста́телей на́ших, благода́рним се́рдцем і усти́ ублажа́єм пі́сньми такови́ми:","Ра́дуйся, святи́й Архістрати́же Бо́жий Рафаї́ле, всіх душе́вних і тіле́сних неду́гов благода́тний ціли́телю.","Ра́дуйтеся, святі́ї пра́веднії Богоотці́ Іоаки́мі і А́нно, непло́дство супру́гов благода́тію Бо́жиєю разріша́ющії.","Ра́дуйся, великому́чениче і Побідоно́сче Гео́ргіє, непобіди́мий во́їне Христа́ Бо́га на́шего, немощству́ющих ско́рий врачу́ і всім в ско́рбіх і біда́х су́щим засту́пниче.","Ра́дуйся, святи́телю Іулія́не, свята́го Апо́стола Петра́ учениче́, младе́нці от болі́зней і сме́рті благода́тно сохраня́яй.","Ра́дуйся, преподо́бне о́тче Паї́сіє Вели́кий, моли́твою ду́шу послу́шника своєго́ із а́да ізведи́й і нас от муки́ ві́чния моли́твами твої́ми ізбавля́яй.","Ра́дуйтеся, святі́ї му́ченици Фло́ре і Ла́вре, Богому́драя дво́їце пресві́тлая, трудолюбці незло́бивії і неду́гов на́ших ціли́телі.","Ра́дуйтеся, преподо́бний царю́ Симео́не Мироточи́вий і святи́телю Са́вво, Се́рбськая похвало́, мно́гими чудеси́ і да́ром ісціле́ній от вся́ких болі́зней Бо́гом просла́вленнії.","Ра́дуйся, преподо́бне о́тче Іоа́нне Рильський, лечебную си́лу от Бо́га прия́вий і всім с ві́рою приходящим здра́віє подава́яй.","Ра́дуйся, преподо́бная ма́ти Марі́є Єги́петськая, стра́сті плотські́я мече́м воздержа́нія посіка́ти нас науча́ющая.","Ра́дуйся, страстоте́рпице Христо́ва Параске́во, світ благода́тний душе́вним і тіле́сним оча́м на́шим открива́ющая.","Ра́дуйся, му́ченице Агриппи́но, прокаже́нния от неісці́льния сея́ болі́зні свобожда́ющая.","Ра́дуйся, великому́ченице Мари́но, си́лою Креста́ главу́ дия́вола сокруши́вшая і мно́гих неду́гов лю́тих прогони́тельнице.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 13","ps":["О преди́внії і пресла́внії уго́дниці Бо́жії, святі́ї вра́чеве-безсре́бреници і чудотво́рці, ско́рії помо́щници всім с ві́рою к вам прибегающим! Приймі́те сіє́ хвале́ніє на́ше і мольби́ сле́зния вам приноси́мия, ісцілі́те многообра́зния неду́ги душ і тіле́с на́ших і те́плим предста́тельством ва́шим іспросі́те нам у Христа́ Бо́га ізбавле́ніє от всіх бід і напа́стей, проще́ніє прегріше́ній на́ших і благу́ю наде́жду ві́чнаго спасе́нія, да сподо́бимся с ва́ми і со всі́ми святи́ми воспіва́ти во ві́ки Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і челові́ков Творе́ць ізбра́ вас, враче́й, ціли́телей і чудотво́рцев свято́є сосло́віє, я́ко любо́вію і сострада́нієм ко всім лю́дем горя́щих, і дарова́ вам сугу́бую благода́ть, да бу́дете ізбавля́ти от бід, скорбе́й, болі́зней і вся́ких лю́тих іскуше́ній всіх чту́щих святу́ю па́м'ять ва́шу і с любо́вію восхваля́ющих вас та́ко:","Ра́дуйся, святи́й Проро́че, Предте́че і Крести́телю Госпо́день Іоа́нне, душі́ на́ша покая́нієм обновля́яй.","Ра́дуйся, святи́й пра́ведний Симео́не, Богомладе́нця Христа́ на ру́ці свої́ приє́мий і ни́ні всіх младе́нцев Богодарова́нний храни́телю.","Ра́дуйся, святи́й Апо́столе і Євангели́сте Іоа́нне Богосло́ве, возлю́бленний Христо́в учениче́, лю́б'ящим і чту́щим тя любо́вію воздава́яй.","Ра́дуйся, му́чениче Лонгине, от ка́плі Кро́ве Го́спода о́чі свої́ ісціли́вий і благода́ть обріти́й духо́вноє прозрі́ніє лю́дем дарова́ти.","Ра́дуйтеся, святі́ї му́ченици Зинаїдо і Филонилло, сро́дниці Апо́стола Па́вла, сугу́бо боля́щим послужившия.","Ра́дуйтеся, священному́чениче Киприя́не і му́ченице Іусти́но, от бісо́в і злих челові́к волхвова́нія крі́пції засту́пниці.","Ра́дуйся, великому́чениче Дими́тріє Солунський, ми́ро благово́нноє всім боля́щим на ісціле́ніє істоча́яй.","Ра́дуйся, Кесаріє Назіянзине, царе́й благочести́вих врачу́, от мно́гих тя́жких неду́гов богому́дрий ціли́телю.","Ра́дуйся, великому́ченице Варва́ро, а́гнице всеблаже́нная, от внеза́пния сме́рті ві́рних ізбавля́ющая.","Ра́дуйся, великому́ченице Єкатери́но, ді́во прему́драя, ізбра́нний сосу́де чистоти́, омраче́ніє ума́ на́шего просвіща́ющая.","Ра́дуйся, великому́ченице Анастасі́є, неду́ги заключе́нних в темниціх врачевавшая і от мно́гих скорбе́й нас ізбавля́ющая.","Ра́дуйся, му́ченице Фомаї́до, цілому́дрія ра́ди ду́шу свою́ положившая і плотські́я стра́сті побіжда́ти лю́дем помога́ющая.","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Кондак 1","ps":["Ізбра́ннії помо́щници стра́ждущих, вра́чеве неду́гующих і чудотво́рці преди́внії, святі́ї безме́зднії ціли́телі ми́лостивії, похва́льная воспису́єм вам, засту́пником на́шим і в ско́рбіх уті́шителем. Ви же, я́ко іму́щії дерзнове́ніє ко Всемилостивому́ Спа́су на́шему, ізба́віте от страсте́й і болі́зней всіх ві́рою і любо́вію воспіва́ющих вам:","Ра́дуйтеся, святі́ї Богоблаже́ннії вра́чеве, ціли́телі душ і тіле́с на́ших."]},{"h":"Молитва","ps":["О чудотво́рці сла́внії, вра́чеве безме́зднії, земні́ї а́нгели і небе́снії челові́ци, скоропослушливії помо́щници всім к вам прибегающим! Ви бо, уго́дниці Бо́жії, безчи́сленними чудеси́ весь мир наполня́єте і не то́кмо тіле́сния неду́ги ісціля́єте, но і ві́рою Христо́вою душі́ просвіща́єте, в терпі́нії болі́зней укріпля́єте, в тя́жких неду́зіх су́щих о ісправле́нії житія́ вразумляєте, ко Христу́ покая́нієм направляєте і си́лою Всемогу́щаго Бо́га оби́льния да́ри благода́тния по́мощі істоча́єте. Сего́ ра́ди к вам, я́ко благода́тним враче́м, ми, недосто́йнії і грі́шнії, с благогові́йною любо́вію припа́даєм і мо́лимся: усли́шіте воздиха́нія мно́жества стра́ждущих люде́й, умолі́те Небе́снаго Врача́ душ і тіле́с на́ших і Єго́ Пречи́стую Ма́тер дарова́ти нам ісціле́ніє от неду́гов на́ших, сохрані́те нас от лю́тих і неісці́льних болі́зней, от разслабле́нія ті́ла, от ісступленія ума́ і смертоно́сния я́зви, от внеза́пния сме́рті, от вся́кия біди́ і ско́рби і от вся́каго зла; помозі́те всім в не́мощіх лежащим і в челові́чеськой по́мощі отчаявшимся, к вам же с наде́ждою прибегающим; утіше́ніє і отра́ду пода́йте всім в тя́жких рабо́тах, в заточе́нії і темниціх унивающим і, те́плим хода́тайством ва́шим к Бо́гу, соблюді́те во ві́рі правосла́вній, в богоми́слії, в моли́твах к Бо́гу прилежних; умолі́те Го́спода, да пода́сть всім нам христия́нськую кончи́ну безболі́зненну, непости́дну, ми́рну, Боже́ственних Та́їн прича́стну, і до́брий отві́т на Стра́шнім Суді́ Своє́м, да с наде́ждою спасе́нія дости́гнем Ца́рствія, єго́же угото́ва Госпо́дь лю́б'ящим Єго́, і сподо́бимся ку́пно с ва́ми, уго́дниці Бо́жії, сла́вити Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст преподобному Гавриїлу (Ургебадзе)","e":"Akathist to our Venerable Father Gabriel (Urgebadze)","secs":[{"h":"Кондак 1","ps":["Му́дрости ві́ка сего́ юро́дство креста́ Христо́ва предпоче́т, вся ми́ра сла́дкая і льсти́вная я́коже ізгре́біє пе́щноє вміни́л єси́, о́тче Гавриї́ле. І крест свой взем, єди́ному Христу́ послі́довал єси́ ізді́тська і до послі́дняго іздиха́нія. І та́ко вшел єси́ в Небе́сния Оби́телі, іді́же ни́ні предстоя́ своєму́ Влади́ці, мо́лиши о нас, пою́щих ті:","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Ікос 1","ps":["Єва́нгеліє обрі́т, я́коже сокро́вище, на селі́ сокри́тоє, с ра́достію вся расточи́л єси́, да Христа́ приобря́щеши, і я́коже ку́плений раб во виногра́ді Госпо́днем нелі́ностно ді́лал єси́. І ми тебі́ поє́м:","Ра́дуйся, ді́лателю пе́рваго часа́;","ра́дуйся, я́ко раба́, нічесо́же сотво́рша, себі́ вміня́яй.","Ра́дуйся, я́ко апо́стол Андре́й, на зов Христо́в не заме́дливий;","ра́дуйся, я́ко Петр, горя́чим се́рдцем єго́ приє́мий.","Ра́дуйся, от Него́ нічто́же себі́ утаї́вий;","ра́дуйся, я́ко ле́пті вдови́чі все житіє́ своє́ в дар Бо́гу вве́ргнувий.","Ра́дуйся, до́брая земле́, на не́йже сі́м'я прозябе́ і припло́дова;","ра́дуйся, тала́нти, от Бо́га да́нния, мно́гажди возрасти́вий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 2","ps":["Єще́ гріха́ не позна́в, на плоть свою́ вооружи́лся єси́, похотству́єть бо на ду́ха, я́коже апо́стол рече́. Ізді́тська не ві́дая си́тости, ніже́ м'я́гкаго ло́жа, чте́нію же Єва́нгелія приліжа́ і усе́рдній моли́тві. Такові́й твоє́й ре́вности о Бо́зі удивля́ємся, глаго́люще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Раздраже́н твої́ми по́двиги, біс яви́ся ті я́ві, отмсти́ти хотя́. Оба́че Госпо́дь от рожде́нія храня́й тя, я́ко сосу́д свой ізбра́нний, благода́тію Своє́ю тя сохрани́. І ми тебі́ взива́єм та́ко:","Ра́дуйся, ізмла́да к себі́ жа́лости не імі́яй;","ра́дуйся, о́троче, бі́су противобо́рствуяй.","Ра́дуйся, і ма́тере ра́ди от о́браза житія́ своєго́ не отступи́вий;","ра́дуйся, саму́ ду́шу свою́ в ми́рі сем возненави́дівий.","Ра́дуйся, в мі́ру дре́вніх отце́во во бді́нії і по́стничестві прише́дий;","ра́дуйся, іні́м же по си́лам подвиза́тися благословля́яй.","Ра́дуйся, плоть свою́, я́ко же́ртву жи́ву, свя́ту, благоуго́дну Го́сподеві принеси́й;","ра́дуйся, за словеса́ Госпо́дня сохрани́вий путі́ же́стоки.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 3","ps":["Мно́го скита́ній претерпі́л єси́ ти, о́тче, єще́ о́трок сий, ходя́ із монастиря́ в монасти́р, до́ндеже прише́л єси́ в Бета́нію, наше́д отце́в свої́х духо́вних, с ни́миже ни́ні поє́ши Христу́, тобо́ю возлю́бленному, хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["По́сліжде прия́л єси́ досто́їнство мона́ха і свяще́нника, по сих і архімандрі́та, но і во всем житії́ твоє́м мно́гая лі́та не імі́л єси́ себе́ приста́нища. І на кла́дбищі среди́ моги́л нема́ло жил єси́, пита́яся подая́нієм, і та́ко Го́споду своєму́ послі́дуя, не іму́щему, гді главу́ подклони́ти. Сего́ ра́ди твої́м по Христе́ ше́ствієм поуча́ємі, зове́м ті си́це:","Ра́дуйся, гони́мий, я́ко всі о Христі́ благоче́стно жи́ти хотя́щії;","ра́дуйся, Госпо́день апо́столе, без суми́ і зла́та по́сланний.","Ра́дуйся подви́жниче, до вре́мене ники́мже по́знанний;","ра́дуйся, по́сліжде всеми люби́мий і почита́ємий.","Ра́дуйся, житіє́м среди́ моги́л страх навсегда́ побіди́вий;","ра́дуйся, єди́наго гріха́ отто́лі боя́тися научи́вийся.","Ра́дуйся, глад і мраз в нічто́же вміня́яй любве́ ра́ди Христо́ви;","ра́дуйся, реки́й, я́ко скорбми́ науча́ємся ві́рі і любві́.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 4","ps":["Це́рков Христо́ву, в запусті́нії би́вшую, возсозида́л єси́, о́тче Гавриї́ле, єще́ ізді́тська ігра́я, о́трок же сий, тя́жкіє ка́мни нося́ і це́рков пору́шенную возводя́ по зо́ву свята́го Гео́ргия, по сих же і храм свой прекра́сний созда́в, в него́же і ни́ні прихо́дять ві́рнії воспі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["О́тче Гавриї́ле, созида́я святи́ні, і о́брази по дома́м собира́я, раді́л єси́ ти, даби́ же́ртва Бо́гові приноси́лася і та́їнства соверша́лися, і та́ко да возсозда́ни бу́дуть хра́ми пору́шенії в душа́х челові́чеських, да возно́ситься в них моли́тва Бо́гові. Сего́ ра́ди ми, благода́рнії, взива́єм си́це:","Ра́дуйся, святи́нь благогові́йний храни́телю;","ра́дуйся, іко́н, в небреже́нії би́вших, попечи́телю.","Ра́дуйся, во вся́цім челові́ці іко́ну Бо́жию лицезрі́вий;","ра́дуйся, о́браз пору́шенний челові́ком возвраща́яй.","Ра́дуйся, храм свой велеле́пий созда́вий і возсозда́вий;","ра́дуйся, єму́же а́нгели я́ко подмасте́рія служа́ху.","Ра́дуйся, храм свой тіле́сний свят і чист в служе́ніє Бо́гові угото́вавий;","ра́дуйся, я́ко ни́ні мо́щі твоя́ істоча́ють благода́ть.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 5","ps":["О́тче святи́й, ти рекл єси́, я́ко мона́ху тве́рду во і́стині би́ти подоба́єть. Ти же до кро́ве і до сме́рти свиді́тельствовал єси́ ві́ру твою́, єгда́ ізше́л єси́ на пло́щадь, а́ки на три́знище, дре́внім му́чеником подо́бен, смерть Христа́ ра́ди предпоче́т согла́сію с поклоне́нієм і́дольським. Твоєму́ дерзнове́нію подража́ти не могу́ще, взива́єм Укрі́пльшему тя: Аллилу́я."]},{"h":"Ікос 5","ps":["Тве́рдо шел єси́, о́тче, на му́ки і смерть, єгда́ огне́м возже́гл єси́ ізображе́ніє і́дольськоє, глаго́ля за́повідь Госпо́дню, є́же не сотвори́ себі́ куми́ра, ні вся́каго подо́бія єго́, па́ству свою́ науча́я Бо́гу єди́ному воздава́ти поклоне́ніє. Ті́мже ми, малові́рнії, восхваля́єм тя си́це:","Ра́дуйся, богодохнове́нний ві́ри іспові́дниче;","ра́дуйся, до́брий па́стирю, о па́стві своє́й раде́яй.","Ра́дуйся, Христа́ ра́ди пострада́ти жела́вий;","ра́дуйся, сугу́бая муче́нія, в темни́ці і среди́ безу́мних претерпі́вий.","Ра́дуйся, сме́рті то́кмо си́лою Бо́жиєю ізбе́гнувий;","ра́дуйся, отто́лі я́ко безу́мець вмене́нний.","Ра́дуйся, я́коже отре́би ми́ру би́вий;","ра́дуйся, торжество́ Це́ркве но́ваго вре́мене.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 6","ps":["Я́ко мона́х тща́тельнешій, о́тче Гавриї́ле, вся за́повіді храни́л єси́, найпа́че же смире́ніє, я́ко Бо́гу свіщу́ неугаси́мую. Єще́ о́троку тебі́ би́вшу, ді́лал єси́ ку́чу со́ра сіда́лище своє́, себі́ а́ки нічто́же вміня́я. По́двиг же юро́дства на себі́ под'я́в, себі́ явля́ше а́ки безу́мця і а́ки пія́ницю, і а́ки послі́дняго грі́шника. Таково́му по́двигу твоєму́ хвале́ніє вознося́ще, воспіва́єм до кре́стния сме́рті смири́вшему Ся Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Глаго́лал єси́, о́тче, і ча́дом свої́м смире́ніє стяжа́ти, я́ко в Рай вводя́щеє, і мно́гажди поуча́л єси́ сопроти́в гріхо́в горди́ні, і воі́стину то житіє́м свої́м явля́л єси́, ніколи́же своя́ дарова́нія показу́я, но то́кмо смотри́тельно явля́я, по́льзи ра́ди ві́рних. Ми же, горди́нею своє́ю свя́зани би́вше, а́ки у́зами мно́гими, взива́єм ті си́це:","Ра́дуйся, я́ко па́губу мона́ху похвалу́ іменова́вий;","ра́дуйся, тебі́ оби́девших, оскорби́вших і посмея́вшихся єще́ па́че жале́яй і люб'я́й.","Ра́дуйся, я́ко возвише́ніє себе́ я́ко ме́рзость пред Го́сподем ви́дяй;","ра́дуйся, я́ко во осужде́нії то́кмо неразу́міє, є́же єсть незна́ніє себі́, прозрі́вий.","Ра́дуйся, я́ко приходя́щаго к тебі́, а́ще грі́шен єси́, вопроша́ше;","ра́дуйся, сама́го себі́ а́ки грі́шника і́стинно іспові́давий.","Ра́дуйся, я́ко про́повідію своє́ю смире́нною си́лу Бо́жию явля́яй;","ра́дуйся. А́ки отроча́, в Ца́рствіє Небе́сноє невозбра́нно вше́дий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 7","ps":["Наро́да своєго́ ско́рби в се́рдці нося́, о́тче Гавриї́ле, о Гру́зії, уді́ле ізбра́ннім Бо́жия Ма́тере, усе́рдно моли́тви возсила́л єси́, глаго́ля, я́ко го́ре мона́ху, не моля́щуся о наро́ді своє́м. За таково́є твоє́ усе́рдіє сино́внєє, поє́м с тобо́ю Отцю́ всіх Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Предвозвеща́л єси́, о́тче, Гру́зії, во тьмі неві́рія су́щей, і Це́ркві єя́ гони́мей воскресе́ніє, я́коже Ла́зарю, оба́че чрез вели́кая іспита́нія. І бил єси́ кость от ко́сті наро́да своєго́, і святи́я Ни́ни і со́нма святи́х грузи́нських ча́до духо́вноє. Оба́че і Єги́петському Мака́рію і Саро́вському Серафи́му брат о Христі́ і сотаї́нник і́стинний. І ни́ні всі конці́ землі́ тебі́ пою́ть:","Ра́дуйся, до кончи́ни своєя́ се́рдцем о Гру́зії боле́яй;","ра́дуйся, на Афо́н поменя́ти ю не возжела́вий.","Ра́дуйся, просвітле́ніє духо́вноє наро́да своєго́ прови́дяй;","ра́дуйся, пред Втори́м Прише́ствієм сла́ву Гру́зії провозвісти́вий.","Ра́дуйся, я́ко аз уношу́ любо́в ко всему́ наро́ду правосла́вному, пред кончи́ною реки́й;","ра́дуйся, я́ко крест свой всю Гру́зію і полови́ну Украї́ни іменова́вий.","Ра́дуйся, стра́ждущия Гру́зії си́не ві́рний;","ра́дуйся, ма́ма Габріє́ли, всім правосла́вним ми́ра о́тче чадолюби́вий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 8","ps":["От младе́нства ми́лостив і милосе́рд бил єси́, о́тче Гавриї́ле, по́стничеський же по́двиг проше́д і іспове́дничеством просія́в, дости́гл єси́ в любо́в Христо́ву, я́же єсть ісполне́ніє зако́на. То́ю любо́вію твоє́ю ми согре́яни би́вше, бли́жнії і да́льнії, благода́рно зове́м всіх благ Пода́телю: Аллилу́я."]},{"h":"Ікос 8","ps":["О́браз любве́ соверше́нния о Христі́ Ісу́се яви́л єси́ нам, о́тче преподо́бне, я́же не зави́дить, не ми́слить зла, ра́дується же о і́стині, вся терпи́ть, всему́ ві́ру є́млеть, я́же ніколи́же отпа́даєть. Вся́каго челові́ка прийма́л єси́ ти в об'я́тія душі́ своєя́. Ті́мже ми, ча́да твоя́, зове́м ті:","Ра́дуйся, єго́же се́рдце горя́ бі о Христі́, я́коже у апо́стол на путі́ во Еммау́с;","ра́дуйся, в бли́жнем своє́м Христа́ всегда́ лицезрі́вий.","Ра́дуйся, єму́же люби́ даде́ зрі́ніє душ челові́чеських;","ра́дуйся, єму́же люби́ даде́ па́м'ять ніколи́же ослабева́ющую.","Ра́дуйся, нікого́же єди́ножди ви́діннаго забве́нію преда́вий;","ра́дуйся, я́ко оте́ць гріхи́ їх с любо́вію облича́яй.","Ра́дуйся, челові́ка без любве́ я́ко сосу́д без дна іменова́вий;","ра́дуйся, я́ко Паї́сій ста́рець, ду́шу свою́ бли́жняго ра́ди положи́вий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 9","ps":["Моли́тва твоя́, блаже́нне, досяза́ше до небе́с, бя́ше бо со смире́нієм, стра́хом Бо́жиїм і со слеза́ми, даде́ся бо тебе́ дар сле́зний, і в це́ркві-ке́ллії твоє́й на мі́сяци затворя́ся, пла́каше, я́коже ста́рець Силуа́н, о свої́х грісі́х, о оте́честві твоє́м, і о всем Ада́ме. Сего́ ра́ди, і днесь, мо́лиши о нас, твої́х моли́тв прося́щих, Бо́гу же пою́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Найпа́че призива́л єси́, па́стирю рачи́тельний, даби́ моли́тва не била́ во гріх, да моли́тві той до́брая діла́ послі́дують – та́ко подоба́єть моли́тися. Моля́йся же і за́повіді не ісполня́яй – злі мо́литься, та́ко глаго́лал і ді́лал єси́. І ми я́ко па́стирю на́шему та́ко взива́єм ті:","Ра́дуйся, запове́довавий Бо́гу со стра́хом предстоя́ти;","ра́дуйся, наказу́яй неспі́шно моли́тися, а не тра-та-та глаго́лати.","Ра́дуйся, я́ко Бо́гу всу́є стужа́ти возбраня́вий;","ра́дуйся, я́ко моли́тву без діл ме́ртвою іменова́вий.","Ра́дуйся, я́ко моли́тися за бли́жняго уча́й, та бо моли́тва любві́ науча́єть;","ра́дуйся, я́ко начина́ти о бли́жніх моли́тися, і та́ко да́же до враго́в доходи́ти наставля́яй.","Ра́дуйся, я́ко на моли́тві вопи́ти, я́ко младе́нцю к ма́тері, дале́че су́щей, сказу́яй;","ра́дуйся, ка́ятися бо́ліє се́рдцем, не́же слеза́ми призива́яй.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 10","ps":["Ві́ру правосла́вную, от отце́в пре́данную, тве́рдо храни́л єси́, Гавриї́ле преподо́бне, я́коже отці́ глаго́лаху, у́не єсть тебі́ блуднику́ би́ти, не́же єретику́, Поне́же, рекл єси́, ність любве́ спаси́тельния кромі́ Го́спода Ісу́са Христа́, І́же єсть І́стина і Живо́т. Ті́мже ми, твоєму́ стоя́нію во ві́рі поуча́яся, прино́сим Бо́гу ревни́телю хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Люб'я́й вся́каго челові́ка, о́тче, любве́ іспо́лненний, ти рекл єси́ отмета́тися єретико́в, глаго́ля: я́ко от Го́спода запові́дано бисть, не дава́ти святи́ні псом, ніже́ помета́ти би́сер пред свинія́ми, та́кожде і о є́ресі єресе́й упрежда́л єси́, я́же єсть єкумени́зм, ізме́ною Христу́ нариця́я. Ті́мже ми, челові́ком па́че, не́же Бо́гу угожда́ющії, зове́м ті:","Ра́дуйся, ві́ру свою́ позво́лити руга́ти, поги́белі приравня́вий;","ра́дуйся, без це́ркве живу́щих я́ко богоху́льников вменя́вий.","Ра́дуйся, я́ко за своє́ рожде́ніє во ві́рі правосла́вній Бо́га благодари́ти запові́давий;","ра́дуйся, я́ко пещи́ся о є́же спасу́ться ли во іні́х ве́рах су́щії, не веле́вий.","Ра́дуйся, любо́в свою́ і на самі́х враго́в Бо́жиїх простира́яй;","ра́дуйся, свої́м приме́ром в пра́вую ві́ру обраща́яй.","Ра́дуйся, я́ко времена́ анти́христа ско́ро хотя́щая би́ти предрека́яй;","ра́дуйся, імі́ти ві́ру в се́рдці, а не в ра́зумі, даби́ того́ распозна́ти, призива́яй.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 11","ps":["Подви́жниче ди́вний, тебі́ Госпо́дь, смире́нния вознося́й, сицеви́ми дарми́ обогати́, я́коже гости́вшим в ке́ллії твоє́й се́рдце умиля́шеся созна́нієм гріхо́в свої́х. Імі́л бо єси́ ти власть удаля́ти із ми́слей вся зла́я і оставля́ти то́кмо я́же к Ца́рствію Небе́сному поле́зная. То́ю си́лою Госпо́днею в тебі́ ді́йствующею ізумле́ни би́вше, рцем Го́споду, ди́вному во святи́х Свої́х: Аллилу́я."]},{"h":"Ікос 11","ps":["Мно́гія ісціли́л єси́ ти, о́тче, явля́я їм по́мисли і та́йная душі́ їх. По моли́тві твоє́й дождь ве́лій а́біє преста́, єгда́ поко́йнаго погреба́ти надлежа́ше. Ти же посту́ і бді́нію приліжа́, юро́дством скрива́л єси́ да́ри своя́ і сія́ніє душі́ своєя́. Ни́ні же, покланя́ющеся іко́ні твоє́й і от тебе́ по́мощі прося́ще, взива́єм си́це:","Ра́дуйся, дарова́ньми свої́ми мі́ру сме́ртних превозше́дий;","ра́дуйся, я́ко бесі́дою своє́ю глубо́коє раска́яніє дарова́вий.","Ра́дуйся, в созерца́нії во іні́м монастирі́ гости́вий і та́мо би́вшая пове́давий;","ра́дуйся, младе́нця во утро́бі ма́терні сло́во Бо́жиє слу́шати благослови́вий.","Ра́дуйся, єму́же Госпо́дь даде́ прозрі́ти глубини́ душ челові́чеських;","ра́дуйся, я́ко апо́стол любве́, на пе́рсіх Госпо́дніх возлежа́й.","Ра́дуйся, я́ко тому́ подо́бні, тебі́ Госпо́дь безві́стная і та́йная Своя́ яви́л єсть;","ра́дуйся, я́ко бу́єє Бо́жиє прему́дріє челові́к би́ти свиде́тельствовавий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 12","ps":["Послі́дніх време́н подви́жниче, поуча́л єси́ ти па́ству твою́, я́ко ни́ні Бог взиску́єть от нас любве́, я́же ізся́че от беззако́ній мно́гих, то́кмо бо любо́вію смо́жеть челові́к устоя́ти во ві́рі пред кончи́ною ві́ка. І я́ко тоя́ ді́латель і учи́тель, ни́ні с ли́ки безпло́тних прино́сиши Пресвяті́й Тро́йце блаже́нную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Поуча́л єси́, о́тче святи́й, я́ко в любві́ єсть соу́з соверше́нств, і сія́ єсть коне́чноє обоже́ніє. Посему́ і враг челові́чеський супроти́в нея́ подима́єть найви́шшую брань, зіло́ скорб'я́ о ней. Сего́ ра́ди всему́ предпочита́ти подоба́єть діла́ любве́, поне́же без діл мертва́ єсть. Ми же, ка́плю тоя́ наслі́довати хотя́ще, поє́м ті:","Ра́дуйся, п'яти́ му́дрим ді́вам уподо́бивийся;","ра́дуйся, сотвори́вий і научи́вий.","Ра́дуйся, му́дрий любве́ ді́лателю і к ді́ланію призива́яй;","ра́дуйся, любо́в я́ко по́двиг, на́шему вре́мені да́нний, нариця́яй.","Ра́дуйся, є́же той научи́ти, своє́ю забо́тою пе́рвейшею полага́яй;","ра́дуйся, я́ко проше́ніє о ми́лостині а́ки ми́лость Бо́жию вміня́ти назида́яй.","Ра́дуйся, любве́ служи́телю і рачи́телю, сія́ бо єсть Сам Госпо́дь;","ра́дуйся, я́ко без Христа́ вся нічто́же суть, запові́давий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 13","ps":["О,блаже́нний о́тче, подви́жниче і іспові́дниче, ві́рний Христо́в служи́телю, все житіє́ своє́ Тому́ усокро́виществовавий і по кончи́ні своє́й в Нем сокро́вище своє́ обріти́й, я́коже сам предре́кл єси́. Ни́ні со а́нгели і со всі́ми святи́ми предстоя́ Престо́лу Госпо́дню, помоли́ся о нас, ма́ма Габріє́ли, с мольбо́ю к тебі́ прибіга́ющих, умоли́ милосе́рдаго Влади́ку, да і в на́ша ізсо́хшая го́рдостію сердца́ проліє́ться ка́пля твоєго́ блаже́ннаго упова́нія, ві́ри і любве́. Да поє́м с тобо́ю: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Єва́нгеліє обрі́т, я́коже сокро́вище, на селі́ сокри́тоє, с ра́достію вся расточи́л єси́, да Христа́ приобря́щеши, і я́коже ку́плений раб во виногра́ді Госпо́днем нелі́ностно ді́лал єси́. І ми тебі́ поє́м:","Ра́дуйся, ді́лателю пе́рваго часа́;","ра́дуйся, я́ко раба́, нічесо́же сотво́рша, себі́ вміня́яй.","Ра́дуйся, я́ко апо́стол Андре́й, на зов Христо́в не заме́дливий;","ра́дуйся, я́ко Петр, горя́чим се́рдцем єго́ приє́мий.","Ра́дуйся, от Него́ нічто́же себі́ утаї́вий;","ра́дуйся, я́ко ле́пті вдови́чі все житіє́ своє́ в дар Бо́гу вве́ргнувий.","Ра́дуйся, до́брая земле́, на не́йже сі́м'я прозябе́ і припло́дова;","ра́дуйся, тала́нти, от Бо́га да́нния, мно́гажди возрасти́вий.","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Кондак 1","ps":["Му́дрости ві́ка сего́ юро́дство креста́ Христо́ва предпоче́т, вся ми́ра сла́дкая і льсти́вная я́коже ізгре́біє пе́щноє вміни́л єси́, о́тче Гавриї́ле. І крест свой взем, єди́ному Христу́ послі́довал єси́ ізді́тська і до послі́дняго іздиха́нія. І та́ко вшел єси́ в Небе́сния Оби́телі, іді́же ни́ні предстоя́ своєму́ Влади́ці, мо́лиши о нас, пою́щих ті:","Ра́дуйся, блаже́нне Гавриї́ле, любо́в свою́ в науче́ніє нам оста́вивий."]},{"h":"Молитва","ps":["О́тче святи́й, блаже́нне Гавриї́ле, преподо́бним дре́внім подо́бниче і тве́рдий іспові́дниче, с ма́лих літ словеса́ Госпо́дня восприя́вий і тім ре́вностно послі́довавий! Се ми, раби́ ліни́вії і лука́вії тебі́ предстої́м с моли́твою, не імі́юще ні подвиго́в твої́х, ніже́ смире́нія, но себе́ на всяк день в душі́ хва́ляще і велича́юще, єще́ же і враго́во вовні́ себі́ і́щуще! Не і́мами пред Бо́гом чем оправди́тися! Но моли́ за нас, о́тче, да пода́сть нам Госпо́дь си́ли сло́во Своє́ разумі́ти і ісполня́ти, я́коже тебі́ от младе́нства откри́. Да бу́дем ми, себі́ христия́ни імену́юще, не то́кмо сли́шателіє рассе́яннії, но і ісполни́теліє. Да уразумі́єм лице́ битія́ своєго́, я́ко нічесо́же мо́жем кромі́ по́мощі Бо́жия. І да взи́щем тоя́ і да возлю́бим Єго́, і да приліпі́мся к Нему́ все́ю душе́ю своє́ю, всім се́рдцем свої́м, всім помишле́нієм свої́м, і да бу́деть се́рдце на́ше, по сло́ву твоєму́, пре́данним Го́споду. І да пода́сть нам зало́г спасе́нія в ду́ші на́ша, ра́дость, мир і любо́во в сердця́ на́ша, примире́ніє во всіх нестроє́ніїх на́ших, утіше́ніє во всіх ско́рбіх на́ших, не от діл на́ших, но моли́твами твої́ми, по неізрече́нній ми́лості Своє́й, Єму́же сла́ва і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Я́коже Влади́ка Христо́с сла́ву Свою́ неізглаго́ланную / сокри́, пло́тію оді́явся, / та́коже і ти юро́дства вре́тищем покри́л єси́ / світ Фаво́рский і́мже Тя Госпо́дь осі́я / я́ко іспові́дника і страда́льця, / і па́стир душ яви́лся єси́, / о́тче преподо́бне Гавриї́ле, // моли́ Христа́ Бо́га поми́ловати ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Непости́жима єсть ми́лость Бо́жия, / Єго́же благода́тію созда́ніє обоже́но лицезрі́єм всі, / ти бо, преподо́бне о́тче, / о́браз Творця́ в себі́ утверди́л єси́, / возне́сши єстество́ своє́ в подо́біє Бо́жиє, / ті́мже сла́вим тя, о́тче Гавриї́ле, досто́йні похвали́, / я́ко бил єси́ на землі́ гла́сом пра́вди і го́лубем чистоти́, / жи́тельствовавши же в чу́дном смире́нії, / звені́л єси́ ли́рою му́дрості і любві́ орга́ном, / ни́ні же на небесі́х предста́тельствуєши о спасе́нії на́шем, // хода́таю Бо́жия благода́ті."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Гавриї́ле, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святим праведним Марфі і Марії, сестрам праведного Лазаря","e":"Akathist to the Holy Righteous Martha and Mary, sisters of the Righteous Lazarus","secs":[{"h":"Кондак 1","ps":["Ізбра́нния от Бо́га служительници но́вия благода́ті, пра́веднаго Ла́заря боголюби́вия сестри́, Ма́рфо і Марі́є, ви дія́нієм і разумі́нієм во ві́рі і любві́ Христу́ послі́довали єсте́ і ни́ні с ли́ки святи́х жен пребива́єте, наслажда́ющеся ра́йських красо́т і весе́лія. Ті́мже, я́ко іму́щия дерзнове́ніє ко Го́споду, Того́ прилі́жно молі́те от бід і скорбе́й і паде́ній гріхо́вних ізба́вити нас, да ва́ми научи́вшеся угожда́ти Христу́ Бо́гу, не преста́нем со умиле́нієм взива́ти Єму́: Аллилу́я."]},{"h":"Ікос 1","ps":["А́нгелов і челові́к Цар і Госпо́дь, добро́ту душ ва́ших прови́дів і до конця́ вас возлюби́в, во дні земно́й жи́зні Своєя́ благослове́нний дом ваш посещаше і бра́та ва́шего Ла́заря от ме́ртвих воскреси́. Ми же грі́шнії, таково́є человіколю́бноє снисхожде́ніє Єго́ воспомина́юще, во умиле́нії серде́ць на́ших вопіє́м вам та́ко:","Ра́дуйтеся, всім се́рдцем, все́ю душе́ю і все́ю ми́слію ва́шею Бо́га возлюбившия;","ра́дуйтеся, любо́во ва́шу не сло́вом іли́ язи́ком, но ді́лом і і́стиною яви́вшия.","Ра́дуйтеся, любо́вію ві́ру во Христа́ Си́на Бо́жия от Отця́ Небе́снаго снискавшия;","ра́дуйтеся, ві́рою, послуша́нієм, діла́ми любве́ і милосе́рдія Єму́ послужившия.","Ра́дуйтеся, тім Ца́рствіє Небе́сноє наследовавшия;","ра́дуйтеся, дів непоро́чних і жен цілому́дренних похвало́ і украше́ніє.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 2","ps":["Ві́дяще, пра́ведния жени́, я́ко Госпо́дь, не іми́й гді глави́ подклони́ти, при́йдеть к вам, потщалися єсте́ в до́му ва́шем Єго́, я́ко Боже́ственнаго Учи́теля, с ві́рою і любо́вію послу́шати і со усе́рдієм мно́гим послужи́ти Єму́. Ті́мже науча́єте і нас Єму́, я́ко Бо́гу, нас ра́ди воплоти́вшемуся, нелі́ностно служи́ти і благогові́йно воспіва́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Науча́я нас і страннолю́бія не оставля́ти, і о сло́ві Бо́жиєм усе́рдно приліжа́ти, не о хлі́бі бо єди́ном жив бу́деть челові́к, но о вся́ком сло́ве Бо́жиєм, Госпо́дь і Учи́тель наш і слу́жби Ма́рфи трудолюбния не отве́рже, і Марі́їно сіді́ніє у ног Єго́ попремно́гу ублажи́. Ті́мже і ми боголюби́вій дво́їце о́ной воспої́м:","Ра́дуйся, Ма́рфо, Христа́, нас ра́ди воплоти́вшагося, в до́му твоє́м прия́вшая;","ра́дуйся, в служе́нії твоє́м на потре́бу пло́ті Єго́ не отверженная.","Ра́дуйся, і нас діла́ми милосе́рдія служи́ти Єму́ науча́ющая;","ра́дуйся, Марі́є, у ног Ісу́сових сло́вом уст Єго́ насищавшаяся.","Ра́дуйся, єди́ноє на потре́бу, я́ко благу́ю часть, ізбра́вшая;","ра́дуйся, ре́вности ра́ди о сли́шанії слове́с Госпо́дніх со блаже́нними Їм сопричте́нная.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною укріпля́ємі, уни́нієм не уязви́лися єсте́, єгда́ узрі́ли бра́та ва́шего болі́знію лю́тою істощаєма, но к Ціли́телю неду́гов, Го́споду Ісу́су, со упова́нієм послали єсте́, глаго́люще: Го́споди, єго́же лю́биши, боли́ть. Сим послі́дующе, і ми во вся́ком обстоя́нії уни́нію да не предадимся, со упова́нієм Христу́ Бо́гу вопію́ще: Аллилу́я."]},{"h":"Ікос 3","ps":["Любля́ше Ісу́с Ма́рфу і сестру́ єя́ і Ла́заря і, ві́ру їх в гряду́щеє Ца́рствіє жи́зні ві́чния іспиту́я і утвержда́я, рече́: сія́ болі́знь ність к сме́рті, но к сла́ві Бо́жієй, да просла́виться Син Бо́жий єя́ ра́ди. Ви же, о боголюби́вия сестри́, і пред лице́м сме́рті бра́та ва́шего ві́рою і любо́вію ко Христу́ ду́хом горя́ще, в Боже́ственній си́лі Єго́ не усомнилися єсте́. Сего́ ра́ди приймі́те от нас похвале́нія такова́я:","Ра́дуйтеся, во уни́ніє безнадежноє во обстоя́нії і ско́рби не впадшия;","ра́дуйтеся, обремене́нних скорбми́ жите́йськими тім ободряющия.","Ра́дуйтеся, в печа́лі ва́шей ко Врачу́ душ і тіле́с, Го́споду Ісу́су, со смире́нним упова́нієм по́мисли своя́ обратившия;","ра́дуйтеся, лиця́ Єго́ не ви́дяще, во благо́й покорности Єму́ пребившия.","Ра́дуйтеся, во іспита́нії сем ві́ру крі́пку, я́ко Авраа́мову, яви́вшия;","ра́дуйтеся, в злострада́ніях терпі́ніє тве́рдоє, я́ко І́ов, показавшия.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 4","ps":["Ві́дая, я́же хо́щеть сотвори́ти, Всемогу́щий Госпо́дь і Спас наш, рече́ ученико́м Свої́м: Ла́зар, друг наш, у́спе, но іду́, да возбужу́ єго́; науча́я всіх во сві́ті лиця́ Бо́жия ходи́ти і Пода́телю жи́зні воспіва́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Мно́гії от іуде́й прийдо́ша к Ма́рфі і Марі́ї, да уті́шать їх о Ла́зарі, бра́те їх. Сестри́ же, отбіга́я їх, я́ко не іму́щих о Христі́ Ісу́се упова́нія. Ма́рфа к Єди́ному Уті́шителю стопи́ своя́ с ра́достію напра́ви, єгда́ Той Вифа́нії дости́же. Такову́ю крі́пкую любо́в сесте́р Ла́заревих ко Христу́ і ві́ру їх зря́ще, ра́достними гла́си воспої́м їм такова́я:","Ра́дуйтеся, добро́тою душ ва́ших неві́рних іуде́єв окамене́нния се́рдця покори́ти возмогшия;","ра́дуйтеся, не су́єтному уни́нію, но Бо́жию благоволе́нію себ'я́ предавшия.","Ра́дуйтеся, на єди́ную бла́гость Христо́ву в печа́лі ва́шей наде́жду возложившия;","ра́дуйтеся, в срі́теніє Єго́ со тща́нієм стопи́ ва́ша направившия.","Ра́дуйтеся, во упова́нії ва́шем от Могу́щаго спасти́ оправданния;","ра́дуйтеся, утіше́нія в ско́рбіх не от люде́й, но от Бо́га іска́ти нас научающия.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 5","ps":["Ма́рфа блаже́нная, єгда́ срі́те Го́спода, утіше́нія от Него́ і́щущи, рече́: Го́споди, а́ще би Ти зді бил, не у́мерл би брат мой. Но і ни́ні вім, я́ко єли́ка а́ще попро́сиши от Бо́га, дасть Тебі́ Бог. Єму́же от всея́ душі́ на́шея і ми вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Боже́ственноє Своє́ смотре́ніє о на́шем спасе́нії показу́я, Госпо́дь Ісу́с, я́ко жи́зні і сме́рті Влади́ка, благоволи́ рещи́ тебі́, блаже́нная Ма́рфо: воскре́снеть брат твой. І па́ки: ві́руяй в М'я, а́ще і у́мреть, оживе́ть. Ві́риши ли сему́? - вопроси́ тя. Ти же отвіща́ Єму́: єй, Го́споди, ві́рую, я́ко Ти Христо́с Син Бо́жий, гряду́щий в мир. Сего́ ра́ди, ві́рі во Христа́ Си́на Бо́жия тобо́ю научаємії, восхваля́єм тя си́це:","Ра́дуйся, блаже́нная Ма́рфо, обітова́ніє о воскресе́нії бра́та твоєго́ от Самаго́ Жизнода́вця услишавшая;","ра́дуйся, я́ко вопрошенная от Него́ о ві́рі твоє́й, не пло́ті і кро́ві, но гла́са Отця́ Небе́снаго послушавшая.","Ра́дуйся, я́ко от Него́ науче́нная, Христа́ Си́на Бо́жия тве́рдо іспові́дала єси́;","ра́дуйся, я́ко тім ка́мень ві́ри, на не́мже созда́ Госпо́дь Це́рков Свою́, яви́вшая.","Ра́дуйся, во іспові́данії твоє́м Петру́, первоверхо́вному апо́столу, уподо́бившаяся;","ра́дуйся, равноапо́стольнаго ублаженія воі́стину досто́йная.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 6","ps":["Тро́сти надломленния не преломля́яй, Человіколю́бець Госпо́дь, єгда́ ви́ді Марі́ю і прише́дшия с ней іуде́ї плачущия, я́коже любля́ше Ла́заря, прослези́ся Сам. Да і ми немощні́ї, в ско́рбіх су́ще, бестрепетно к Нему́ со слеза́ми притека́єм, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Воі́стину благослове́н о бра́ті твоє́м плач твой, Марі́є, єго́же ви́дя, прослези́ся Ісу́с. Сего́ ра́ди со умиле́нієм ублажа́єм тя си́це:","Ра́дуйся, боголюби́вая Марі́є, в серафимстей любві́ твоє́й ко Го́споду і к сро́дникам любве́ своєя́ не угаси́вшая;","ра́дуйся, пла́чем твої́м о Ла́зарі нас, во окамене́нії серде́чнім пребива́ющих, обличи́вшая.","Ра́дуйся, Христа́ Бо́га сле́зи о па́дшем созда́нії Своє́м істочи́ти подвигшая;","ра́дуйся, в слеза́х Го́спода Ісу́са, не́мощем на́шим состра́ждуща, єле́й утіше́нія всім пла́чущим і болезнующим показа́вшая.","Ра́дуйся, і сама́ в ско́рбіх на́ших сострада́ти нам могу́щая;","ра́дуйся, с сестро́ю твоє́ю Ма́рфою милосе́рдія сестра́м первоначальниця богоуго́дная.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 7","ps":["Всеві́дий по Божеству́ Своєму́, челові́чеськоє єстество́ показу́юще, о Ла́зарі вопроша́л єси́, Го́споди Ісу́се: гді положи́сте єго́. І ка́мень от гро́ба взя́ти повелі́л єси́, да возсмерденієм сме́рті заградя́ться неві́рних уста́. Ми же, ві́рнії, со дерзнове́нієм Тебі́, побіди́ти смерть прише́дшему, вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Не́мощ єстества́ челові́чеськаго явля́ющи, сестра́ уме́ршаго, Ма́рфа, глаго́ла Ісу́су: Го́споди, уже́ смерди́ть: четверодне́вен бо єсть. Марі́я же, зря́ще ка́мень отвале́н от гро́ба, в молча́нії пребива́ше. Сему́ Марі́їну молча́нію со умиле́нієм внима́юще, с Ма́рфою же малові́ріє своє́ Го́споду дерзнове́нно іспові́дующе, воззове́м к ним такова́я:","Ра́дуйся, Марі́є, я́ко ко гро́бу смердя́щаго в претрепетном молча́нії за Христо́м прише́дшая;","ра́дуйся, я́ко сим всіх нас в послуша́ніє ві́ри ра́зум покоря́ти научи́вшая.","Ра́дуйся, Ма́рфо, я́ко не́мощ ві́ри на́шея превозмога́ти науча́ющая;","ра́дуйся, я́ко всім нам: єй, Го́споди, ві́рую, я́ко Ти Христо́с, Син Бо́жий, глаго́лати указавшая.","Ра́дуйтеся, блаже́нния сестри́, в не́мощіх душ і тіле́с ва́ших от Христа́ не отступившия і Єму́ любо́вію последовавшия;","ра́дуйтеся, на висоту́ благода́тнаго разумі́нія Сами́м Всеведцем возведенния.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 8","ps":["Сла́ву Свою́, я́ко Єдиноро́днаго от Отця́, всім ві́рним явля́я, хвалу́ Отцю́ Своєму́ возда́в, Ісу́с гла́сом вели́ким воззва́: Ла́заре, гряди́ вон. І бездиха́нний, Даю́щаго диха́ніє послу́шав, от сме́рти восста і от гро́ба ізи́де; да чу́до сіє́ зря́ще, ку́пно і ми с ним Побіди́телю сме́рти воспої́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Чу́до ве́ліє і стра́шноє сотвори́ Христо́с Бог наш, Ла́заря четверодне́внаго от ме́ртвих воздви́гнув. Да і нас всіх ві́ру в Него́, я́ко Си́на Бо́жия, утверди́ть, бессмертіє душі́ і о́бщеє всіх воскресе́ніє увіря́я. Ми же, боже́ственноє поклоне́ніє Сотво́ршему сіє́ воздаю́ще, ублажи́м сестри́ воскрешеннаго Їм і воззове́м к ним сицева́я:","Ра́дуйтеся, пра́веднаго Ла́заря сестри́, Христа́ нелицемі́рні возлюбившия;","ра́дуйтеся, Христо́м за ві́рность ва́шу возлю́бленния.","Ра́дуйтеся, о́бщеє воскресе́ніє пре́жде страсте́й Христо́вих во ві́рі узревшия;","ра́дуйтеся, ві́рою ва́шею і на́шу ві́ру укрепляющия.","Ра́дуйтеся, ученици́ Христо́ви достославния;","ра́дуйтеся, ли́ка апо́стольськаго і́стинния прича́стници.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 9","ps":["Си́ни тьми, зря уме́ршаго і гла́сом Бо́жиїм от тлі́нія восставшаго, в ожесточенії серде́ць не ві́роваша Христу́ да́же до сего́ дне, во осліпле́нії су́ще. Ми же, сих безу́мію не прилагающеся, но в о́бщеє воскресе́ніє по гла́су Си́на Бо́жия ві́рующе, Єму́, я́ко Жизнода́вцю, велегла́сно і вседу́шно возопії́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Пресла́вная і стра́шная во Вифа́нії сотвори́в, Ісу́с, пре́жде шести́ дній Па́схи, па́ки при́йде во весь сію́. І сотвори́ша Єму́ ве́черю, і бі Ла́зар єди́н от возлежа́щих с Ним. Ви же, присноблаже́нния сестри́, Пода́телю вся́чеських благода́рні су́ще, Ма́рфа служа́ше Єму́ всеусе́рдні, Марі́я же ми́ро на но́зі Єго́ возлія́. Сего́ ра́ди, в ра́дость ва́шу вни́ти жела́юще, і ми со умиле́нієм зове́м вам:","Ра́дуйтеся, богому́дрия жени́, хвали́ і благодаре́нія благоді́ющему Го́споду преісполненния;","ра́дуйся, Ма́рфо трудолю́бная, се уже́ други́й раз на ве́чері Го́споду послужи́вшая.","Ра́дуйся, в благодарнем служе́нії сем Господом ми́лостивно прия́тая;","ра́дуйся, Марі́є, Сладча́йшему Ісу́су но́зі ми́ром многоці́нним пома́завшая.","Ра́дуйся, во обличе́ніє Іу́диних злохуленій похвале́нія Ісу́сова сподо́бившаяся;","ра́дуйся, я́ко многоці́ннаго ми́ра на но́зі Христо́ви возлія́нієм і нас благолі́піє до́му Бо́жия люби́ти і о том приліжа́ти поуча́єши.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 10","ps":["Ма́рфі і Марі́ї, ві́рнії, подража́юще, ки́йждо во своє́м чи́ну, ко Христу́ Спа́су припаде́м і, прося́ще от Того́ ісціле́нія не́мощей на́ших і от сна гріхо́внаго воскреше́нія, благода́рними усти́ воспої́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Ві́рнії до конця́ во служе́нії ва́шем Христу́ во днех пло́ті Єго́ пребившия і самови́дці страсте́й Єго́ би́ти сподобившіяся, к погребе́нію Воскресителя Ла́зарева, сла́вния Ма́рфо і Марі́є, посреді́ мироно́сиць яви́лися. С ни́ми предстоя́ще ни́ні престо́лу сла́ви Бо́жия, моли́твами ва́шими к песнопенному тіх ли́ку совокупі́те і нас, ва́ші по́двиги прославля́ющих:","Ра́дуйся, Ма́рфо, в твоє́м Христу́ многопопечительном служе́нії, я́коже і во іспові́данії, поревновавшая;","ра́дуйся, странноприїмницям і милосе́рдія сестра́м подвигоположниця.","Ра́дуйся, Марі́є, возлю́бленному ученику́ Христо́ву Іоа́нну в пламенной любві́ к Тому́ уподо́бившаяся;","ра́дуйся, непоро́чних дів, Христу́ в житії́ своє́м уневі́стившихся, руководи́тельниця нело́жная.","Ра́дуйтеся, боголюби́вия сестри́, і ді́ятельним житіє́м, і внима́нієм серде́чним послі́дованія Христу́ ревнительници ізря́дния;","ра́дуйтеся, на обої́х сих путях угожде́нія Го́споду жи́ти бра́тії вку́пі му́дре нас научающия.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 11","ps":["Кий глаго́л довлі́єть по достоя́нію воспі́ти Воскресе́нія Христо́ва ра́дость всеми́рную, єя́же ви, со про́чими жена́ми мироно́сицями, в сей ве́лій і святи́й день причасти́лися єсте́; ті́мже і ми, Воскресе́нія Христо́ва вели́чіє боголі́пноє сла́в'яще, пої́м Христу́: Аллилу́я."]},{"h":"Ікос 11","ps":["Вся́коє іскуше́ніє прейти́ моля́щися і живо́т ві́чний улучи́ти хотя́щи, я́ко ві́рния ученици́ Христо́ви, ка́яждо во своє́м путі́, оба́че єди́ним ду́хом ві́ри і любве́ Єму́ порабо́тали єсте́, отону́дуже і ра́достей во Ца́рствії Єго́ сподо́билися єсте́. Сего́ ра́ди, труди́ і по́двиги ва́ша воспомина́юще і сла́ві ва́шей во Ца́рствії Христо́вом ра́дующеся, воспіва́єм вам такова́я:","Ра́дуйтеся, ві́рния ученици́ Христо́ви, не челові́ком, но Бо́гу в житії́ ва́шем угодившия;","ра́дуйтеся, нището́ю духо́вною Ца́рствіє Небе́сноє стяжавшия.","Ра́дуйтеся, ду́хом кро́тости зе́млю обітова́нія наследовавшия;","ра́дуйтеся, милосе́рдія діла́ми ми́лостей от Го́спода во Ца́рствії Єго́ сподобившіяся.","Ра́дуйтеся, се́рдцем чи́стим Бо́га Сло́ва зрящия;","ра́дуйтеся, іспові́дниці ві́ри Христо́ви, мзду мно́гу на небесі́х приявшия.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 12","ps":["Благода́тію Всеми́лостиваго Бо́га прия́ли дерзнове́ніє ве́ліє к Нему́, о блаже́нния сестри́. Моле́нія ва́ша і проше́нія о нас грі́шних к престо́лу сла́ви Єго́ вознесі́те, да спаса́ємі предста́тельством ва́шим, Воскре́сшему і вся с Собо́ю воскреси́вшему а́нгельськую піснь воспої́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ни́ні со всі́ми небе́сними си́лами трисвяту́ю піснь ди́вному во святи́х Свої́х Бо́гу, о преблаже́нния сестри́ Ла́зареви, при́зріте с висоти́ небе́сния на нас грі́шних, волна́ми мо́ря жите́йськаго обурева́ємих, ти́хаго приста́нища жа́ждущих і вас си́це любо́вію велича́ющих:","Ра́дуйтеся, на небесі́ во сла́ві со а́нгели і всі́ми святи́ми царствующия;","ра́дуйтеся, і на землі́ в Це́ркві Христо́вой пі́сненно прославляємия.","Ра́дуйтеся, я́ко зві́зди небе́сния во тьмі ві́ка сего́ доброді́тельми ва́шими сіяющия;","ра́дуйтеся, Бо́гом да́нния нам в житії́ на́шем наста́вници.","Ра́дуйтеся, милосе́рдія служе́нієм Христу́ первонача́льници;","ра́дуйтеся, те́плия о нас к Бо́гу моли́твенниці.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 13","ps":["О преди́вная боголюби́вая дво́їце, ві́рния ученици́ Христо́ви, Ма́рфо і Марі́є пресла́вния, огнь любве́ і ві́ри в душа́х ва́ших возжегшия і сих ра́ди в Ца́рство сла́ви си́лою Воскре́сшаго вше́дшия, іспросі́те нам у Христа́ Бо́га на́шего по́мощі путьми́ ва́шими зді на землі́ жи́тельствовати, да во оби́телі Отця́ Небе́снаго всели́вшеся, ку́пно с ва́ми і всі́ми святи́ми і ми на престо́лі сла́ви Сідя́щему воспої́м а́нгельськую піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і челові́к Цар і Госпо́дь, добро́ту душ ва́ших прови́дів і до конця́ вас возлюби́в, во дні земно́й жи́зні Своєя́ благослове́нний дом ваш посещаше і бра́та ва́шего Ла́заря от ме́ртвих воскреси́. Ми же грі́шнії, таково́є человіколю́бноє снисхожде́ніє Єго́ воспомина́юще, во умиле́нії серде́ць на́ших вопіє́м вам та́ко:","Ра́дуйтеся, всім се́рдцем, все́ю душе́ю і все́ю ми́слію ва́шею Бо́га возлюбившия;","ра́дуйтеся, любо́во ва́шу не сло́вом іли́ язи́ком, но ді́лом і і́стиною яви́вшия.","Ра́дуйтеся, любо́вію ві́ру во Христа́ Си́на Бо́жия от Отця́ Небе́снаго снискавшия;","ра́дуйтеся, ві́рою, послуша́нієм, діла́ми любве́ і милосе́рдія Єму́ послужившия.","Ра́дуйтеся, тім Ца́рствіє Небе́сноє наследовавшия;","ра́дуйтеся, дів непоро́чних і жен цілому́дренних похвало́ і украше́ніє.","Ра́дуйтеся, Ма́рфо і Марі́є, о́браз ві́ри і любве́ нам показу́ющия."]},{"h":"Кондак 1","ps":["Ізбра́нния от Бо́га служительници но́вия благода́ті, пра́веднаго Ла́заря боголюби́вия сестри́, Ма́рфо і Марі́є, ви дія́нієм і разумі́нієм во ві́рі і любві́ Христу́ послі́довали єсте́ і ни́ні с ли́ки святи́х жен пребива́єте, наслажда́ющеся ра́йських красо́т і весе́лія. Ті́мже, я́ко іму́щия дерзнове́ніє ко Го́споду, Того́ прилі́жно молі́те от бід і скорбе́й і паде́ній гріхо́вних ізба́вити нас, да ва́ми научи́вшеся угожда́ти Христу́ Бо́гу, не преста́нем со умиле́нієм взива́ти Єму́: Аллилу́я."]},{"h":"Молитва","ps":["О святи́я і всехва́льния ученици́ Христо́ви, Боголюби́вия Ма́рфо і Марі́є! Умолі́те возлю́бленнаго ва́ми і вас возлюби́вшаго Сладча́йшаго Ісу́са, Єго́же ви іспові́дали єсте́, Христа́, Си́на Бо́жия, да дасть і нам грі́шним, гріхо́в, оставле́ніє, во ві́рі пра́вой нелицемі́рноє і тве́рдоє стоя́ніє. Вселі́те в се́рдця на́ша дух стра́ха Бо́жия, смире́ннаго на Бо́га упова́нія, терпі́нія і к бли́жнім милосе́рдія. Ізба́віте нас моли́твами ва́шими от іскуше́ній жите́йських, бід і напа́стей, да ти́хоє і ми́рноє житіє́ пожи́вше зді, с по́мисли непоро́чними і се́рдцем чи́стим, с дерзнове́нієм ві́ри і упова́нія предста́нем на о́ний Стра́шний Суд і, до́брий отві́т на нем возда́вше, ра́дости ві́чния в Ца́рствії Небе́снім сподо́бимся. Амі́нь."]},{"h":"Молитва друга","ps":["О блаже́нния і святи́я жени́, ві́рою і любо́вію Христу́ Бо́гу последовавшия і во оби́телі Отця́ Небе́снаго всели́вшіяся! К вам ни́ні аз, грі́шная, (і́м'ярік) прибіга́ю і смире́нно молю́: научі́те м'я і помозі́те мі ходи́ти пред Бо́гом путьми́ ва́шими непреткнове́нно і ві́чную ку́пно с ва́ми жизнь наслі́довати.","О Ма́рфо пра́ведная, тве́рдим іспові́данієм ві́ри твоєя́ Христу́ угоди́вшая, укріпи́ сла́бую ві́ру мою́. О слу́жбі Го́споду і бра́тіям нелицемі́рні і всеусе́рдні прилежа́вшая, помози́ і мні служе́ніє моє́ безро́потні і вседуше́вні проходи́ти. Сестру́ твою́ іногда́, в ско́рбі су́щу, ко Христу́ воззвала́ єси́, отая ре́кши: Учи́тель прише́л єсть і глаша́єть тя. Ни́ні у́бо предста́ни мні в тру́дний час іспита́нія ві́ри і любве́ моєя́ і в глубині́ се́рдця возвісти́ мі, я́ко Госпо́дь Ісу́с незри́мо гряде́ть, да путе́м іспита́ній привлече́ть м'я к Себі́! Іспроси́ мні, о ма́ти свята́я, у Го́спода на́шего си́лу і крі́пость, да воста́вши ско́ро, притеку́ к Нему́, поклоню́ся Єму́ і в смире́нній любві́ Єго́ мир і спасе́ніє душі́ моє́й обря́щу.","І ти, о Боголюби́вая Марі́є, у но́гу Ісу́сову єди́ноє на потре́бу обрі́тшая, помоли́ся Єму́ благу́ю часть спаса́ємих і мні, грі́шній, улучи́ти. Ми́ро благово́нноє в дар благодаре́нія Христу́ Жизнода́вцю прине́сшая, умоли́ ни́ні Єго́ і душі́ моє́й пода́ти ми́ро моли́тви і покая́нія сле́зи, чистоти́ і до́брих діл благоуха́ніє, та́ко да во обновле́нноє всі́ми си́ми се́рдце моє́ Госпо́дь при́йдеть і оби́тель Себі́ сотвори́ть.","К вам, о святи́я пра́ведния жени́, Ма́рфо і Марі́є, припа́даю і смире́нно молю́: не оста́віте м'я в дні тя́жких іспита́ній, да не соблазню́ся тлі́нними і кра́сними ми́ра сего́, найпа́че же в час го́ркий разлуче́нія душі́ моєя́ с ті́лом, предста́ніте мні і о́бщаго Влади́ку на́шего умолі́те, да при́зрить на м'я во оскуді́нії сил мої́х ми́лостивним о́ком і, прости́во вся прегріше́нія моя́, возста́вить м'я к жи́зні несконча́ємій во блаже́нних оби́теліх Отця́ Небе́снаго. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Пра́веднаго Ла́заря Боголюби́вия сестри́, Ма́рфо і Марі́є пресла́вния, чи́стим се́рдцем Христа́ в житії́ ва́шем возлюби́ли єсте́, мироно́сиць взе́мши чин, і Єго́, я́ко Си́на Бо́жия, безбоя́зненно іспові́дали єсте́, сего́ ра́ди ни́ні во оби́теліх Отця́ Небе́снаго со А́нгели і всі́ми святи́ми сла́вно ца́рствуєте. Умолі́те, Єго́же возлюби́ли єсте́, і нам, грі́шним, во ві́рі і любві́ Христо́вой утверди́тися і Ца́рствія Небе́снаго сподо́битися."]},{"h":"Величання","ps":["Ублажа́єм вас, / святи́я пра́ведния Ма́рфо і Марі́є, / і чтим святу́ю па́м'ять ва́шу, / ви бо мо́лите о нас // Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Трифону, В’ятському чудотворцю","e":"Akathist to our Venerable Father Tryphon of Vyatka, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і чудотво́рче, преподо́бне о́тче Три́фоне, свя́тостію житія́ і чудеси́ твої́ми возсія́вий страні́ В'ятстей, я́ко звізда́ богосві́тлая! Похва́льная воспису́єм ті, любо́вію творя́щії всечестну́ю па́м'ять твою́: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела тя во пло́ті су́ща позна́вше, преподо́бне, і ве́лія благодія́нія от тебе́ приє́мше, я́ко чудотво́рця пресла́внаго тя сла́вим і си́це тебі́ со умиле́нієм зове́м:","Ра́дуйся, сі́верния страни́ благоуха́нний кри́не.","Ра́дуйся, о́трасле благочести́ваго ко́рене.","Ра́дуйся, от мла́дости в добро́м наказа́нії воспита́нний.","Ра́дуйся, ізді́тська сопричтенний в синовство́ Отцю́ Небе́сному.","Ра́дуйся, благочести́вия ма́тере твоєя́ отра́до і утіше́ніє.","Ра́дуйся, бра́тію і сро́дники твоя́ свої́м благоче́стієм удиви́вий.","Ра́дуйся, целому́дріє ді́вства невреди́мо сохрани́вий.","Ра́дуйся, от се́рдця твоєго́ вся іскуше́нія ю́ности отгна́вий.","Ра́дуйся, к Бо́гу імі́вий раче́ніє ве́ліє.","Ра́дуйся, Го́спода ра́ди путь ті́сний і ско́рбний ізбра́вий.","Ра́дуйся, до́льняя го́рняго ра́ди оста́вивий.","Ра́дуйся, я́ко спасе́нія іски́й, во страну́ чужду́ю стопи́ твоя́ упра́вил єси́.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дів, я́ко ма́ти і бра́тія твоя́ восхоті́ша бра́ку тя вда́ти, і чистоту́ ді́вства па́че возлюби́в, дом оте́чеський оста́вил єси́ і стра́нник би́ти предсуди́л єси́, да сподо́бишися ві́чно пі́ти Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в ко́зні, от врага́ спасе́нія на́шего содіва́ємия, терпі́ніє, поще́ніє і моли́тву к Бо́гу проти́ву поста́вил єси́, всеблаже́нне о́тче, і я́ко нищ ду́хом же і ті́лом, от гра́да во град і от ві́си во весь преходи́л єси́ і во о́них примета́тися ко хра́мом Госпо́днім возлюби́л єси́. Сего́ ра́ди зове́м ті:","Ра́дуйся, вся кра́сная ми́ра сего́ ні во что вміни́вий.","Ра́дуйся, нищету́ тіле́сную і духо́вную возлюби́вий.","Ра́дуйся, ру́бища ве́тхая, я́ко оде́жду драгую, на ті́лі своє́м носи́вий.","Ра́дуйся, а́лчбою і жа́ждею, мра́зом і зно́єм ті́ло твоє́ ізнури́вий.","Ра́дуйся, ча́шу поруга́нія пра́вди ра́ди до конця́ іспи́вий.","Ра́дуйся, за творя́щия ті напа́сть, я́ко за благотворця Го́споду моли́вийся.","Ра́дуйся, терпі́нієм твої́м ми́ра сего́ зло́бу побіди́вий.","Ра́дуйся, огне́м моли́тви твоєя́ вся стрі́ли лука́ваго попали́вий.","Ра́дуйся, си́лою твоє́ю ві́ри язи́чеськая суєві́рія потреби́вий.","Ра́дуйся, красоту́ селе́нія Бо́жия возлюби́вий.","Ра́дуйся, примета́тися в до́му Бо́жії ізво́ливий.","Ра́дуйся, я́ко стра́нник і пришле́ць бив на землі́, ни́ні в оби́теліх небе́сних всели́лся єси́.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия даде́ся ті, преподо́бне, єгда́ в честні́м стра́нствії твоє́м ні́коєго младе́нця і́менем Тимофе́я, не́мощію лю́тою одержи́ма і близ коне́чнаго іздиха́нія би́вша, моли́твами твої́ми ісціли́л єси́, і здра́ва того́ сотвори́в, ку́пно с роди́телі і при́сними єго́ воспі́л єси́ укріпля́ющему ті Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і ду́шу непоро́чну, блаже́нне о́тче, уразумі́л єси́ суєту́ ми́ра сего́ і непостоя́нство, і ві́чних благ возжелі́в, ми́ра сего́ отре́клся єси́ і постриже́ніє і́ночеськоє прия́л єси́. Ті́мже ублажа́єм тя, преподо́бне о́тче, і сла́в'яще є́же о тебі́ ізволе́ніє Бо́жиє, вопіє́м ті си́це:","Ра́дуйся, я́ко земна́я отри́нув, умо́м твої́м к небе́сним восте́кл єси́.","Ра́дуйся, я́ко к ви́шнім тече́ніє своє́ ви́ну упра́вил єси́.","Ра́дуйся, смире́ніє возлюби́вий.","Ра́дуйся, послуша́нія рачи́телю.","Ра́дуйся, моли́тв кади́ло благоприя́тноє.","Ра́дуйся, слез покаянних неоску́дний істо́чниче.","Ра́дуйся, благо́є і́го Христо́во на себі́ возложи́вий.","Ра́дуйся, на висоту́ безстра́стія возше́дий.","Ра́дуйся, всего́ себе́ Бо́гу преда́вий.","Ра́дуйся, от сме́рти напра́сния ізволе́нієм Бо́жиїм ди́вно сохраненний.","Ра́дуйся, явле́нієм святи́теля Никола́я обра́дованний.","Ра́дуйся, от неду́га лю́таго їм ісцеленний.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю іскуше́ній і бід от челові́к, зло́бних на тя свята́го ра́ди житія́ твоєго́, преподо́бне о́тче, с кро́тостію претерпіва́я і єди́наго то́лько на потре́бу іща́, є́же ка́ко Бо́гові угоди́ти, Бо́гом води́мий, дости́гл єси́ В'я́тськия страни́, і во гра́ді Хлинове оби́тель во сла́ву Богоро́диці созда́в, в ней с ли́ки і́ночествующих немо́лчно вопія́л єси́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше христоимени́тії лю́діє гра́да Хлинова, я́ко оби́телі іночестей близ гра́да того́ основа́ніє положи́л єси́, Три́фоне богоно́сне, возра́довашася ра́достію ве́лію, і я́ко а́нгела Бо́жия тя почита́ху, служа́ще от імі́ній свої́х к устроє́нію о́ния оби́телі і вопія́ху тебі́ си́це:","Ра́дуйся, та́йнаго велі́нія Бо́жия послушавий.","Ра́дуйся, Авраа́ма ві́рі поревнова́вий.","Ра́дуйся, во страну́ В'ятськую путь свой благоче́стне упра́вивий.","Ра́дуйся, оби́тель і́ночеськую та́мо созда́ти зіло́ восхоті́вий.","Ра́дуйся, хра́ми Бо́жія в ней благолі́пно устро́ївий.","Ра́дуйся, чудеса́ пресла́вная при основа́нії оби́телі соверши́вий.","Ра́дуйся, я́ко Моїсей моли́твами во́ду істочи́вий.","Ра́дуйся, Богоро́диці заступле́нію і покро́ву оби́тель твою́ вда́вий.","Ра́дуйся, ли́ка і́ночеськаго предстоя́телю богому́дрий.","Ра́дуйся, гра́да Хлинова свято́є украше́ніє і покро́ве, Бо́гом да́нний.","Ра́дуйся, сотвори́вий во́лю Госпо́дню і і́ни твори́ти научи́вий.","Ра́дуйся, сего́ ра́ди ве́лій в Ца́рствії Небе́сном нарече́нний.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготечно, я́ко світоза́рная звізда́, ше́ствовал єси́, уго́дниче Бо́жий, в престо́льний град Москву́, поле́зная оби́телі твоє́й та́мо устроя́я і от святі́йшаго патріа́рха І́ова в архімандрі́та поста́влен бив, с ми́лостинею мно́гою от благові́рнаго царя́ Фео́дора дарова́нною, в оби́тель твою́ па́ки возврати́лся єси́, благода́рственно воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів враг спасе́нія на́шего оби́тель твою́ до́брі устрояєму от тебе́, преподо́бне о́тче, воздви́же на тя ні́киїх от учени́к твої́х, і́же проти́ву тебе́ возставше, от оби́телі твоєя́ тя отгна́ша. Ти же, на землі́ сіє́ ізгна́ніє с кро́тостію приє́мий, ни́ні же всели́вийся в оби́теліх небе́сних, усли́ши нас, пою́щих ті сицева́я:","Ра́дуйся, я́ко за блага́я ко спасе́нію словеса́ поруга́ніє приє́мий.","Ра́дуйся, а́ки кро́ткий а́гнець вся терпі́вий.","Ра́дуйся, с небесе́ утіше́ніє приє́мий.","Ра́дуйся, молча́нієм на укори́зни отвещавий.","Ра́дуйся, во ізгна́ніє незло́биво отше́дий.","Ра́дуйся, любо́вію Христо́вою ко́зні вра́жия побіди́вий.","Ра́дуйся, мно́гі оби́телі і́ночеськия во стра́нствії твоє́м посіти́вий.","Ра́дуйся, в них себі́ утіше́ніє і отра́ду обріти́й.","Ра́дуйся, чудеса́ ди́вная во ізгна́нії твоє́м соверши́вий.","Ра́дуйся, мно́гі на путь і́ночеськаго житія́ наста́вивий.","Ра́дуйся, блаже́ннаго Проко́пія на по́двиг юро́дства о Христі́ благослови́вий.","Ра́дуйся, я́ко сий на землі́ я́ві с небожители бесі́довал єси́.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть при́сно страна́ В'ятськая по́двиги і труди́ твоя́, преподо́бне, в страна́х Арха́нгельських, Устю́жських, пермських, і сві́тло красу́ється, стяжа́вши тя помо́щника і покрови́теля себі́ осо́бні. Мо́лим у́бо тя, свя́тче Бо́жий, не лиши́ і нас грі́шних небе́сния твоєя́ по́мощі і покро́ва моли́тв твої́х, к твоєму́ бо заступле́нію в ско́рбіх на́ших вседу́шно прибіга́єм і просла́вльшему тя Го́споду со умиле́нієм зове́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, преподо́бне, я́ко звізда́ богосві́тлая, во гра́ді Слободстем, вонь же по ізгна́нії твоє́м прише́д, оби́тель Богоявле́нія Госпо́дня созда́л єси́ і та́мо всели́лся єси́, всіх озаря́я свя́тостію житія́ своєго́. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, гра́ду Слободському прише́ствієм твої́м благослове́ніє от Го́спода низпосла́вий.","Ра́дуйся, жи́телем гра́да того́ світи́льник пресві́тел би́вий.","Ра́дуйся, от них ра́достно прия́тий.","Ра́дуйся, любо́вію їх уті́шенний.","Ра́дуйся, оби́тель і́ночеськую та́мо до́брі устро́ївий.","Ра́дуйся, ми́лостиню на устроє́ніє єя́ мно́гу собра́вий.","Ра́дуйся, ти́хоє в ней приста́нище обріти́й.","Ра́дуйся, при́сно в ней в труді́ і моли́тві пребива́вий.","Ра́дуйся, і зді і́ноков богоми́слію поучавий.","Ра́дуйся, ученика́ твоєго́ Досифе́я ко спасе́нію наставля́вий.","Ра́дуйся, путь терпі́нія і́ночеськаго тому́ показа́вий.","Ра́дуйся, о́бразе ві́ри і любве́ і а́нгельськаго житія́ в подража́ніє ученико́м твої́м оста́вивий.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́но імі́л єси́, преподо́бне, є́же ви́діти созда́нную от тебе́ оби́тель Богоро́диці во гра́ді Хлинове. Сего́ ра́ди вість от Бо́га приє́м, я́ко близ єсть кончи́на твоя́, от оби́телі Солове́цькия, єя́же в стра́нствії своє́м богоугодієм дости́гл єси́, па́ки во град Хлинов стопи́ твоя́ упра́вил єси́, да та́мо во оби́телі твоє́й, преда́си дух твой Бо́гу, Єму́же от ю́ности твоєя́ нави́кл єси́ пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно бисть, уго́дниче Бо́жий, прише́ствіє твоє́ во град Хлинов, єгда́ тя ве́тха денми су́ща і тіле́сною не́мощію одержи́ма, бра́тія оби́телі твоєя́ отри́нуша, посліди́ же, пред кончи́ною твоє́ю свято́ю, гні́ва Бо́жия убоя́вшеся і терпі́нієм твої́м побіжде́ні би́вше, раскаяхуся і в оби́тель твою́ с любо́вію тя прияху. Ми же таково́му незло́бію твоєму́ див'я́щеся, вопіє́м ті:","Ра́дуйся, о́тче благосе́рдий, враждовавшия на тя любо́вію Христо́вою возлюби́вий.","Ра́дуйся, гнів на воздви́гших гоне́ніє на тя соверше́нно в себі́ умертви́вий.","Ра́дуйся, до конця́ оби́тель твою́ возлюби́вий.","Ра́дуйся, па́ки в ней ра́достно і ми́рно водворивийся.","Ра́дуйся, в затво́рі келе́йнім в ней уєдинивийся.","Ра́дуйся, посто́м і моли́твою к ісхо́ду із ми́ра сего́ в нем уготовлявийся.","Ра́дуйся, бра́тію твою́ пред ісхо́дом от житія́ сего́ благослови́вий.","Ра́дуйся, поуче́ніє от Писа́нія боже́ственнаго їм преподавий.","Ра́дуйся, тім блага́я за зло возда́вий.","Ра́дуйся, при ісхо́ді твоє́м от вре́меннаго житія́ прича́стія Боже́ственних Та́їн сподо́бивийся.","Ра́дуйся, от уз ті́ла разріши́тися і со Христо́м би́ти жела́ніє всегда́ імі́вий.","Ра́дуйся, о Нем єди́нім при́сно воздихавий.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є сконча́вшу ті, Три́фоне приснопа́м'ятне, благоуха́нія ди́внаго іспо́лнися келлія твоя́: вери́ги же та́йно тобо́ю носи́мия, спадо́ша с твоєго́ тілесе́, і зрак лиця́ твоєго́ просвіти́ся, я́ко всім, ви́дівшим ісхо́д твой, диви́тися зіло́ і возопи́ти ко Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся бра́тія оби́телі твоєя́, преблаже́нне, со освяще́нним собо́ром і людьми́ мно́гими со слеза́ми і пі́нії надгробними ізнесо́ша всечестно́є ті́ло твоє́ ко гро́бу, тобо́ю в хра́мі Пресвяти́я Богоро́диці угото́ванному, іді́же о́ноє, я́ко сокро́вище духо́вноє, че́стно положи́ша. Ми же у ра́ки твоєя́ святи́я вопіє́м ті с любо́вію такова́я:","Ра́дуйся, во благоуха́нії святи́ні сном сме́рти опочивий.","Ра́дуйся, смерть вкуси́вий, тлі́нія же не позна́вий.","Ра́дуйся, в ри́зу нетлі́нія благода́тію Бо́жиєю облече́нний.","Ра́дуйся, чудеси́ мно́гими от Бо́га по сме́рті просла́вленний.","Ра́дуйся, я́ко честна́я ра́ка твоя́ враче́бниця бисть всім неду́гующим.","Ра́дуйся, я́ко всяк, приходя́й к ней с ві́рою, приє́млеть да́ри ціле́бния.","Ра́дуйся, разсла́бленних укріпи́телю.","Ра́дуйся, бісну́ющихся от наси́лія дия́вольськаго свободи́телю.","Ра́дуйся, сліпи́м зрі́ніє возвраща́яй.","Ра́дуйся, хроми́м є́же пра́во ходи́ти устроя́яй.","Ра́дуйся, німи́м проглаголаніє да́руяй.","Ра́дуйся, неісці́льния я́зви ди́вно врачу́яй.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["А́нгели Небе́снії ра́достно прия́ша чи́стую ду́шу твою́, преподо́бне, во оби́телі ра́йськия, іді́же Цар Сла́ви Христо́с Госпо́дь вінча́ тя вінце́м небе́сним, єго́же угото́ва всім, возлю́бльшим явле́ніє Єго́, і дарова́ нам тебе́ засту́пника і моли́твенника блага́го, да благода́рно поє́м Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовещанії не возмо́гуть по достоя́нію воспіва́ти сла́ву, от Го́спода угото́ванную святи́м Єго́ во Ца́рствії Небе́снім, єя́же наслі́дник сподо́бился єси́ би́ти, Три́фоне преблаже́нне. Сея́ сла́ви соприча́стники би́ти і нас сподо́би, уго́дниче Бо́жий, святи́ми твої́ми о нас к Бо́гу моли́твами, да ра́достно вопіє́м ті:","Ра́дуйся, ликовству́яй в черто́зі Небе́снаго Домовлади́ки.","Ра́дуйся, граждани́не Ієрусали́ма го́рняго.","Ра́дуйся, свя́тче Бо́жий, со всі́ми святи́ми прославля́ємий.","Ра́дуйся, от го́рних висо́т к нам земноро́дним ми́лостивно приникаяй.","Ра́дуйся, оби́тель твою́ і град наш при́сно сохраня́яй.","Ра́дуйся, в со́ніїх і виді́ніїх ві́рним явля́яйся.","Ра́дуйся, сі́верния і В'я́тськия страни́ небе́сний осо́бні покрови́телю.","Ра́дуйся, гра́да Хлинова неотсту́пний храни́телю.","Ра́дуйся, всіх скорб'я́щих утіше́ніє.","Ра́дуйся, всіх притека́ющих к тебі́ ско́роє усли́шаніє.","Ра́дуйся, предста́телю наш благи́й.","Ра́дуйся, хода́таю о нас пред Бо́гом немо́лчний.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спаси́тельний зало́г Бо́жия благода́ті святи́я мо́щі твоя́, преподо́бне, по лі́тіх мно́зіх обрі́тени би́ша нетлі́нни і в но́вім хра́мі Богоро́диці че́стне от святи́теля Іо́ни положе́ні би́ша, і́же с бра́тією оби́телі і всім мно́жеством благогові́йні лобиза́ху о́ния, ра́достно поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв твої́х, преподо́бне, огради́ нас от вся́ких бід і скорбе́й, тебі́ бо стяжа́хом засту́пника тве́рдаго і предста́теля о нас пред Бо́гом неусипнаго, да огражда́єми твої́м заступле́нієм, си́це тебі́ зове́м:","Ра́дуйся, в біда́х і обстоя́ніїх ско́рий помо́щниче.","Ра́дуйся, призива́ющим тя усе́рдний засту́пниче.","Ра́дуйся, почита́ющих тя проше́нія ско́ро ісполня́яй.","Ра́дуйся, мно́гажди проше́ніє по́мощію твоє́ю предваривий.","Ра́дуйся, в ми́лостіх неістощи́мий.","Ра́дуйся, скорб'я́щих прибі́жище те́плоє.","Ра́дуйся, печа́льних утіше́ніє.","Ра́дуйся, оби́димих засту́пниче.","Ра́дуйся, от бід і скорбе́й нас ско́ро ізбавля́яй.","Ра́дуйся, я́ко непреста́нною моли́твою о нас Бо́га умилостивля́єши.","Ра́дуйся, сосу́де честни́й, єле́й ми́лости Бо́жия к нам содержаяй.","Ра́дуйся, звіздо́ сві́тлая, путь к Ца́рствію Бо́жию нам указу́ющая.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, преподо́бне, пред ра́кою твоє́ю свято́ю предстоя́ще, і мо́лимся ті прилі́жно: я́коже отрокови́цю, біснова́нієм одержи́мую, ми́лостивно ісціли́л єси́, та́ко і нас, страстьми́ многоразли́чними неду́гующих, посіти́ і да́нною ті от Бо́га благода́тію ісціли́, да ра́достно поє́м просла́вльшему ті Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельна світи́льника тя ві́ми, о́тче, Престо́лу Бо́жию предстоя́ща і мрак страсте́й і гріхо́в на́ших луча́ми моли́тв разгоня́юща. Озари́ у́бо от го́рних висо́т і на́ша се́рдця, всеблаже́нне, да досточестно вопіє́м ті си́це:","Ра́дуйся, сві́та Тро́їчеськаго зри́телю.","Ра́дуйся, небе́снаго Сіо́на жи́телю.","Ра́дуйся, го́рняго ми́ра блаже́нний обита́телю.","Ра́дуйся, при́сно созерца́яй пресві́тлоє лице́ Влади́ки Христа́.","Ра́дуйся, немо́лчно воспіва́яй трисвяту́ю піснь Тро́йце.","Ра́дуйся, луче́ пресві́тлая, от Со́лнця Христа́ возсія́вшая.","Ра́дуйся, я́ко і по преставле́нії твоє́м с на́ми пребива́єши.","Ра́дуйся, в моли́твах твої́х о нас к Бо́гу те́плий предста́телю.","Ра́дуйся, страну́ В'ятськую зіло́ возлюби́вий.","Ра́дуйся, мо́щі твоя́ святи́я єй в наслі́діє оста́вивий.","Ра́дуйся, сокро́вище неоску́дноє мно́гих ісціле́ній.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́ нам, преподо́бне, у Христа́ і Бо́га на́шего і моли́твенник усе́рдний бу́ди о нас ко Го́споду, да утверди́вшеся в за́повідіх Єго́, полу́чим спасе́ніє ві́чноє і та́ко при́сно поє́м Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги преди́внаго житія́ твоєго́ і сла́в'яще чудеса́ твоя́, преподо́бне, любо́вію ублажа́єм тя, я́ко многомо́щна моли́твенника о нас і прдстателя пред Го́сподем на́шим. Ти же о свя́тче Бо́жий, я́ко благоутро́бен, принеси́ моле́ніє те́плоє о нас ко Влади́ці, да сподо́бит нас Небе́снаго Ца́рствія Своєго́, вопію́щих ті с любо́вію такова́я:","Ра́дуйся, Пресвяти́я Тро́йці служи́телю ві́рний.","Ра́дуйся, благода́тію Ду́ха Свята́го приосіне́нний.","Ра́дуйся, Пресвяти́я Богоро́диці слуго́ ізря́дний.","Ра́дуйся, а́нгелом собесі́дниче преди́вний.","Ра́дуйся, со апо́столи ликовству́яй у Престо́ла Царя́ Сла́ви.","Ра́дуйся, му́ченик добропобі́дних сострада́льче.","Ра́дуйся, преподо́бних подража́телю ві́рний.","Ра́дуйся, всіх святи́х Бо́жиїх сонаслі́дниче.","Ра́дуйся, о грі́шних всегда́ Бо́га умоля́яй.","Ра́дуйся, ду́ші і тілеса́ на́ша благода́тію Бо́жиєю ісціля́яй.","Ра́дуйся, по Бо́зі на тя упова́ніє возлага́ющих не посрамля́яй.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче і пресла́вний чудотво́рче, преподо́бне о́тче наш Три́фоне! Ми́лостивно прийми́ сіє́ ма́лоє моле́ніє на́ше, в похвалу́ тебі́ приноси́моє, і предстоя́ Престо́лу Царя́ Сла́ви, умоли́ Го́спода, да сохрани́ть нас от враг ви́димих і неви́димих, от неду́га і гла́да, от напа́сти і ско́рби і ві́чнаго муче́нія ізба́вить, да сподо́бимся вку́пі с тобо́ю ра́дості святи́х ві́чно воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела тя во пло́ті су́ща позна́вше, преподо́бне, і ве́лія благодія́нія от тебе́ приє́мше, я́ко чудотво́рця пресла́внаго тя сла́вим і си́це тебі́ со умиле́нієм зове́м:","Ра́дуйся, сі́верния страни́ благоуха́нний кри́не.","Ра́дуйся, о́трасле благочести́ваго ко́рене.","Ра́дуйся, от мла́дости в добро́м наказа́нії воспита́нний.","Ра́дуйся, ізді́тська сопричтенний в синовство́ Отцю́ Небе́сному.","Ра́дуйся, благочести́вия ма́тере твоєя́ отра́до і утіше́ніє.","Ра́дуйся, бра́тію і сро́дники твоя́ свої́м благоче́стієм удиви́вий.","Ра́дуйся, целому́дріє ді́вства невреди́мо сохрани́вий.","Ра́дуйся, от се́рдця твоєго́ вся іскуше́нія ю́ности отгна́вий.","Ра́дуйся, к Бо́гу імі́вий раче́ніє ве́ліє.","Ра́дуйся, Го́спода ра́ди путь ті́сний і ско́рбний ізбра́вий.","Ра́дуйся, до́льняя го́рняго ра́ди оста́вивий.","Ра́дуйся, я́ко спасе́нія іски́й, во страну́ чужду́ю стопи́ твоя́ упра́вил єси́.","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і чудотво́рче, преподо́бне о́тче Три́фоне, свя́тостію житія́ і чудеси́ твої́ми возсія́вий страні́ В'ятстей, я́ко звізда́ богосві́тлая! Похва́льная воспису́єм ті, любо́вію творя́щії всечестну́ю па́м'ять твою́: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Три́фоне, пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче наш Три́фоне! Земни́й а́нгеле і небе́сний челові́че, світи́льниче пресві́тлий, страну́ В'ятськую озаря́яй чудеси́, гра́ду на́шему стіно́ і утвержде́ніє, бедствующим крі́пкий помо́щниче, оби́телі твоєя́ до́брий храни́телю, при́сний о нас к Бо́гу моли́твенниче і те́плий о душа́х на́ших хода́таю! Тебі́, уго́дниче Бо́жий, неістощи́моє от Всеблага́го Влади́ки благода́ті і даро́в даде́ся сокро́вище, є́же ціли́ти неду́ги тіле́сния і отгоня́ти стра́сті душе́вния і от всіх зол ізбавля́ти с ві́рою і́м'я твоє́ призива́ющих. К тебі́ у́бо прибіга́єм і тебі́ припа́дающе мо́лимся: не пре́зри нас, моля́щихся тебі́ і твоєя́ прося́щих по́мощі, ізба́ви нас от враг ви́димих і неви́димих, зави́стно на ни возстаю́щих і я́ростію зверською поглоти́ти хотя́щих, ізми́ нас неви́димим предста́тельством твої́м от смуще́нія і бу́ри і тьмочисленних скорбе́й на́ших, за гріхи́ на́ша нам прибива́ющих. О преди́вний і богоно́сний о́тче наш Три́фоне! Ско́ро потщи́ся на по́мощ на́шу. Вознеси́ благомо́щную моли́тву твою́ ко Го́споду сил: стра́ждущую страну́ Украї́нськую от лю́тих безбо́жник і вла́сті їх Госпо́дь да свободи́ть, і да возста́вить престо́л правосла́вних правителей; ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш, да потреби́ть Госпо́дь от землі́ на́шея вся неі́стовия крамоли́, і утверди́ть в ней безм'яте́жіє, мир і благоче́стіє, да сохрани́ть оби́тель твою́ святу́ю, град наш і вся гра́ди і ве́сі страни́ на́шея от гла́да і губи́тельства, от м'яте́жа і нестроє́нія, от запале́нія і бу́ри, от нападе́ній вра́жиїх і от тлітво́рних вітр і от вся́каго зла. Уми́лостиви о нас благоприя́тними моли́твами твої́ми Христа́ Бо́га на́шего, є́же ізба́витися нам от гріх на́ших і наві́тов вра́жиїх, я́ко да заступле́нієм твої́м і по́мощію в ми́рі і тишині́ богоуго́дні зді на землі́ поживе́м, і в бу́дущем ві́ці да сподо́бимся ча́сти святи́х Го́сподем на́шим Ісу́сом Христо́м, Єму́же подоба́єть і честь і поклоне́ніє, ни́ні і во вся ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко світоза́рная звізда́, / возсія́л єси́ от восто́ка до за́пада, / оста́вль бо своє́ оте́чество, / доше́л єси́ В'я́тськия страни́ і Богоспаса́ємаго гра́да Хли́нова, / в не́мже оби́тель во сла́ву Пресвяти́я Богоро́диці созда́в, / і, та́мо на доброді́тель впери́вся, / собра́л єси́ і́ночествующих мно́жество, / і, сих наставля́я на путь спасе́нія, / бил єси́ А́нгелом собесі́дник, / і по́стником соприча́стник, Три́фоне преподо́бне, // с ни́ми Христа́ Бо́га моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["От земни́х на Небе́сная поми́слив, / і́ночеськоє житіє́ ізмла́да, преподо́бне, возлюби́в, / і ді́лом соверши́в ко Го́споду любо́в, / і тве́рдим умо́м Єго́ Духнове́нним уче́нієм озаря́я мир, / і, возлюби́в, блаже́нне, всено́щноє бді́ніє / і моли́тву непреста́нну, і наставле́нія Боже́ственнаго ра́зума, / і́нок ста́до собра́, му́дре, / і наста́вил єси́ ко сві́ту Богоразу́мія, Три́фоне о́тче наш, // Христа́ Бо́га моли́ дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Днесь в нача́лі основа́нія доброді́телем, блаже́нне, / положи́л єси́ в душі́ своє́й страх Бо́жий, / от ю́ности взем крест свой, / благоче́стно Христо́ві послі́довал єси́, / А́нгельським о́бразом облече́ся і бисть мона́х преди́вен, / в доброді́теліх цветя́ше, к бу́дущим Бо́гові простира́лся. / І своє́й пло́ті, я́ко врагу́, неми́лостив, о́тче, бил єси́, / терпі́нієм яви́ся, блаже́нне, я́ко зла́то іскуше́но в горни́лі, / но і ни́ні не забу́ди посіща́ти чад свої́х, / помина́й нас, чту́щих пресвяту́ю па́м'ять твою́, / да всі благодари́во вопіє́м ті: // ра́дуйся, прему́дре Три́фоне, наста́вниче мона́хом."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Три́фоне, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче а́нгелов."]}],"notes":[]}];
export default D;
